-- Practice 283: Part 1 (Questions 1 to 95)
-- Table: public.question_explanations

INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-1', 'practice_283', 'Công ty đang áp dụng lợi thế nào của điện toán đám mây khi sử dụng AWS Region để tăng tính khả dụng của ứng dụng cho người dùng ở các quốc gia khác nhau?', 'Domain 1: Cloud Concepts', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Phạm vi tiếp cận toàn cầu là lợi thế của điện toán đám mây mà một công ty có thể áp dụng khi sử dụng AWS Region để tăng tính khả dụng của ứng dụng cho người dùng ở các quốc gia khác nhau. Phạm vi tiếp cận toàn cầu đề cập đến khả năng triển khai các ứng dụng và dịch vụ ở nhiều vị trí địa lý trên khắp thế giới và phục vụ khách hàng với độ trễ thấp và hiệu suất cao. AWS có cơ sở hạ tầng toàn cầu lớn nhất và đáng tin cậy nhất so với bất kỳ nhà cung cấp đám mây nào, với 25 Khu vực và 81 Availability Zone (AZ) trên khắp Châu Mỹ, Châu Âu, Châu Á Thái Bình Dương, Châu Phi và Trung Đông123. Bằng cách sử dụng AWS Region, công ty có thể chọn vị trí tốt nhất cho ứng dụng của mình dựa trên khoảng cách gần với khách hàng, yêu cầu tuân thủ và chiến lược khắc phục thảm họa23.', '[{"label": "A", "text_vi": "Định giá thanh toán theo nhu cầu sử dụng", "is_correct": false, "analysis_vi": "Sai. Định giá thanh toán theo nhu cầu sử dụng: Mô hình trả tiền theo mức dùng thực tế (Pay-as-you-go) giúp doanh nghiệp chuyển đổi chi phí đầu tư vốn lớn (CapEx) sang chi phí vận hành linh hoạt (OpEx). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Dự báo công suất", "is_correct": false, "analysis_vi": "Sai. Dự báo công suất: Điện toán đám mây giúp bạn ''ngừng đoán định công suất'' (Stop guessing capacity), loại bỏ lãng phí tài nguyên hoặc nguy cơ quá tải. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Tính kinh tế của quy mô", "is_correct": false, "analysis_vi": "Sai. Tính kinh tế của quy mô: Tính kinh tế nhờ quy mô khổng lồ (Massive economies of scale) cho phép AWS tổng hợp nhu cầu của hàng triệu khách hàng để hạ giá thành dịch vụ liên tục. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Phạm vi tiếp cận toàn cầu", "is_correct": true, "analysis_vi": "Đúng. Phạm vi tiếp cận toàn cầu là đáp án chính xác. Phạm vi tiếp cận toàn cầu là lợi thế của điện toán đám mây mà một công ty có thể áp dụng khi sử dụng AWS Region để tăng tính khả dụng của ứng dụng cho người dùng ở các quốc gia khác nhau."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
