INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-2', 'practice_283', 'Một ứng dụng đang chạy trên nhiều phiên bản Amazon EC2. Công ty muốn làm cho ứng dụng có tính sẵn sàng cao bằng cách định cấu hình Load Balancer (ELB) với các yêu cầu được chuyển tiếp đến phiên bản EC2 dựa trên đường dẫn URL. Load Balancer (ELB) AWS nào sẽ đáp ứng các yêu cầu này và tốn ít công sức nhất để triển khai?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'Câu trả lời đúng là B vì Cân bằng tải ứng dụng là cân bằng tải AWS sẽ đáp ứng các yêu cầu và tốn ít công sức nhất để triển khai. Cân bằng tải ứng dụng là một loại Cân bằng tải đàn hồi hoạt động ở lớp ứng dụng (lớp 7) của mô hình OSI và định tuyến các yêu cầu đến các mục tiêu dựa trên nội dung của yêu cầu. Cân bằng tải ứng dụng hỗ trợ các tính năng nâng cao, chẳng hạn như định tuyến dựa trên đường dẫn, định tuyến dựa trên máy chủ và định tuyến dựa trên tiêu đề HTTP. Các tùy chọn khác không chính xác vì chúng không phải là Load Balancer (ELB) AWS sẽ đáp ứng yêu cầu và tốn ít công sức nhất để triển khai. Network Load Balancer là một loại Cân bằng tải đàn hồi hoạt động ở lớp truyền tải (lớp 4) của mô hình OSI và định tuyến các yêu cầu đến mục tiêu dựa trên địa chỉ IP và cổng đích. Network Load Balancer không hỗ trợ định tuyến dựa trên đường dẫn. AWS OpsWorks Load Balancer không phải là Load Balancer (ELB) AWS mà là một tính năng của AWS OpsWorks cho phép người dùng gắn Load Balancer (ELB) Elastic Load Balancing vào một lớp trong ngăn xếp của họ. Cân bằng tải tùy chỉnh trên Amazon EC2 không phải là cân bằng tải AWS mà là cân bằng tải do người dùng xác định chạy trên phiên bản Amazon EC2. Cân bằng tải tùy chỉnh trên Amazon EC2 đòi hỏi nhiều nỗ lực hơn để triển khai và duy trì so với cân bằng tải AWS.', '[{"label": "A", "text_vi": "Cân bằng tải mạng", "is_correct": false, "analysis_vi": "Sai. Cân bằng tải mạng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Cân bằng tải ứng dụng", "is_correct": true, "analysis_vi": "Đúng. Cân bằng tải ứng dụng là đáp án chính xác. Câu trả lời đúng là B vì Cân bằng tải ứng dụng là cân bằng tải AWS sẽ đáp ứng các yêu cầu và tốn ít công sức nhất để triển khai."}, {"label": "C", "text_vi": "Cân bằng tải AWS OpsWorks", "is_correct": false, "analysis_vi": "Sai. Cân bằng tải AWS OpsWorks không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Cân bằng tải tùy chỉnh trên Amazon EC2", "is_correct": false, "analysis_vi": "Sai. Cân bằng tải tùy chỉnh trên Amazon EC2: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
