INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-3', 'practice_283', 'Nguyên tắc thiết kế nào sau đây được đề xuất của Khung kiến trúc tối ưu AWS?', 'Domain 1: Cloud Concepts', 'Cloud Concepts', 'Câu trả lời đúng là C vì học cách cải thiện từ các lỗi vận hành là nguyên tắc thiết kế được đề xuất của Khung kiến trúc tối ưu AWS. Khung kiến ​​trúc tối ưu AWS là một tập hợp các biện pháp thực hành và hướng dẫn tốt nhất để thiết kế và vận hành các hệ thống đáng tin cậy, an toàn, hiệu quả và tiết kiệm chi phí trên đám mây. Khung kiến ​​trúc tối ưu AWS bao gồm năm trụ cột: vận hành xuất sắc, bảo mật, độ tin cậy, hiệu quả hoạt động và tối ưu hóa chi phí. Mỗi trụ cột có một bộ nguyên tắc thiết kế mô tả các đặc điểm của một hệ thống được kiến ​​trúc tốt. Học cách cải thiện từ những sai sót trong vận hành là nguyên tắc thiết kế của trụ cột vận hành xuất sắc, tập trung vào việc vận hành và giám sát các hệ thống để mang lại giá trị kinh doanh và liên tục cải tiến các quy trình và thủ tục hỗ trợ. Các tùy chọn khác không chính xác vì chúng không phải là nguyên tắc thiết kế được đề xuất của Khung kiến ​​trúc tối ưu AWS. Giảm thời gian ngừng hoạt động bằng cách thực hiện các thay đổi cơ sở hạ tầng không thường xuyên và với số lượng lớn không phải là nguyên tắc thiết kế của Khung kiến ​​trúc tối ưu AWS mà là nguồn gốc của rủi ro và kém hiệu quả. Một hệ thống có kiến ​​trúc tốt nên thực hiện các thay đổi thường xuyên và theo từng bước nhỏ để giảm thiểu tác động và phạm vi của lỗi. Đầu tư thời gian để định cấu hình cơ sở hạ tầng theo cách thủ công không phải là nguyên tắc thiết kế của Khung kiến ​​trúc tối ưu AWS mà là nguyên nhân gây ra lỗi và sự không nhất quán của con người. Một hệ thống có kiến ​​trúc tốt sẽ tự động hóa các tác vụ thủ công để cải thiện tốc độ và độ chính xác của các hoạt động. Sử dụng thiết kế ứng dụng nguyên khối để tập trung hóa không phải là nguyên tắc thiết kế của Khung kiến ​​trúc tối ưu AWS mà là nguyên nhân gây ra sự phức tạp và cứng nhắc. Một hệ thống có kiến ​​trúc tốt nên sử dụng các thành phần được phân phối và liên kết lỏng lẻo để có khả năng mở rộng và phục hồi.', '[{"label": "A", "text_vi": "Giảm thời gian ngừng hoạt động bằng cách thực hiện thay đổi cơ sở hạ tầng không thường xuyên và với mức độ lớn.", "is_correct": false, "analysis_vi": "Sai. Giảm thời gian ngừng hoạt động bằng cách thực hiện thay đổi cơ sở hạ tầng không thường xuyên và với mức độ lớn. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Đầu tư thời gian để cấu hình cơ sở hạ tầng theo cách thủ công.", "is_correct": false, "analysis_vi": "Sai. Đầu tư thời gian để cấu hình cơ sở hạ tầng theo cách thủ công.: AWS Config liên tục ghi lại và đánh giá các thay đổi cấu hình tài nguyên so với các quy tắc tuân thủ mong muốn. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Học cách cải thiện từ những thất bại trong vận hành.", "is_correct": true, "analysis_vi": "Đúng. Học cách cải thiện từ những thất bại trong vận hành. là đáp án chính xác. Câu trả lời đúng là C vì học cách cải thiện từ các lỗi vận hành là nguyên tắc thiết kế được đề xuất của Khung kiến trúc tối ưu AWS."}, {"label": "D", "text_vi": "Sử dụng thiết kế ứng dụng nguyên khối để tập trung hóa.", "is_correct": false, "analysis_vi": "Sai. Sử dụng thiết kế ứng dụng nguyên khối để tập trung hóa. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
