INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-4', 'practice_283', 'Một công ty đang chạy khối lượng công việc trên Đám mây AWS. Biện pháp thực hành tốt nhất nào của AWS đảm bảo kiến ​​trúc tiết kiệm chi phí NHẤT cho khối lượng công việc?', 'Domain 3: Cloud Technology and Services', 'Quản lý chi phí & Thanh toán AWS', 'Biện pháp tốt nhất của AWS nhằm đảm bảo kiến trúc tiết kiệm chi phí nhất cho khối lượng công việc là phân quyền. Quyền hóa có nghĩa là chọn loại phiên bản hoặc cấu hình tài nguyên phù hợp nhất phù hợp với nhu cầu của khối lượng công việc. Việc cấp quyền có thể giúp tối ưu hóa hiệu suất và giảm chi phí bằng cách tránh cung cấp quá mức hoặc cung cấp dưới mức tài nguyên1. Khớp nối lỏng lẻo, bộ nhớ đệm và dự phòng là các biện pháp thực hành tốt nhất khác của AWS có thể cải thiện khả năng mở rộng, độ sẵn sàng và hiệu suất của khối lượng công việc, nhưng chúng không nhất thiết đảm bảo kiến ​​trúc hiệu quả nhất về mặt chi phí.', '[{"label": "A", "text_vi": "Khớp nối lỏng lẻo", "is_correct": false, "analysis_vi": "Sai. Khớp nối lỏng lẻo, bộ nhớ đệm và dự phòng là các biện pháp thực hành tốt nhất khác của AWS có thể cải thiện khả năng mở rộng, độ sẵn sàng và hiệu suất của khối lượng công việc, nhưng chúng không nhất thiết đảm bảo kiến ​​trúc hiệu quả nhất về mặt chi phí.."}, {"label": "B", "text_vi": "Quyền hóa", "is_correct": true, "analysis_vi": "Đúng. Quyền hóa là đáp án chính xác. Biện pháp tốt nhất của AWS nhằm đảm bảo kiến trúc tiết kiệm chi phí nhất cho khối lượng công việc là phân quyền."}, {"label": "C", "text_vi": "Bộ nhớ đệm", "is_correct": false, "analysis_vi": "Sai. Bộ nhớ đệm không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Dự phòng", "is_correct": false, "analysis_vi": "Sai. Khớp nối lỏng lẻo, bộ nhớ đệm và dự phòng là các biện pháp thực hành tốt nhất khác của AWS có thể cải thiện khả năng mở rộng, độ sẵn sàng và hiệu suất của khối lượng công việc, nhưng chúng không nhất thiết đảm bảo kiến ​​trúc hiệu quả nhất về mặt chi phí.."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '[]'::jsonb, NOW())
