INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-5', 'practice_283', 'Một công ty muốn tạo một chatbot và tích hợp chatbot đó với ứng dụng web hiện tại của mình. Dịch vụ AWS nào sẽ đáp ứng những yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'The AWS service that will meet the requirements of the company that wants to create a chatbot and integrate the chatbot with its current web application is Amazon Lex. Amazon Lex là dịch vụ giúp khách hàng xây dựng giao diện đàm thoại bằng giọng nói và văn bản. The company can use Amazon Lex to create a chatbot that can understand natural language and respond to user requests, using the same deep learning technologies that power Amazon Alexa. Amazon Lex also provides easy integration with other AWS services, such as Amazon Comprehend, Amazon Polly, and AWS Lambda, as well as popular platforms, such as Facebook Messenger, Slack, and Twilio. Amazon Lex giúp khách hàng tạo các chatbot hấp dẫn và có tính tương tác cho ứng dụng web của họ. Amazon Kendra, Amazon Textract và Amazon Polly không phải là những dịch vụ tốt nhất để sử dụng cho mục đích này. Amazon Kendra là dịch vụ giúp khách hàng đưa ra câu trả lời chính xác và tự nhiên cho các truy vấn bằng ngôn ngữ tự nhiên bằng cách sử dụng máy học. Amazon Textract is a service that helps customers extract text and data from scanned documents using optical character recognition (OCR) and machine learning. Amazon Polly là dịch vụ giúp khách hàng chuyển đổi văn bản thành lời nói sống động như thật bằng cách sử dụng deep learning. These services are more useful for different types of natural language processing and generation tasks, rather than creating and integrating chatbots.', '[{"label": "A", "text_vi": "AmazonKendra", "is_correct": false, "analysis_vi": "Sai. AmazonKendra không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Amazon Lex", "is_correct": true, "analysis_vi": "Đúng. Amazon Lex đáp ứng đầy đủ yêu cầu của đề bài. The AWS service that will meet the requirements of the company that wants to create a chatbot and integrate the chatbot with its current web application is Amazon Lex."}, {"label": "C", "text_vi": "Văn bản Amazon", "is_correct": false, "analysis_vi": "Sai. Văn bản Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "AmazonPolly", "is_correct": false, "analysis_vi": "Sai. AmazonPolly không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
