INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-6', 'practice_283', 'Những nhiệm vụ nào thuộc trách nhiệm của khách hàng theo mô hình trách nhiệm chung của AWS? (Chọn HAI.)', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Câu trả lời đúng cho câu hỏi là B vì việc cung cấp quyền truy cập cho người dùng bằng AWS Identity and Access Management (IAM) là trách nhiệm của khách hàng theo mô hình trách nhiệm chung của AWS. Mô hình trách nhiệm chung của AWS là một khuôn khổ xác định sự phân chia trách nhiệm giữa AWS và khách hàng về vấn đề bảo mật và tuân thủ. AWS chịu trách nhiệm về tính bảo mật của đám mây, bao gồm cơ sở hạ tầng toàn cầu, chẳng hạn như các khu vực, Availability Zone (AZ) và vị trí biên; phần cứng, phần mềm, mạng và cơ sở vật chất chạy các dịch vụ AWS; và lớp ảo hóa phân tách phiên bản khách hàng và bộ lưu trữ. Khách hàng chịu trách nhiệm về bảo mật trên đám mây, bao gồm dữ liệu khách hàng, hệ điều hành khách, ứng dụng, quản lý danh tính và quyền truy cập, cấu hình tường lửa và mã hóa. IAM là dịch vụ AWS cho phép khách hàng quản lý quyền truy cập và quyền đối với các tài nguyên và dịch vụ AWS. Khách hàng chịu trách nhiệm tạo và quản lý người dùng, nhóm, vai trò và chính sách IAM, đồng thời đảm bảo rằng họ tuân theo nguyên tắc đặc quyền tối thiểu.', '[{"label": "A", "text_vi": "Xác định sự phụ thuộc của ứng dụng với hệ điều hành.", "is_correct": true, "analysis_vi": "Đúng. Xác định sự phụ thuộc của ứng dụng với hệ điều hành. là đáp án chính xác. Mô hình trách nhiệm chung của AWS là một khuôn khổ xác định sự phân chia trách nhiệm giữa AWS và khách hàng về vấn đề bảo mật và tuân thủ."}, {"label": "B", "text_vi": "Cung cấp quyền truy cập cho người dùng bằng AWS Identity and Access Management (IAM).", "is_correct": true, "analysis_vi": "Đúng. Cung cấp quyền truy cập cho người dùng bằng AWS Identity and Access Management (IAM). là đáp án chính xác. Câu trả lời đúng cho câu hỏi là B vì việc cung cấp quyền truy cập cho người dùng bằng AWS Identity and Access Management (IAM) là trách nhiệm của khách hàng theo mô hình trách nhiệm chung của AWS."}, {"label": "C", "text_vi": "Bảo mật trung tâm dữ liệu trong Availability Zone (AZ).", "is_correct": false, "analysis_vi": "Sai. Bảo mật trung tâm dữ liệu trong Availability Zone (AZ). không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Vá phần mềm ảo hóa.", "is_correct": false, "analysis_vi": "Sai. Vá phần mềm ảo hóa. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "E", "text_vi": "Cung cấp tính khả dụng của mạng trong Availability Zone (AZ).", "is_correct": false, "analysis_vi": "Sai. Cung cấp tính khả dụng của mạng trong Availability Zone (AZ). không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["AWS IAM"]'::jsonb, NOW())
