INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-7', 'practice_283', 'Một công ty bán lẻ gần đây đã chuyển trang web của mình sang AWS. Công ty muốn đảm bảo rằng nó được bảo vệ khỏi các cuộc tấn công tiêm nhiễm SQL. Trang web sử dụng Cân bằng tải ứng dụng để phân phối lưu lượng truy cập đến nhiều phiên bản Amazon EC2. Dịch vụ hoặc tính năng nào của AWS có thể được sử dụng để tạo quy tắc tùy chỉnh chặn các cuộc tấn công tiêm nhiễm SQL?', 'Domain 2: Security and Compliance', 'Dịch vụ điện toán đám mây Amazon EC2', 'AWS WAF là tường lửa ứng dụng web giúp bảo vệ các ứng dụng web hoặc API của bạn khỏi các hoạt động khai thác web phổ biến có thể ảnh hưởng đến tính khả dụng, xâm phạm bảo mật hoặc tiêu tốn quá nhiều tài nguyên. AWS WAF cung cấp cho bạn quyền kiểm soát cách lưu lượng truy cập đến ứng dụng của bạn bằng cách cho phép bạn tạo các quy tắc bảo mật chặn các kiểu tấn công phổ biến, chẳng hạn như chèn SQL hoặc tập lệnh chéo trang và các quy tắc lọc ra các mẫu lưu lượng truy cập cụ thể mà bạn xác định2. Bạn có thể sử dụng AWS WAF để tạo quy tắc tùy chỉnh chặn các cuộc tấn công chèn SQL vào trang web của bạn.', '[{"label": "A", "text_vi": "Security Group", "is_correct": true, "analysis_vi": "Đúng. Security Group là giải pháp đáp ứng yêu cầu. AWS WAF là tường lửa ứng dụng web giúp bảo vệ các ứng dụng web hoặc API của bạn khỏi các hoạt động khai thác web phổ biến có thể ảnh hưởng đến tính khả dụng, xâm phạm bảo mật hoặc tiêu tốn quá nhiều tài nguyên. Security Group là tường lửa ảo ở cấp instance, hoạt động có trạng thái (Stateful) và chỉ cấu hình các quy tắc cho phép (Allow rules)."}, {"label": "B", "text_vi": "AWS WAF", "is_correct": false, "analysis_vi": "Sai. AWS WAF: AWS WAF là tường lửa ứng dụng web hoạt động ở tầng 7 (HTTP/S), bảo vệ chống lại các lỗ hổng web phổ biến như SQL Injection và XSS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "ACL mạng", "is_correct": false, "analysis_vi": "Sai. ACL mạng: Network ACL là tường lửa ở cấp subnet, hoạt động không trạng thái (Stateless) và hỗ trợ cả quy tắc cho phép (Allow) lẫn từ chối (Deny). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Khiên AWS", "is_correct": false, "analysis_vi": "Sai. Khiên AWS: AWS Shield là dịch vụ phòng chống tấn công từ chối dịch vụ phân tán (DDoS), bản Standard miễn phí tích hợp sẵn và bản Advanced hỗ trợ phản ứng 24/7 từ đội SRT. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "AWS Shield", "AWS WAF"]'::jsonb, NOW())
