INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-8', 'practice_283', 'Dịch vụ hoặc công cụ AWS nào giúp quản lý tập trung việc thanh toán và cho phép quyền truy cập có kiểm soát vào các tài nguyên trên các tài khoản AWS?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'AWS Organs giúp quản lý tập trung việc thanh toán và cho phép truy cập có kiểm soát vào các tài nguyên trên các tài khoản AWS. AWS Organizations là dịch vụ cho phép người dùng hợp nhất nhiều tài khoản AWS thành một tổ chức có thể được quản lý dưới dạng một đơn vị duy nhất. AWS Organizations cho phép người dùng tạo nhóm tài khoản và áp dụng các chính sách cho chúng, chẳng hạn như chính sách kiểm soát dịch vụ (SCP) để chỉ định các dịch vụ và hành động mà người dùng và vai trò có thể truy cập trong tài khoản. AWS Organs cũng cho phép người dùng sử dụng tính năng thanh toán tổng hợp, kết hợp mức sử dụng và phí từ tất cả các tài khoản trong tổ chức vào một hóa đơn duy nhất.', '[{"label": "A", "text_vi": "Quản lý quyền truy cập và nhận dạng AWS (IAM)", "is_correct": true, "analysis_vi": "Đúng. Quản lý quyền truy cập và nhận dạng AWS (IAM) là đáp án chính xác. AWS Organs giúp quản lý tập trung việc thanh toán và cho phép truy cập có kiểm soát vào các tài nguyên trên các tài khoản AWS."}, {"label": "B", "text_vi": "AWS Organizations", "is_correct": false, "analysis_vi": "Sai. AWS Organizations: AWS Organizations giúp quản lý tập trung nhiều tài khoản AWS, hỗ trợ xuất hóa đơn hợp nhất (Consolidated Billing) và áp dụng chính sách SCP. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Trình AWS Cost Explorer AWS", "is_correct": false, "analysis_vi": "Sai. Trình AWS Cost Explorer AWS: AWS Cost Explorer cung cấp giao diện trực quan để phân tích, hiểu rõ chi phí lịch sử và dự báo chi tiêu AWS trong tương lai lên đến 12 tháng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Ngân sách AWS", "is_correct": false, "analysis_vi": "Sai. Ngân sách AWS: AWS Budgets cho phép thiết lập ngưỡng ngân sách tùy chỉnh và gửi thông báo hoặc kích hoạt hành động tự động khi chi phí dự kiến vượt ngưỡng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Cost Explorer", "AWS Budgets", "AWS Organizations", "AWS IAM"]'::jsonb, NOW())
