INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-9', 'practice_283', 'Một nhà phát triển đã được một công ty lớn thuê và cần có thông tin xác thực AWS. Những phương pháp bảo mật tốt nhất nào nên được tuân theo? (Chọn HAI.)', 'Domain 2: Security and Compliance', 'An ninh & Phòng chống đe dọa (Security & Compliance)', 'Các phương pháp bảo mật tốt nhất cần được tuân theo là A và E. A). Chỉ cấp cho nhà phát triển quyền truy cập vào các tài nguyên AWS cần thiết để thực hiện công việc. Đây là một ví dụ về nguyên tắc đặc quyền tối thiểu, có nghĩa là cấp các quyền tối thiểu cần thiết để hoàn thành một nhiệm vụ. Điều này giúp giảm nguy cơ truy cập trái phép, rò rỉ dữ liệu hoặc vô tình làm hỏng tài nguyên AWS. Bạn có thể sử dụng AWS Identity and Access Management (IAM) để tạo người dùng, nhóm, vai trò và chính sách cấp quyền truy cập chi tiết vào tài nguyên AWS12. Đ). Đảm bảo chính sách mật khẩu tài khoản yêu cầu độ dài tối thiểu. Đây là biện pháp bảo mật cơ bản giúp ngăn chặn các cuộc tấn công vũ phu hoặc đoán mật khẩu. Mật khẩu dài hơn khó bị bẻ khóa hơn mật khẩu ngắn hơn. Bạn có thể sử dụng IAM để định cấu hình chính sách mật khẩu thực thi độ dài mật khẩu tối thiểu cũng như các yêu cầu khác như độ phức tạp, ngày hết hạn và lịch sử34. B). Chia sẻ thông tin đăng nhập của người dùng root tài khoản AWS với nhà phát triển. Đây là một thói quen xấu cần tránh. Người dùng root có toàn quyền truy cập vào tất cả tài nguyên và dịch vụ AWS, đồng thời có thể thực hiện các hành động nhạy cảm như thay đổi thông tin thanh toán, đóng tài khoản hoặc xóa tất cả tài nguyên. Việc chia sẻ thông tin đăng nhập của người dùng root sẽ khiến tài khoản của bạn có nguy cơ bị xâm phạm hoặc sử dụng sai mục đích. Bạn không bao giờ nên chia sẻ thông tin xác thực người dùng root của mình với bất kỳ ai và chỉ sử dụng chúng cho các tác vụ quản trị tài khoản5 . C). Thêm nhà phát triển vào nhóm quản trị viên trong IAM. Đây cũng là một thói quen xấu cần tránh. Nhóm quản trị viên có toàn quyền truy cập vào tất cả tài nguyên và dịch vụ AWS, nhiều hơn những gì nhà phát triển cần để thực hiện công việc của họ. Việc thêm nhà phát triển vào nhóm quản trị viên sẽ vi phạm nguyên tắc đặc quyền tối thiểu và làm tăng nguy cơ truy cập trái phép, rò rỉ dữ liệu hoặc vô tình làm hỏng tài nguyên AWS. Bạn nên tạo một nhóm tùy chỉnh cho nhà phát triển để chỉ cấp các quyền cần thiết cho vai trò của họ12. Đ). Định cấu hình chính sách mật khẩu để đảm bảo không thể thay đổi mật khẩu của nhà phát triển. Đây là một thực hành xấu khác cần tránh. Việc ngăn nhà phát triển thay đổi mật khẩu sẽ làm giảm khả năng bảo vệ thông tin đăng nhập và tuân thủ các chính sách bảo mật của họ. Ví dụ: nếu mật khẩu của nhà phát triển bị xâm phạm, họ không thể thay đổi mật khẩu đó để ngăn chặn hành vi truy cập trái phép tiếp theo. Hoặc nếu công ty yêu cầu luân chuyển mật khẩu định kỳ thì họ không thể cập nhật mật khẩu của mình để đáp ứng yêu cầu này. Bạn nên cho phép nhà phát triển thay đổi mật khẩu của họ nếu cần và thực thi chính sách mật khẩu đặt ra các quy tắc hợp lý cho việc quản lý mật khẩu34.', '[{"label": "A", "text_vi": "Chỉ cấp cho nhà phát triển quyền truy cập vào các tài nguyên AWS cần thiết để thực hiện công việc.", "is_correct": true, "analysis_vi": "Đúng. Chỉ cấp cho nhà phát triển quyền truy cập vào các tài nguyên AWS cần thiết để thực hiện công việc. là đáp án chính xác. Chỉ cấp cho nhà phát triển quyền truy cập vào các tài nguyên AWS cần thiết để thực hiện công việc."}, {"label": "B", "text_vi": "Chia sẻ thông tin đăng nhập của người dùng root tài khoản AWS với nhà phát triển.", "is_correct": false, "analysis_vi": "Sai. Chia sẻ thông tin đăng nhập của người dùng root tài khoản AWS với nhà phát triển. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Thêm nhà phát triển vào nhóm quản trị viên trong AWS IAM.", "is_correct": false, "analysis_vi": "Sai. Thêm nhà phát triển vào nhóm quản trị viên trong AWS IAM.: AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Định cấu hình chính sách mật khẩu để đảm bảo không thể thay đổi mật khẩu của nhà phát triển.", "is_correct": false, "analysis_vi": "Sai. Định cấu hình chính sách mật khẩu để đảm bảo không thể thay đổi mật khẩu của nhà phát triển.: AWS Config liên tục ghi lại và đánh giá các thay đổi cấu hình tài nguyên so với các quy tắc tuân thủ mong muốn. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "E", "text_vi": "Đảm bảo chính sách mật khẩu tài khoản yêu cầu độ dài tối thiểu.", "is_correct": true, "analysis_vi": "Đúng. Đảm bảo chính sách mật khẩu tài khoản yêu cầu độ dài tối thiểu. là đáp án chính xác. Đây là một ví dụ về nguyên tắc đặc quyền tối thiểu, có nghĩa là cấp các quyền tối thiểu cần thiết để hoàn thành một nhiệm vụ."}]'::jsonb, '["Cặp dịch vụ bảo mật hay gặp: GuardDuty (phát hiện mối đe dọa thông minh), Inspector (quét lỗ hổng phần mềm trên EC2/Lambda), WAF (tường lửa web lớp 7)."]'::jsonb, '[{"term": "phát hiện mối đe dọa", "points_to": "Amazon GuardDuty"}]'::jsonb, '["AWS IAM"]'::jsonb, NOW())
