INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-10', 'practice_283', 'Dịch vụ nào sau đây là dịch vụ cơ sở dữ liệu đồ thị được quản lý toàn phần trên AWS?', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'Amazon Neptune là dịch vụ cơ sở dữ liệu đồ thị được quản lý toàn phần trên AWS. Cơ sở dữ liệu đồ thị là một loại cơ sở dữ liệu lưu trữ và truy vấn dữ liệu dưới dạng mạng gồm các nút và cạnh, biểu diễn các thực thể và mối quan hệ. Cơ sở dữ liệu đồ thị rất hữu ích cho các ứng dụng xử lý dữ liệu có tính kết nối cao, chẳng hạn như mạng xã hội, công cụ đề xuất, phát hiện gian lận và biểu đồ tri thức45. Amazon Neptune là dịch vụ cơ sở dữ liệu đồ thị nhanh, đáng tin cậy và có thể mở rộng, hỗ trợ hai mô hình đồ thị phổ biến: đồ thị thuộc tính và RDF. Amazon Neptune cũng hỗ trợ hai tiêu chuẩn mở để truy vấn biểu đồ: Apache TinkerPop Gremlin và SPARQL. Amazon Neptune xử lý những công việc nặng nhọc trong việc quản lý cơ sở dữ liệu, chẳng hạn như cung cấp, vá lỗi, sao lưu, phục hồi, mã hóa và sao chép456.', '[{"label": "A", "text_vi": "Amazon cực quang", "is_correct": false, "analysis_vi": "Sai. Amazon cực quang: Amazon Aurora là cơ sở dữ liệu quan hệ tương thích MySQL/PostgreSQL hiệu năng cao gấp 3-5 lần, tự động sao chép 6 bản dữ liệu qua 3 AZ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon FSx", "is_correct": false, "analysis_vi": "Sai. Amazon FSx không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Amazon DynamoDB", "is_correct": false, "analysis_vi": "Sai. Amazon DynamoDB: Amazon DynamoDB là cơ sở dữ liệu NoSQL (Key-Value và Document) serverless, cung cấp hiệu năng dưới 10 mili-giây ổn định ở mọi quy mô. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Sao Hải Vương Amazon", "is_correct": true, "analysis_vi": "Đúng. Sao Hải Vương Amazon là đáp án chính xác. Amazon Neptune là dịch vụ cơ sở dữ liệu đồ thị được quản lý toàn phần trên AWS."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon Aurora", "Amazon DynamoDB"]'::jsonb, NOW())
