INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-11', 'practice_283', 'Để giảm chi phí, một công ty đang có kế hoạch di chuyển cơ sở dữ liệu NoSQL sang AWS. Dịch vụ AWS nào được quản lý toàn phần và có thể tự động thay đổi quy mô công suất thông lượng để đáp ứng nhu cầu khối lượng công việc của cơ sở dữ liệu?', 'Domain 3: Cloud Technology and Services', 'Quản lý chi phí & Thanh toán AWS', 'Amazon DynamoDB là dịch vụ cơ sở dữ liệu NoSQL có giá trị khóa, không có máy chủ, được quản lý toàn phần, có thể mang lại hiệu suất ổn định ở từng mili giây ở mọi quy mô. DynamoDB có thể tự động thay đổi quy mô công suất thông lượng để đáp ứng nhu cầu của khối lượng công việc cơ sở dữ liệu mà không cần bất kỳ sự can thiệp thủ công nào. DynamoDB lý tưởng cho các ứng dụng NoSQL cần hiệu năng, tính khả dụng và khả năng mở rộng cao. DynamoDB cũng cung cấp các tính năng như mã hóa khi lưu trữ, khôi phục tại thời điểm, bảng chung và bộ nhớ đệm trong bộ nhớ.', '[{"label": "A", "text_vi": "Dịch chuyển đỏ của Amazon", "is_correct": false, "analysis_vi": "Sai. Dịch chuyển đỏ của Amazon: Amazon Redshift là kho dữ liệu đám mây (Data Warehouse) phục vụ phân tích dữ liệu lớn và OLAP ở quy mô petabyte. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon cực quang", "is_correct": false, "analysis_vi": "Sai. Amazon cực quang: Amazon Aurora là cơ sở dữ liệu quan hệ tương thích MySQL/PostgreSQL hiệu năng cao gấp 3-5 lần, tự động sao chép 6 bản dữ liệu qua 3 AZ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Amazon DynamoDB", "is_correct": true, "analysis_vi": "Đúng. Amazon DynamoDB là đáp án chính xác. Amazon DynamoDB là dịch vụ cơ sở dữ liệu NoSQL có giá trị khóa, không có máy chủ, được quản lý toàn phần, có thể mang lại hiệu suất ổn định ở từng mili giây ở mọi quy mô."}, {"label": "D", "text_vi": "Amazon RDS", "is_correct": false, "analysis_vi": "Sai. Amazon RDS: Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["Amazon RDS", "Amazon Aurora", "Amazon DynamoDB"]'::jsonb, NOW())
