INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-12', 'practice_283', 'Dịch vụ AWS nào là giải pháp phân phối và triển khai liên tục?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'AWS CodePipeline là dịch vụ phân phối và triển khai liên tục, tự động hóa quy trình phát hành ứng dụng phần mềm qua các giai đoạn khác nhau, chẳng hạn như mã nguồn, bản dựng, thử nghiệm và triển khai2. AWSAppSync, AWS Cloud9 và AWS CodeCommit là các dịch vụ AWS khác liên quan đến phát triển ứng dụng nhưng chúng không cung cấp các giải pháp triển khai và phân phối liên tục34 .', '[{"label": "A", "text_vi": "AWSAppSync", "is_correct": false, "analysis_vi": "Sai. AWSAppSync, AWS Cloud9 và AWS CodeCommit là các dịch vụ AWS khác liên quan đến phát triển ứng dụng nhưng chúng không cung cấp các giải pháp triển khai và phân phối liên tục34 .."}, {"label": "B", "text_vi": "Đường dẫn mã AWS", "is_correct": true, "analysis_vi": "Đúng. Đường dẫn mã AWS là đáp án chính xác. AWS CodePipeline là dịch vụ phân phối và triển khai liên tục, tự động hóa quy trình phát hành ứng dụng phần mềm qua các giai đoạn khác nhau, chẳng hạn như mã nguồn, bản dựng, thử nghiệm và triển khai2."}, {"label": "C", "text_vi": "AWS Cloud9", "is_correct": false, "analysis_vi": "Sai. AWSAppSync, AWS Cloud9 và AWS CodeCommit là các dịch vụ AWS khác liên quan đến phát triển ứng dụng nhưng chúng không cung cấp các giải pháp triển khai và phân phối liên tục34 .."}, {"label": "D", "text_vi": "AWS CodeCommit", "is_correct": false, "analysis_vi": "Sai. AWSAppSync, AWS Cloud9 và AWS CodeCommit là các dịch vụ AWS khác liên quan đến phát triển ứng dụng nhưng chúng không cung cấp các giải pháp triển khai và phân phối liên tục34 .."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
