INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-13', 'practice_283', 'Công ty nên sử dụng dịch vụ hoặc công cụ AWS nào để dự báo chi tiêu AWS?', 'Domain 4: Billing, Pricing and Support', 'Billing, Pricing and Support', 'Cost Explorer là một dịch vụ hoặc công cụ AWS có thể dùng để dự báo chi tiêu AWS. Nó cho phép người dùng phân tích chi phí và mức sử dụng AWS của họ bằng cách sử dụng các biểu đồ và bảng tương tác. Nó cũng cung cấp các tính năng như lọc, nhóm và dự báo để giúp người dùng lập kế hoạch chi tiêu trong tương lai. Amazon DevPay là dịch vụ AWS cho phép các nhà phát triển bán ứng dụng được xây dựng trên dịch vụ AWS. Nó xử lý việc thanh toán và đo lường cho khách hàng của ứng dụng và thu các khoản thanh toán từ họ. Nó không phải là công cụ để dự báo chi tiêu AWS. AWS Organizations là dịch vụ AWS cho phép người dùng quản lý và quản lý tập trung tài khoản AWS của họ. Nó cung cấp các tính năng như tạo nhóm tài khoản, áp dụng chính sách và tự động tạo tài khoản. Nó không phải là công cụ để dự báo chi tiêu AWS. AWS Trusted Advisor là dịch vụ AWS cung cấp các biện pháp thực hành và đề xuất tốt nhất để tối ưu hóa hiệu suất, bảo mật và chi phí của tài nguyên AWS. Nó có thể giúp người dùng xác định các cơ hội để giảm chi phí AWS của họ, nhưng nó không phải là công cụ để dự báo chi tiêu AWS', '[{"label": "A", "text_vi": "Amazon DevPay", "is_correct": false, "analysis_vi": "Sai. Amazon DevPay không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "AWS Organizations", "is_correct": false, "analysis_vi": "Sai. AWS Organizations: AWS Organizations giúp quản lý tập trung nhiều tài khoản AWS, hỗ trợ xuất hóa đơn hợp nhất (Consolidated Billing) và áp dụng chính sách SCP. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "AWS Trusted Advisor", "is_correct": false, "analysis_vi": "Sai. AWS Trusted Advisor: AWS Trusted Advisor quét toàn bộ tài khoản AWS và đưa ra khuyến nghị tối ưu theo 5 trụ cột: Chi phí, Hiệu năng, Bảo mật, Khả năng chịu lỗi và Giới hạn dịch vụ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "AWS Cost Explorer", "is_correct": true, "analysis_vi": "Đúng. AWS Cost Explorer là đáp án chính xác. Cost Explorer là một dịch vụ hoặc công cụ AWS có thể dùng để dự báo chi tiêu AWS."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Trusted Advisor", "AWS Cost Explorer", "AWS Organizations"]'::jsonb, NOW())
