INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-14', 'practice_283', 'Kỹ sư đám mây nên sử dụng dịch vụ AWS nào để xem lệnh gọi API đến dịch vụ AWS?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'Câu trả lời đúng là B vì AWS CloudTrail là dịch vụ AWS mà kỹ sư đám mây có thể sử dụng để xem lệnh gọi API tới dịch vụ AWS. AWS CloudTrail là dịch vụ cho phép khách hàng theo dõi hoạt động của người dùng và mức sử dụng API trên tài khoản AWS của họ. AWS CloudTrail ghi lại thông tin chi tiết về mọi lệnh gọi API được thực hiện tới các dịch vụ AWS, chẳng hạn như danh tính của người gọi, thời gian của cuộc gọi, địa chỉ IP nguồn của người gọi, các tham số và phản hồi của cuộc gọi, v.v. Khách hàng có thể sử dụng AWS CloudTrail để kiểm tra, giám sát và khắc phục sự cố các tài nguyên và hành động AWS của mình. Các tùy chọn khác không chính xác vì chúng không phải là dịch vụ AWS mà kỹ sư đám mây có thể sử dụng để xem lệnh gọi API tới dịch vụ AWS. Amazon CloudWatch là dịch vụ AWS cho phép khách hàng thu thập, phân tích và trực quan hóa các số liệu, nhật ký và sự kiện từ các tài nguyên và ứng dụng AWS của họ. AWS Config là dịch vụ AWS cho phép khách hàng đánh giá, kiểm tra và đánh giá cấu hình tài nguyên AWS của họ. AWS Artifact là dịch vụ AWS cung cấp cho khách hàng quyền truy cập theo yêu cầu vào các báo cáo tuân thủ AWS và các thỏa thuận trực tuyến chọn lọc.', '[{"label": "A", "text_vi": "Amazon CloudWatch", "is_correct": false, "analysis_vi": "Sai. Amazon CloudWatch: Amazon CloudWatch là dịch vụ giám sát và quan sát tài nguyên, thu thập chỉ số (metrics), log và gửi cảnh báo (alarms) theo thời gian thực. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "AWS CloudTrail", "is_correct": true, "analysis_vi": "Đúng. AWS CloudTrail là đáp án chính xác. Câu trả lời đúng là B vì AWS CloudTrail là dịch vụ AWS mà kỹ sư đám mây có thể sử dụng để xem lệnh gọi API tới dịch vụ AWS."}, {"label": "C", "text_vi": "Cấu hình AWS", "is_correct": false, "analysis_vi": "Sai. Cấu hình AWS: AWS Config liên tục ghi lại và đánh giá các thay đổi cấu hình tài nguyên so với các quy tắc tuân thủ mong muốn. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Tạo phẩm AWS", "is_correct": false, "analysis_vi": "Sai. Tạo phẩm AWS: AWS Artifact là cổng thông tin cung cấp quyền truy cập theo yêu cầu vào các báo cáo kiểm toán bảo mật và tuân thủ của AWS (SOC, PCI-DSS, ISO). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon CloudWatch", "AWS CloudTrail", "AWS Artifact"]'::jsonb, NOW())
