INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-15', 'practice_283', 'Availability Zone (AZ) là gì?', 'Domain 3: Cloud Technology and Services', 'Lợi thế điện toán đám mây & Hạ tầng toàn cầu', 'Availability Zone (AZ) là một hoặc nhiều trung tâm dữ liệu riêng biệt có nguồn điện, mạng và kết nối dự phòng. Availability Zone (AZ) là một phần của cơ sở hạ tầng toàn cầu AWS, bao gồm AWS Region, Availability Zone (AZ) và vị trí biên. Availability Zone (AZ) là các vị trí riêng biệt về mặt vật lý trong AWS Region, được thiết kế để cách ly khỏi lỗi và được kết nối bằng mạng có độ trễ thấp, thông lượng cao và có tính dự phòng cao. Mỗi Availability Zone (AZ) chứa một hoặc nhiều trung tâm dữ liệu chứa các máy chủ và thiết bị lưu trữ chạy dịch vụ AWS. Availability Zone (AZ) cho phép người dùng thiết kế và vận hành các ứng dụng có khả năng chịu lỗi và tính sẵn sàng cao trên AWS. Cơ sở hạ tầng toàn cầu AWSNgười thực hành đám mây được chứng nhận AWS - aws.amazon.com', '[{"label": "A", "text_vi": "Vị trí nơi người dùng có thể triển khai điện toán, lưu trữ, cơ sở dữ liệu và các dịch vụ AWS chọn lọc khác ở nơi hiện không có AWS Region nào tồn tại", "is_correct": false, "analysis_vi": "Sai. Vị trí nơi người dùng có thể triển khai điện toán, lưu trữ, cơ sở dữ liệu và các dịch vụ AWS chọn lọc khác ở nơi hiện không có AWS Region nào tồn tại không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Một hoặc nhiều trung tâm dữ liệu riêng biệt có nguồn điện, mạng và kết nối dự phòng", "is_correct": true, "analysis_vi": "Đúng. Một hoặc nhiều trung tâm dữ liệu riêng biệt có nguồn điện, mạng và kết nối dự phòng là đáp án chính xác. Availability Zone (AZ) là một hoặc nhiều trung tâm dữ liệu riêng biệt có nguồn điện, mạng và kết nối dự phòng."}, {"label": "C", "text_vi": "Một hoặc nhiều cụm máy chủ có thể triển khai khối lượng công việc mới", "is_correct": false, "analysis_vi": "Sai. Một hoặc nhiều cụm máy chủ có thể triển khai khối lượng công việc mới không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Dịch vụ mạng phân phối nội dung (CDN) nhanh chóng cung cấp dữ liệu, video, ứng dụng và API cho người dùng trên toàn cầu một cách an toàn", "is_correct": false, "analysis_vi": "Sai. Dịch vụ mạng phân phối nội dung (CDN) nhanh chóng cung cấp dữ liệu, video, ứng dụng và API cho người dùng trên toàn cầu một cách an toàn không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Direct Connect"]'::jsonb, NOW())
