INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-16', 'practice_283', 'Một công ty thương mại điện tử muốn thiết kế một ứng dụng có tính sẵn sàng cao sẽ được lưu trữ trên nhiều phiên bản Amazon EC2. Công ty nên triển khai các phiên bản EC2 như thế nào để đáp ứng các yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'Công ty nên triển khai các phiên bản EC2 trên nhiều Availability Zone (AZ) để thiết kế một ứng dụng có tính sẵn sàng cao. Availability Zone (AZ) là các vị trí biệt lập trong AWS Region được thiết kế để có khả năng chịu lỗi và hoạt động độc lập với nhau. Bằng cách triển khai các phiên bản EC2 trên nhiều Availability Zone (AZ), công ty có thể đảm bảo rằng ứng dụng của họ có thể chịu được sự cố của toàn bộ Availability Zone (AZ) và tiếp tục hoạt động với mức gián đoạn tối thiểu. Việc triển khai các phiên bản EC2 trên nhiều vị trí biên, VPC hoặc tài khoản AWS sẽ không cung cấp cùng mức độ sẵn sàng và khả năng chịu lỗi như Availability Zone (AZ). Các vị trí biên là một phần của dịch vụ Amazon CloudFront, một mạng phân phối nội dung (CDN) lưu trữ và phân phát nội dung web cho người dùng. VPC là các mạng ảo cô lập các tài nguyên AWS trong AWS Region. Tài khoản AWS là đơn vị chính có quyền sở hữu và kiểm soát quyền truy cập đối với các tài nguyên AWS12 Bãi chứa AWS-Certified-Cloud-Practitioner hợp lệ được EduDump.com chia sẻ để giúp vượt qua kỳ thi dành cho người thực hành trên nền tảng đám mây được chứng nhận AWS! EduDump.com hiện cung cấp các kết xuất bài thi AWS- Certified-Cloud-Practitioner mới nhất, các câu hỏi thi EduDump.com AWS-Certified-Cloud-Practitioner đã được cập nhật và các câu trả lời đã được sửa. Hãy tải các kết xuất bài thi EduDump.com AWS-Certified-Cloud-Practitioner mới nhất với Test Engine tại đây: https://www.edudump.com/exams/Amazon/AWS-Certified-Cloud-Practitioner/premium/ ( 600 lượt hỏi đáp, GIẢM GIÁ 35% Mã giảm giá đặc biệt: freecram )', '[{"label": "A", "text_vi": "Trên nhiều vị trí biên", "is_correct": false, "analysis_vi": "Sai. Trên nhiều vị trí biên không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Trên nhiều VPC", "is_correct": false, "analysis_vi": "Sai. Trên nhiều VPC: Amazon VPC cho phép khởi tạo mạng ảo riêng biệt được cô lập logic trên đám mây AWS, kiểm soát toàn diện dải IP, subnet, bảng định tuyến và cổng mạng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Trên nhiều Availability Zone (AZ)", "is_correct": true, "analysis_vi": "Đúng. Trên nhiều Availability Zone (AZ) là đáp án chính xác. Công ty nên triển khai các phiên bản EC2 trên nhiều Availability Zone (AZ) để thiết kế một ứng dụng có tính sẵn sàng cao."}, {"label": "D", "text_vi": "Trên nhiều tài khoản AWS", "is_correct": false, "analysis_vi": "Sai. Trên nhiều tài khoản AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon EC2", "Amazon VPC"]'::jsonb, NOW())
