INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-17', 'practice_283', 'Ứng dụng của một công ty có lượng khách hàng sử dụng cao vào những thời điểm nhất định trong ngày. Công ty muốn giảm số lượng phiên bản Amazon EC2 chạy khi mức sử dụng ứng dụng ở mức thấp. Công ty nên sử dụng tùy chọn mua phiên bản hoặc dịch vụ AWS nào để đáp ứng yêu cầu này?', 'Domain 4: Billing, Pricing and Support', 'Dịch vụ điện toán đám mây Amazon EC2', 'Amazon EC2 Auto Scaling là dịch vụ AWS có thể giúp người dùng giảm số lượng phiên bản Amazon EC2 chạy khi mức sử dụng ứng dụng ở mức thấp. Amazon EC2 Auto Scaling cho phép người dùng tạo các chính sách thay đổi quy mô tự động điều chỉnh số lượng phiên bản EC2 dựa trên nhu cầu hoặc lịch trình. Gói tiết kiệm phiên bản EC2, Phiên bản dùng ngay và Phiên bản dự trữ là các tùy chọn mua phiên bản có thể giúp người dùng tiết kiệm tiền khi sử dụng EC2, nhưng chúng không tự động thay đổi quy mô số lượng phiên bản theo mức sử dụng ứng dụng.', '[{"label": "A", "text_vi": "Gói tiết kiệm phiên bản EC2", "is_correct": false, "analysis_vi": "Sai. Gói tiết kiệm phiên bản EC2: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Phiên bản Spot", "is_correct": false, "analysis_vi": "Sai. Phiên bản Spot không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Phiên bản dự trữ", "is_correct": false, "analysis_vi": "Sai. Phiên bản dự trữ không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Tự động thay đổi quy mô Amazon EC2", "is_correct": true, "analysis_vi": "Đúng. Tự động thay đổi quy mô Amazon EC2 là đáp án chính xác. Amazon EC2 Auto Scaling là dịch vụ AWS có thể giúp người dùng giảm số lượng phiên bản Amazon EC2 chạy khi mức sử dụng ứng dụng ở mức thấp."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
