INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-18', 'practice_283', 'Dịch vụ AWS nào cho phép các công ty triển khai một lượng ứng dụng cho người dùng cuối?', 'Domain 2: Security and Compliance', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Amazon CloudFront là dịch vụ mạng phân phối nội dung (CDN) nhanh, cung cấp dữ liệu, video, ứng dụng và API một cách an toàn cho khách hàng trên toàn cầu với độ trễ thấp, tốc độ truyền cao, tất cả đều trong môi trường thân thiện với nhà phát triển. CloudFront cho phép các công ty triển khai một ứng dụng gần với người dùng cuối bằng cách lưu vào bộ nhớ đệm nội dung của ứng dụng tại các vị trí biên gần với người dùng hơn về mặt địa lý. Điều này làm giảm độ trễ mạng và cải thiện trải nghiệm người dùng. CloudFront cũng tích hợp với các dịch vụ AWS khác, chẳng hạn như Amazon S3, Amazon EC2, AWS Lambda, AWS Shield và AWS WAF, để cung cấp giải pháp an toàn và có thể mở rộng để phân phối ứng dụng12.', '[{"label": "A", "text_vi": "Amazon CloudFront", "is_correct": true, "analysis_vi": "Đúng. Amazon CloudFront là đáp án chính xác. Amazon CloudFront là dịch vụ mạng phân phối nội dung (CDN) nhanh, cung cấp dữ liệu, video, ứng dụng và API một cách an toàn cho khách hàng trên toàn cầu với độ trễ thấp, tốc độ truyền cao, tất cả đều trong môi trường thân thiện với nhà phát triển."}, {"label": "B", "text_vi": "Tự động chia tỷ lệ AWS", "is_correct": false, "analysis_vi": "Sai. Tự động chia tỷ lệ AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Đồng bộ hóa ứng dụng AWS", "is_correct": false, "analysis_vi": "Sai. Đồng bộ hóa ứng dụng AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Tuyến đường Amazon S3", "is_correct": false, "analysis_vi": "Sai. Tuyến đường Amazon S3: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon S3", "Amazon CloudFront"]'::jsonb, NOW())
