INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-19', 'practice_283', 'Một công ty đang sử dụng dịch vụ của bên thứ ba để sao lưu 10 TB dữ liệu vào thư viện băng từ. Máy chủ dự phòng tại chỗ sắp hết dung lượng. Công ty muốn sử dụng các dịch vụ AWS để sao lưu mà không thay đổi quy trình sao lưu hiện có. Công ty nên sử dụng dịch vụ AWS nào để đáp ứng những yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Câu trả lời đúng là B vì AWS Storage Gateway là dịch vụ nên được công ty sử dụng để đáp ứng yêu cầu. AWS Storage Gateway là dịch vụ kết nối các ứng dụng phần mềm tại chỗ với bộ lưu trữ trên nền tảng đám mây. AWS Storage Gateway hỗ trợ ba loại cổng: cổng tệp, cổng ổ đĩa và cổng băng từ. Loại cổng băng từ cho phép người dùng sao lưu và lưu trữ dữ liệu vào băng từ ảo trong AWS mà không thay đổi quy trình sao lưu hiện tại của họ. Người dùng có thể sử dụng các ứng dụng sao lưu và thư viện băng từ hiện có của mình để lưu trữ dữ liệu trên băng ảo trên Amazon S3 hoặc Amazon S3 Glacier. Các lựa chọn khác không chính xác vì chúng không phải là dịch vụ mà công ty nên sử dụng để đáp ứng yêu cầu. Amazon Elastic Block Store (Amazon EBS) là dịch vụ cung cấp dung lượng lưu trữ cấp khối cho các phiên bản Amazon EC2. Amazon Elastic Container Service (Amazon ECS) là dịch vụ cho phép người dùng chạy, mở rộng quy mô và bảo mật các ứng dụng được chứa trong bộ chứa trên AWS. AWS Lambda là dịch vụ cho phép người dùng chạy mã mà không cần cung cấp hay quản lý máy chủ.', '[{"label": "A", "text_vi": "Cửa hàng khối đàn hồi Amazon (Amazon EBS)", "is_correct": false, "analysis_vi": "Sai. Cửa hàng khối đàn hồi Amazon (Amazon EBS): Amazon EBS cung cấp các khối lưu trữ cấp block gắn trực tiếp vào phiên bản EC2 với độ trễ thấp và tính bền vững cao trong một Availability Zone. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "AWS Storage Gateway", "is_correct": true, "analysis_vi": "Đúng. AWS Storage Gateway là đáp án chính xác. Câu trả lời đúng là B vì AWS Storage Gateway là dịch vụ nên được công ty sử dụng để đáp ứng yêu cầu."}, {"label": "C", "text_vi": "Dịch vụ container đàn hồi của Amazon (Amazon ECS)", "is_correct": false, "analysis_vi": "Sai. Dịch vụ container đàn hồi của Amazon (Amazon ECS): Amazon ECS là dịch vụ điều phối container Docker có khả năng mở rộng cao và hiệu năng cao trên AWS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "AWS Lambda", "is_correct": false, "analysis_vi": "Sai. AWS Lambda là dịch vụ cho phép người dùng chạy mã mà không cần cung cấp hay quản lý máy chủ.."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Lambda", "AWS Storage Gateway"]'::jsonb, NOW())
