INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-20', 'practice_283', 'Một công ty đang lưu trữ một ứng dụng trên Đám mây AWS. Công ty muốn xác minh rằng các dịch vụ AWS bên dưới và cơ sở hạ tầng chung đang hoạt động bình thường. Những dịch vụ AWS nào có thể giúp công ty đáp ứng các yêu cầu này? (Chọn HAI.)', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'AWS Personal Health Dashboard và AWS Service Health Dashboard là hai dịch vụ AWS có thể giúp công ty xác minh rằng các dịch vụ AWS cơ bản và cơ sở hạ tầng AWS chung đang hoạt động bình thường. AWS Personal Health Dashboard cung cấp cái nhìn được cá nhân hóa về hiệu suất và tính khả dụng của các dịch vụ AWS mà bạn đang sử dụng, cũng như các cảnh báo được tự động kích hoạt khi có những thay đổi về tình trạng của các dịch vụ đó. Ngoài các cảnh báo dựa trên sự kiện, Bảng thông tin sức khỏe cá nhân còn cung cấp thông báo chủ động về các hoạt động đã lên lịch, chẳng hạn như mọi thay đổi đối với cơ sở hạ tầng cung cấp năng lượng cho tài nguyên của bạn, cho phép bạn lập kế hoạch tốt hơn cho các sự kiện có thể ảnh hưởng đến bạn. Những thông báo này có thể được gửi cho bạn qua email hoặc thiết bị di động để xem nhanh và luôn có thể được xem từ trong Bảng điều khiển quản lý AWS. Khi bạn nhận được cảnh báo, cảnh báo sẽ bao gồm thông tin và hướng dẫn chi tiết, cho phép bạn thực hiện hành động ngay lập tức để giải quyết các sự kiện AWS ảnh hưởng đến tài nguyên của bạn3. Bảng thông tin tình trạng dịch vụ AWS cung cấp trạng thái chung của các dịch vụ AWS và chế độ xem tình trạng dịch vụ hiển thị trạng thái hiện tại và lịch sử của tất cả các dịch vụ AWS. Trang này hiển thị các sự kiện dịch vụ được báo cáo cho các dịch vụ trên khắp AWS Region. Bạn không cần đăng nhập hoặc có tài khoản AWS để truy cập Bảng thông tin tình trạng dịch vụ AWS - trang Tình trạng dịch vụ. Bạn cũng có thể đăng ký nguồn cấp dữ liệu RSS cho các dịch vụ hoặc khu vực cụ thể để nhận thông báo về các sự kiện dịch vụ4.', '[{"label": "A", "text_vi": "Bảng thông tin sức khỏe cá nhân AWS", "is_correct": true, "analysis_vi": "Đúng. Bảng thông tin sức khỏe cá nhân AWS là đáp án chính xác. AWS Personal Health Dashboard và AWS Service Health Dashboard là hai dịch vụ AWS có thể giúp công ty xác minh rằng các dịch vụ AWS cơ bản và cơ sở hạ tầng AWS chung đang hoạt động bình thường."}, {"label": "B", "text_vi": "Trình quản lý hệ thống AWS", "is_correct": false, "analysis_vi": "Sai. Trình quản lý hệ thống AWS: AWS Systems Manager cung cấp giao diện quản lý tập trung tài nguyên, tự động hóa tác vụ vận hành, quản lý bản vá (Patch Manager) và chạy lệnh (Run Command). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "AWS Trusted Advisor", "is_correct": false, "analysis_vi": "Sai. AWS Trusted Advisor: AWS Trusted Advisor quét toàn bộ tài khoản AWS và đưa ra khuyến nghị tối ưu theo 5 trụ cột: Chi phí, Hiệu năng, Bảo mật, Khả năng chịu lỗi và Giới hạn dịch vụ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Bảng thông tin tình trạng dịch vụ AWS", "is_correct": true, "analysis_vi": "Đúng. Bảng thông tin tình trạng dịch vụ AWS là đáp án chính xác. AWS Personal Health Dashboard và AWS Service Health Dashboard là hai dịch vụ AWS có thể giúp công ty xác minh rằng các dịch vụ AWS cơ bản và cơ sở hạ tầng AWS chung đang hoạt động bình thường."}, {"label": "E", "text_vi": "Danh mục dịch vụ AWS", "is_correct": false, "analysis_vi": "Sai. Danh mục dịch vụ AWS: AWS Service Catalog cho phép tổ chức tạo và quản lý các danh mục dịch vụ CNTT đã được phê duyệt sẵn để người dùng tự triển khai. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["AWS Trusted Advisor", "AWS Secrets Manager"]'::jsonb, NOW())
