INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-21', 'practice_283', 'công ty muốn bảo vệ thông tin, hệ thống và tài sản trên Đám mây AWS của mình trong khi thực hiện các nhiệm vụ đánh giá và giảm thiểu rủi ro. Trụ cột nào của Khung kiến ​​trúc tối ưu AWS được hỗ trợ bởi các mục tiêu này?', 'Domain 1: Cloud Concepts', 'Khung kiến trúc tối ưu AWS (Well-Architected Framework)', 'Trụ cột của Khung kiến trúc tối ưu AWS được hỗ trợ bởi các mục tiêu bảo vệ thông tin, hệ thống và tài sản trên Đám mây AWS trong khi thực hiện các nhiệm vụ đánh giá và giảm thiểu rủi ro là bảo mật. Bảo mật là khả năng bảo vệ thông tin, hệ thống và tài sản đồng thời mang lại giá trị kinh doanh thông qua các chiến lược đánh giá và giảm thiểu rủi ro. Trụ cột bảo mật bao gồm các chủ đề như quản lý danh tính và quyền truy cập, bảo vệ dữ liệu, bảo vệ cơ sở hạ tầng, kiểm soát phát hiện, ứng phó sự cố và tuân thủ', '[{"label": "A", "text_vi": "Độ tin cậy", "is_correct": false, "analysis_vi": "Sai. Độ tin cậy không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Bảo mật", "is_correct": true, "analysis_vi": "Đúng. Bảo mật đáp ứng đầy đủ yêu cầu của đề bài. Trụ cột của Khung kiến trúc tối ưu AWS được hỗ trợ bởi các mục tiêu bảo vệ thông tin, hệ thống và tài sản trên Đám mây AWS trong khi thực hiện các nhiệm vụ đánh giá và giảm thiểu rủi ro là bảo mật."}, {"label": "C", "text_vi": "Hoạt động xuất sắc", "is_correct": false, "analysis_vi": "Sai. Hoạt động xuất sắc không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Hiệu quả hoạt động", "is_correct": false, "analysis_vi": "Sai. Hiệu quả hoạt động không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Ghi nhớ các ngưỡng SLA phản hồi: Business (<1h cho production down, 24/7 phone/chat/email), Enterprise (<15m cho mission-critical, có TAM)."]'::jsonb, '[{"term": "support plan", "points_to": "Developer / Business / Enterprise"}]'::jsonb, '[]'::jsonb, NOW())
