INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-22', 'practice_283', 'Một công ty muốn có dịch vụ cơ sở dữ liệu chuỗi thời gian giúp lưu trữ và phân tích hàng nghìn tỷ sự kiện mỗi ngày dễ dàng hơn. Dịch vụ AWS nào sẽ đáp ứng yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'Amazon Timestream là dịch vụ cơ sở dữ liệu chuỗi thời gian nhanh, có thể mở rộng và không cần máy chủ dành cho IoT và các ứng dụng vận hành khác, giúp dễ dàng lưu trữ và phân tích hàng nghìn tỷ sự kiện mỗi ngày, nhanh hơn tới 1.000 lần và chi phí chỉ bằng 1/10 so với cơ sở dữ liệu quan hệ1. Amazon Timestream giúp bạn tiết kiệm thời gian và chi phí trong việc quản lý vòng đời của dữ liệu chuỗi thời gian, đồng thời công cụ truy vấn được xây dựng theo mục đích của nó cho phép bạn truy cập và phân tích dữ liệu lịch sử và dữ liệu gần đây cùng với một truy vấn1. Amazon Timestream có các chức năng phân tích chuỗi thời gian tích hợp sẵn, giúp bạn xác định xu hướng và mô hình gần như theo thời gian thực1. Các tùy chọn khác không phù hợp để lưu trữ và phân tích hàng nghìn tỷ sự kiện mỗi ngày. Amazon Neptune là dịch vụ cơ sở dữ liệu đồ thị hỗ trợ các tập dữ liệu có tính kết nối cao. Dự báo của Amazon là dịch vụ máy học tạo ra các dự báo chính xác dựa trên dữ liệu lịch sử. Amazon DocumentDB (có khả năng tương thích với MongoDB) là dịch vụ cơ sở dữ liệu tài liệu hỗ trợ khối lượng công việc MongoDB.', '[{"label": "A", "text_vi": "Sao Hải Vương Amazon", "is_correct": false, "analysis_vi": "Sai. Sao Hải Vương Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Dòng thời gian của Amazon", "is_correct": true, "analysis_vi": "Đúng. Dòng thời gian của Amazon là đáp án chính xác. Amazon Timestream là dịch vụ cơ sở dữ liệu chuỗi thời gian nhanh, có thể mở rộng và không cần máy chủ dành cho IoT và các ứng dụng vận hành khác, giúp dễ dàng lưu trữ và phân tích hàng nghìn tỷ sự kiện mỗi ngày, nhanh hơn tới 1.000 lần và chi phí chỉ bằng 1/10 so với cơ sở dữ liệu quan hệ1."}, {"label": "C", "text_vi": "Dự báo của Amazon", "is_correct": false, "analysis_vi": "Sai. Dự báo của Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Amazon DocumentDB (có khả năng tương thích MongoDB)", "is_correct": false, "analysis_vi": "Sai. Amazon DocumentDB (có khả năng tương thích MongoDB) không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '[]'::jsonb, NOW())
