INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-23', 'practice_283', 'Một công ty cần chạy khối lượng công việc tùy chỉnh, phi sản xuất hiện có trên Đám mây AWS một cách nhanh chóng và tiết kiệm chi phí. Khối lượng công việc có thể phục hồi sau khi bị gián đoạn một cách dễ dàng. Công ty nên sử dụng mô hình định giá nào?', 'Domain 4: Billing, Pricing and Support', 'Quản lý chi phí & Thanh toán AWS', 'Câu trả lời đúng là C vì Phiên bản dùng ngay là mô hình định giá cho phép công ty chạy khối lượng công việc tùy chỉnh, phi sản xuất hiện có trên Đám mây AWS một cách nhanh chóng và tiết kiệm chi phí. Phiên bản Spot là phiên bản Amazon EC2 dự phòng được cung cấp với mức giảm giá lên tới 90% so với giá Theo yêu cầu. Phiên bản Spot phù hợp với khối lượng công việc không trạng thái, có khả năng chịu lỗi và linh hoạt, có thể phục hồi dễ dàng sau khi bị gián đoạn. Các tùy chọn khác không chính xác vì chúng không phải là mô hình định giá cho phép công ty chạy khối lượng công việc tùy chỉnh, phi sản xuất hiện có trên Đám mây AWS một cách nhanh chóng và tiết kiệm chi phí. Phiên bản dự trữ là các phiên bản Amazon EC2 được dự trữ trong một khoảng thời gian cụ thể (một hoặc ba năm) để đổi lấy mức giá theo giờ thấp hơn. Phiên bản dự trữ phù hợp với khối lượng công việc ở trạng thái ổn định hoặc có thể dự đoán được chạy trong thời gian dài. Phiên bản theo yêu cầu là phiên bản Amazon EC2 được khởi chạy và tính phí theo mức cố định theo giờ. Phiên bản Theo yêu cầu phù hợp với khối lượng công việc ngắn hạn, không thường xuyên hoặc không thể đoán trước và không thể bị gián đoạn. Máy chủ chuyên dụng là máy chủ vật lý dành riêng cho một khách hàng. Máy chủ chuyên dụng phù hợp với khối lượng công việc yêu cầu tuân thủ quy định hoặc cách ly dữ liệu.', '[{"label": "A", "text_vi": "Phiên bản dự trữ", "is_correct": false, "analysis_vi": "Sai. Phiên bản dự trữ không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Phiên bản theo yêu cầu", "is_correct": false, "analysis_vi": "Sai. Phiên bản theo yêu cầu không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Phiên bản Spot", "is_correct": true, "analysis_vi": "Đúng. Phiên bản Spot là đáp án chính xác. Câu trả lời đúng là C vì Phiên bản dùng ngay là mô hình định giá cho phép công ty chạy khối lượng công việc tùy chỉnh, phi sản xuất hiện có trên Đám mây AWS một cách nhanh chóng và tiết kiệm chi phí."}, {"label": "D", "text_vi": "Máy chủ chuyên dụng", "is_correct": false, "analysis_vi": "Sai. Máy chủ chuyên dụng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '[]'::jsonb, NOW())
