INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-24', 'practice_283', 'Công cụ cơ sở dữ liệu nào tương thích với Amazon RDS?', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'Amazon RDS hỗ trợ sáu công cụ cơ sở dữ liệu: Amazon Aurora, MySQL, MariaDB, PostgreSQL, Oracle và SQL Server. Apache Cassandra, MongoDB và Neo4j không tương thích với Amazon RDS. Do đó, câu trả lời đúng là D. Bạn có thể tìm hiểu thêm về Amazon RDS và các công cụ cơ sở dữ liệu được hỗ trợ từ trang này.', '[{"label": "A", "text_vi": "Apache Cassandra", "is_correct": false, "analysis_vi": "Sai. Apache Cassandra, MongoDB và Neo4j không tương thích với Amazon RDS."}, {"label": "B", "text_vi": "MongoDB", "is_correct": false, "analysis_vi": "Sai. Apache Cassandra, MongoDB và Neo4j không tương thích với Amazon RDS."}, {"label": "C", "text_vi": "Neo4j", "is_correct": false, "analysis_vi": "Sai. Apache Cassandra, MongoDB và Neo4j không tương thích với Amazon RDS."}, {"label": "D", "text_vi": "PostgreSQL", "is_correct": true, "analysis_vi": "Đúng. PostgreSQL là đáp án chính xác. Amazon RDS hỗ trợ sáu công cụ cơ sở dữ liệu: Amazon Aurora, MySQL, MariaDB, PostgreSQL, Oracle và SQL Server."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon RDS"]'::jsonb, NOW())
