INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-25', 'practice_283', 'Một công ty có một ứng dụng sử dụng dịch vụ AWS. Trong các sự kiện mở rộng quy mô, công ty muốn duy trì mức sử dụng ứng dụng trong hạn mức dịch vụ AWS. Những dịch vụ hoặc công cụ AWS nào có thể báo cáo về hạn ngạch để công ty có thể cải thiện độ tin cậy của ứng dụng? (Chọn HAI.)', 'Domain 4: Billing, Pricing and Support', 'Khung kiến trúc tối ưu AWS (Well-Architected Framework)', 'Câu trả lời đúng là A và B vì bảng điều khiển Service Quotas và AWS Trusted Advisor là các dịch vụ hoặc công cụ AWS có thể báo cáo về hạn ngạch để công ty có thể cải thiện độ tin cậy của ứng dụng. Bảng điều khiển Định mức dịch vụ là một công cụ AWS cho phép người dùng xem và quản lý định mức của họ đối với các dịch vụ AWS từ một vị trí trung tâm. Người dùng có thể sử dụng bảng điều khiển Định mức dịch vụ để yêu cầu tăng hạn ngạch, theo dõi việc sử dụng hạn ngạch và thiết lập cảnh báo khi sắp đạt đến giới hạn hạn ngạch. AWS Trusted Advisor là dịch vụ AWS cung cấp hướng dẫn theo thời gian thực để giúp người dùng thực hiện theo các biện pháp thực hành tốt nhất của AWS về bảo mật, hiệu suất, tối ưu hóa chi phí và khả năng chịu lỗi. Một trong những hạng mục kiểm tra mà AWS Trusted Advisor thực hiện là giới hạn dịch vụ, giám sát việc sử dụng từng dịch vụ AWS và cảnh báo người dùng khi họ gần đạt đến giới hạn mặc định. Các tùy chọn khác không chính xác vì chúng không phải là dịch vụ hoặc công cụ AWS có thể báo cáo về hạn ngạch để công ty có thể cải thiện độ tin cậy của ứng dụng. AWS Systems Manager là dịch vụ AWS cho phép người dùng tự động hóa các tác vụ vận hành, quản lý cấu hình và tuân thủ cũng như giám sát tình trạng và hiệu suất của hệ thống. AWS Shield là dịch vụ AWS bảo vệ người dùng khỏi các cuộc tấn công từ chối dịch vụ (DDoS) phân tán. AWS Cost Explorer là một công cụ AWS cho phép người dùng trực quan hóa, hiểu và quản lý chi phí cũng như mức sử dụng AWS của họ.', '[{"label": "A", "text_vi": "Bảng điều khiển hạn ngạch dịch vụ", "is_correct": true, "analysis_vi": "Đúng. Bảng điều khiển hạn ngạch dịch vụ là đáp án chính xác. Câu trả lời đúng là A và B vì bảng điều khiển Service Quotas và AWS Trusted Advisor là các dịch vụ hoặc công cụ AWS có thể báo cáo về hạn ngạch để công ty có thể cải thiện độ tin cậy của ứng dụng."}, {"label": "B", "text_vi": "AWS Trusted Advisor", "is_correct": true, "analysis_vi": "Đúng. AWS Trusted Advisor là đáp án chính xác. Câu trả lời đúng là A và B vì bảng điều khiển Service Quotas và AWS Trusted Advisor là các dịch vụ hoặc công cụ AWS có thể báo cáo về hạn ngạch để công ty có thể cải thiện độ tin cậy của ứng dụng."}, {"label": "C", "text_vi": "Trình quản lý hệ thống AWS", "is_correct": false, "analysis_vi": "Sai. Trình quản lý hệ thống AWS: AWS Systems Manager cung cấp giao diện quản lý tập trung tài nguyên, tự động hóa tác vụ vận hành, quản lý bản vá (Patch Manager) và chạy lệnh (Run Command). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Khiên AWS", "is_correct": false, "analysis_vi": "Sai. Khiên AWS: AWS Shield là dịch vụ phòng chống tấn công từ chối dịch vụ phân tán (DDoS), bản Standard miễn phí tích hợp sẵn và bản Advanced hỗ trợ phản ứng 24/7 từ đội SRT. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "E", "text_vi": "Trình AWS Cost Explorer AWS", "is_correct": false, "analysis_vi": "Sai. Trình AWS Cost Explorer AWS: AWS Cost Explorer cung cấp giao diện trực quan để phân tích, hiểu rõ chi phí lịch sử và dự báo chi tiêu AWS trong tương lai lên đến 12 tháng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Trusted Advisor", "AWS Cost Explorer", "AWS Shield", "AWS Secrets Manager"]'::jsonb, NOW())
