INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-26', 'practice_283', 'Những dịch vụ AWS nào có thể được sử dụng để lưu trữ tệp? (Chọn HAI.)', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Amazon S3 và Amazon EBS là hai dịch vụ AWS có thể được sử dụng để lưu trữ tệp. Amazon S3 là dịch vụ lưu trữ đối tượng cung cấp khả năng mở rộng, độ bền, tính khả dụng và hiệu suất cao. Amazon EBS là dịch vụ lưu trữ khối cung cấp khối lượng lưu trữ liên tục và có độ trễ thấp cho các phiên bản Amazon EC2. AWS Lambda, Amazon SageMaker và AWS Storage Gateway là các dịch vụ AWS khác có các mục đích khác nhau, chẳng hạn như điện toán serverless, machine learning và lưu trữ đám mây lai .', '[{"label": "A", "text_vi": "Amazon S3", "is_correct": true, "analysis_vi": "Đúng. Amazon S3 là giải pháp đáp ứng yêu cầu. Amazon S3 và Amazon EBS là hai dịch vụ AWS có thể được sử dụng để lưu trữ tệp. Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website."}, {"label": "B", "text_vi": "AWS Lambda", "is_correct": false, "analysis_vi": "Sai. AWS Lambda: AWS Lambda là dịch vụ điện toán không máy chủ (Serverless), tự động chạy mã phản hồi sự kiện và tính phí chính xác theo mili-giây thực thi, không cần quản lý máy chủ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Cửa hàng khối đàn hồi Amazon (Amazon EBS)", "is_correct": true, "analysis_vi": "Đúng. Cửa hàng khối đàn hồi Amazon (Amazon EBS) là đáp án chính xác. Amazon EBS là dịch vụ lưu trữ khối cung cấp khối lượng lưu trữ liên tục và có độ trễ thấp cho các phiên bản Amazon EC2."}, {"label": "D", "text_vi": "Amazon SageMaker", "is_correct": false, "analysis_vi": "Sai. Amazon SageMaker không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "E", "text_vi": "AWS Storage Gateway", "is_correct": false, "analysis_vi": "Sai. AWS Storage Gateway: AWS Storage Gateway kết nối môi trường tại chỗ với lưu trữ đám mây AWS, cung cấp quyền truy cập liền mạch vào S3 và EBS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon S3", "AWS Lambda", "AWS Storage Gateway"]'::jsonb, NOW())
