INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-27', 'practice_283', 'Nhóm nào chia sẻ trách nhiệm với AWS về tính bảo mật và tuân thủ của các tài khoản và tài nguyên AWS?', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Khách hàng chia sẻ trách nhiệm với AWS về tính bảo mật và tuân thủ của các tài khoản và tài nguyên AWS. Đây là một phần của mô hình trách nhiệm chung của AWS, xác định sự phân chia trách nhiệm giữa AWS và khách hàng về vấn đề bảo mật và tuân thủ. AWS chịu trách nhiệm về tính bảo mật của đám mây, bao gồm các biện pháp kiểm soát vật lý và môi trường của cơ sở hạ tầng toàn cầu AWS, chẳng hạn như nguồn điện, làm mát, chữa cháy và truy cập vật lý. Khách hàng chịu trách nhiệm về bảo mật trên đám mây, bao gồm cấu hình và quản lý các tài nguyên và ứng dụng AWS, chẳng hạn như quản lý danh tính và quyền truy cập, mã hóa, tường lửa và sao lưu. Để biết thêm thông tin, hãy xem Mô hình trách nhiệm chung của AWS và Bảo mật đám mây AWS.', '[{"label": "A", "text_vi": "Nhà cung cấp bên thứ ba", "is_correct": false, "analysis_vi": "Sai. Nhà cung cấp bên thứ ba không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Khách hàng", "is_correct": true, "analysis_vi": "Đúng. Khách hàng là đáp án chính xác. Khách hàng chia sẻ trách nhiệm với AWS về tính bảo mật và tuân thủ của các tài khoản và tài nguyên AWS."}, {"label": "C", "text_vi": "Đối tác đại lý", "is_correct": false, "analysis_vi": "Sai. Đối tác đại lý không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Nhà cung cấp Internet", "is_correct": false, "analysis_vi": "Sai. Nhà cung cấp Internet không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '[]'::jsonb, NOW())
