INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-28', 'practice_283', 'Công ty nên áp dụng những nguyên tắc thiết kế nào cho khối lượng công việc trên Đám mây AWS để tối đa hóa tính bền vững và giảm thiểu tác động đến môi trường? (Chọn HAI.)', 'Domain 1: Cloud Concepts', 'Cloud Concepts', 'Để tối đa hóa tính bền vững và giảm thiểu tác động đến môi trường, công ty nên áp dụng các nguyên tắc thiết kế sau cho khối lượng công việc trên Đám mây AWS: tối đa hóa việc sử dụng các phiên bản Amazon EC2 và giảm nhu cầu người dùng cài đặt lại ứng dụng. Tối đa hóa việc sử dụng các phiên bản Amazon EC2 có nghĩa là công ty có thể tối ưu hóa hiệu suất và hiệu suất của các tài nguyên điện toán của mình, đồng thời tránh lãng phí năng lượng và tiền bạc cho các phiên bản nhàn rỗi hoặc không được sử dụng đúng mức. Công ty có thể sử dụng các tính năng như Amazon EC2 Auto Scaling, Amazon EC2 Spot Instances và AWS Computer Optimizer để tự động điều chỉnh số lượng và loại phiên bản dựa trên nhu cầu, chi phí và hiệu suất. Giảm nhu cầu người dùng cài đặt lại ứng dụng có nghĩa là công ty có thể giảm thiểu lượng dữ liệu và băng thông cần thiết để cung cấp ứng dụng của họ cho người dùng, đồng thời tránh các lượt tải xuống và cập nhật không cần thiết tiêu tốn năng lượng và tài nguyên. Công ty có thể sử dụng các dịch vụ như Amazon CloudFront, AWS AppStream 2.0 và AWS Amplify để cung cấp ứng dụng của họ nhanh hơn, an toàn hơn và hiệu quả hơn cho người dùng trên toàn cầu. Giảm thiểu việc sử dụng các phiên bản Amazon EC2, giảm thiểu việc sử dụng các dịch vụ được quản lý và buộc người dùng cài đặt lại ứng dụng thường xuyên không phải là những nguyên tắc thiết kế giúp tối đa hóa tính bền vững và giảm thiểu tác động đến môi trường. Việc giảm thiểu việc sử dụng phiên bản Amazon EC2 sẽ làm giảm hiệu năng và hiệu suất của tài nguyên điện toán, đồng thời có khả năng làm tăng chi phí cũng như độ phức tạp của khối lượng công việc trên đám mây. Việc giảm thiểu việc sử dụng các dịch vụ được quản lý sẽ làm tăng chi phí hoạt động và trách nhiệm của công ty, đồng thời có khả năng khiến họ gặp nhiều rủi ro về bảo mật và độ tin cậy hơn. Việc buộc người dùng cài đặt lại ứng dụng thường xuyên sẽ làm tăng lượng dữ liệu và băng thông cần thiết để cung cấp ứng dụng cho người dùng và có khả năng làm giảm trải nghiệm cũng như sự hài lòng của người dùng.', '[{"label": "A", "text_vi": "Tối đa hóa việc sử dụng các phiên bản Amazon EC2.", "is_correct": true, "analysis_vi": "Đúng. Tối đa hóa việc sử dụng các phiên bản Amazon EC2. là đáp án chính xác. Để tối đa hóa tính bền vững và giảm thiểu tác động đến môi trường, công ty nên áp dụng các nguyên tắc thiết kế sau cho khối lượng công việc trên Đám mây AWS: tối đa hóa việc sử dụng các phiên bản Amazon EC2 và giảm nhu cầu người dùng cài đặt lại ứng dụng."}, {"label": "B", "text_vi": "Giảm thiểu việc sử dụng các phiên bản Amazon EC2.", "is_correct": false, "analysis_vi": "Sai. Giảm thiểu việc sử dụng các phiên bản Amazon EC2.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Giảm thiểu việc sử dụng các dịch vụ được quản lý.", "is_correct": false, "analysis_vi": "Sai. Giảm thiểu việc sử dụng các dịch vụ được quản lý. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Buộc người dùng cài đặt lại ứng dụng thường xuyên.", "is_correct": false, "analysis_vi": "Sai. Buộc người dùng cài đặt lại ứng dụng thường xuyên. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "E", "text_vi": "Giảm nhu cầu người dùng cài đặt lại ứng dụng.", "is_correct": true, "analysis_vi": "Đúng. Giảm nhu cầu người dùng cài đặt lại ứng dụng. là đáp án chính xác. Để tối đa hóa tính bền vững và giảm thiểu tác động đến môi trường, công ty nên áp dụng các nguyên tắc thiết kế sau cho khối lượng công việc trên Đám mây AWS: tối đa hóa việc sử dụng các phiên bản Amazon EC2 và giảm nhu cầu người dùng cài đặt lại ứng dụng."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
