INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-29', 'practice_283', 'Một công ty muốn giảm thiểu độ trễ mạng giữa các phiên bản Amazon EC2 của mình. Các phiên bản EC2 không cần phải có tính khả dụng cao. Giải pháp nào đáp ứng được những yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'Sử dụng các phiên bản EC2 trong một Availability Zone (AZ) duy nhất là giải pháp đáp ứng yêu cầu giảm thiểu độ trễ mạng giữa các phiên bản EC2 và không cần tính sẵn sàng cao. Availability Zone (AZ) là một vị trí biệt lập về mặt vật lý trong AWS Region có nguồn điện, khả năng làm mát và kết nối mạng riêng. Các phiên bản EC2 trong cùng Availability Zone (AZ) có thể liên lạc với nhau bằng địa chỉ IP riêng có độ trễ thấp. Tuy nhiên, các phiên bản EC2 trong một Availability Zone (AZ) không có tính sẵn sàng cao vì chúng dễ bị lỗi hoặc gián đoạn ảnh hưởng đến Availability Zone (AZ)', '[{"label": "A", "text_vi": "Sử dụng các phiên bản EC2 trong một Availability Zone (AZ) duy nhất.", "is_correct": true, "analysis_vi": "Đúng. Sử dụng các phiên bản EC2 trong một Availability Zone (AZ) duy nhất. là đáp án chính xác. Sử dụng các phiên bản EC2 trong một Availability Zone (AZ) duy nhất là giải pháp đáp ứng yêu cầu giảm thiểu độ trễ mạng giữa các phiên bản EC2 và không cần tính sẵn sàng cao."}, {"label": "B", "text_vi": "Sử dụng Amazon CloudFront làm cơ sở dữ liệu cho các phiên bản EC2.", "is_correct": false, "analysis_vi": "Sai. Sử dụng các phiên bản EC2 trong một Availability Zone (AZ) duy nhất là giải pháp đáp ứng yêu cầu giảm thiểu độ trễ mạng giữa các phiên bản EC2 và không cần tính sẵn sàng cao."}, {"label": "C", "text_vi": "Sử dụng các phiên bản EC2 ở cùng vị trí biên và cùng Availability Zone (AZ).", "is_correct": false, "analysis_vi": "Sai. Sử dụng các phiên bản EC2 trong một Availability Zone (AZ) duy nhất là giải pháp đáp ứng yêu cầu giảm thiểu độ trễ mạng giữa các phiên bản EC2 và không cần tính sẵn sàng cao."}, {"label": "D", "text_vi": "Sử dụng các phiên bản EC2 ở cùng vị trí biên và cùng AWS Region.", "is_correct": false, "analysis_vi": "Sai. Sử dụng các phiên bản EC2 trong một Availability Zone (AZ) duy nhất là giải pháp đáp ứng yêu cầu giảm thiểu độ trễ mạng giữa các phiên bản EC2 và không cần tính sẵn sàng cao."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "Amazon CloudFront"]'::jsonb, NOW())
