INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-30', 'practice_283', 'Đặc điểm nào của Đám mây AWS giúp người dùng loại bỏ dung lượng CPU không được sử dụng đúng mức?', 'Domain 1: Cloud Concepts', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Độ co giãn là một đặc tính của Đám mây AWS giúp người dùng loại bỏ dung lượng CPU không được sử dụng đúng mức. Độ co giãn đề cập đến khả năng cung cấp và hủy cung cấp tài nguyên máy tính một cách linh hoạt theo nhu cầu, đảm bảo rằng ứng dụng hoặc dịch vụ luôn có các tài nguyên cần thiết để hoạt động hiệu quả. Độ co giãn giúp người dùng tối ưu hóa hiệu suất và chi phí, vì họ chỉ trả tiền cho những tài nguyên họ sử dụng và tránh lãng phí tài nguyên khi nhu cầu thấp345.', '[{"label": "A", "text_vi": "Nhanh nhẹn", "is_correct": true, "analysis_vi": "Đúng. Nhanh nhẹn là giải pháp đáp ứng yêu cầu. Độ co giãn là một đặc tính của Đám mây AWS giúp người dùng loại bỏ dung lượng CPU không được sử dụng đúng mức. Tính nhanh nhạy (Agility) giúp rút ngắn thời gian khởi tạo và thử nghiệm công nghệ từ hàng tuần xuống chỉ còn vài phút."}, {"label": "B", "text_vi": "Độ đàn hồi", "is_correct": false, "analysis_vi": "Sai. Độ đàn hồi: Độ co giãn (Elasticity) là khả năng hệ thống tự động tăng hoặc giảm tài nguyên máy tính chính xác theo nhu cầu tải công việc thực tế. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Độ tin cậy", "is_correct": false, "analysis_vi": "Sai. Độ tin cậy không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Độ bền", "is_correct": false, "analysis_vi": "Sai. Độ bền không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
