INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-32', 'practice_283', 'Có thể sử dụng dịch vụ hoặc tính năng nào của AWS để tạo kết nối riêng giữa khối lượng công việc tại chỗ và khối lượng công việc trên Đám mây AWS?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'AWS Direct Connect là dịch vụ thiết lập kết nối mạng chuyên dụng giữa mạng tại chỗ của bạn và một hoặc nhiều AWS Region. AWS Direct Connect có thể được sử dụng để tạo kết nối riêng giữa khối lượng công việc tại chỗ và khối lượng công việc trên Đám mây AWS, bỏ qua Internet công cộng và giảm chi phí mạng, độ trễ và các vấn đề về băng thông. AWS Direct Connect cũng có thể tăng cường độ bảo mật và độ tin cậy cho các ứng dụng đám mây lai và truyền dữ liệu của bạn.', '[{"label": "A", "text_vi": "Tuyến đường Amazon 53", "is_correct": false, "analysis_vi": "Sai. Tuyến đường Amazon 53: Amazon Route 53 là dịch vụ định tuyến DNS trên đám mây có tính khả dụng cao và hỗ trợ kiểm tra tình trạng sức khỏe (Health checks) cùng các chính sách định tuyến nâng cao. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon Macie", "is_correct": false, "analysis_vi": "Sai. Amazon Macie: Amazon Macie sử dụng máy học và đối sánh mẫu để tự động phát hiện, phân loại và bảo vệ dữ liệu nhạy cảm (như PII, số thẻ tín dụng) trên Amazon S3. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Kết nối trực tiếp AWS", "is_correct": true, "analysis_vi": "Đúng. Kết nối trực tiếp AWS là đáp án chính xác. AWS Direct Connect là dịch vụ thiết lập kết nối mạng chuyên dụng giữa mạng tại chỗ của bạn và một hoặc nhiều AWS Region."}, {"label": "D", "text_vi": "Liên kết riêng tư AWS", "is_correct": false, "analysis_vi": "Sai. Liên kết riêng tư AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon Route 53", "Amazon Macie", "AWS Direct Connect"]'::jsonb, NOW())
