INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-33', 'practice_283', 'Gói hỗ trợ AWS nào chỉ định nhân viên trợ giúp đặc biệt của AWS cho tài khoản của công ty?', 'Domain 4: Billing, Pricing and Support', 'Các gói hỗ trợ kỹ thuật AWS Support Plans', 'AWS Enterprise Support là gói AWS Support chỉ định một nhân viên trợ giúp đặc biệt của AWS cho tài khoản của công ty. Hỗ trợ doanh nghiệp AWS là mức hỗ trợ cao nhất mà AWS cung cấp và cung cấp hỗ trợ toàn diện và được cá nhân hóa nhất. Nhân viên trợ giúp đặc biệt của AWS là người quản lý tài khoản kỹ thuật chuyên dụng, đóng vai trò là đầu mối liên hệ duy nhất của công ty và giúp tối ưu hóa môi trường AWS, giải quyết vấn đề và tiếp cận các chuyên gia AWS. Để biết thêm thông tin, hãy xem [Gói hỗ trợ AWS] và [Hỗ trợ hướng dẫn khách của AWS].', '[{"label": "A", "text_vi": "Hỗ trợ cơ bản của AWS", "is_correct": false, "analysis_vi": "Sai. Hỗ trợ cơ bản của AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Hỗ trợ nhà phát triển AWS", "is_correct": false, "analysis_vi": "Sai. Hỗ trợ nhà phát triển AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Hỗ trợ kinh doanh của AWS", "is_correct": false, "analysis_vi": "Sai. Hỗ trợ kinh doanh của AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Hỗ trợ doanh nghiệp AWS", "is_correct": true, "analysis_vi": "Đúng. Hỗ trợ doanh nghiệp AWS là đáp án chính xác. AWS Enterprise Support là gói AWS Support chỉ định một nhân viên trợ giúp đặc biệt của AWS cho tài khoản của công ty."}]'::jsonb, '["Ghi nhớ các ngưỡng SLA phản hồi: Business (<1h cho production down, 24/7 phone/chat/email), Enterprise (<15m cho mission-critical, có TAM)."]'::jsonb, '[{"term": "support plan", "points_to": "Developer / Business / Enterprise"}]'::jsonb, '[]'::jsonb, NOW())
