INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-34', 'practice_283', 'Dịch vụ AWS nào cung cấp mã hóa ở trạng thái lưu trữ cho các ổ đĩa Amazon RDS và Amazon Elastic Block Store (Amazon EBS)?', 'Domain 2: Security and Compliance', 'Giải pháp cơ sở dữ liệu trên AWS', 'Dịch vụ quản lý khóa AWS (AWS KMS) là dịch vụ được quản lý cho phép bạn dễ dàng mã hóa dữ liệu của mình. AWS KMS cung cấp cho bạn khả năng kiểm soát tập trung các khóa mã hóa dùng để bảo vệ dữ liệu của bạn. Bạn có thể sử dụng AWS KMS để mã hóa dữ liệu trong các ổ Amazon RDS và Amazon EBS12', '[{"label": "A", "text_vi": "AWS Lambda", "is_correct": false, "analysis_vi": "Sai. AWS Lambda: AWS Lambda là dịch vụ điện toán không máy chủ (Serverless), tự động chạy mã phản hồi sự kiện và tính phí chính xác theo mili-giây thực thi, không cần quản lý máy chủ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Dịch vụ quản lý khóa AWS (AWS KMS)", "is_correct": true, "analysis_vi": "Đúng. Dịch vụ quản lý khóa AWS (AWS KMS) là đáp án chính xác. Dịch vụ quản lý khóa AWS (AWS KMS) là dịch vụ được quản lý cho phép bạn dễ dàng mã hóa dữ liệu của mình."}, {"label": "C", "text_vi": "AWSWAF", "is_correct": false, "analysis_vi": "Sai. AWSWAF: AWS WAF là tường lửa ứng dụng web hoạt động ở tầng 7 (HTTP/S), bảo vệ chống lại các lỗ hổng web phổ biến như SQL Injection và XSS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Nhận thức lại Amazon", "is_correct": false, "analysis_vi": "Sai. Nhận thức lại Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["AWS Lambda", "Amazon RDS", "AWS WAF", "AWS KMS"]'::jsonb, NOW())
