INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-35', 'practice_283', 'Công ty đang sử dụng AWS Lambda có trách nhiệm gì? (Chọn HAI.)', 'Domain 3: Cloud Technology and Services', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Nhiệm vụ của công ty đang sử dụng AWS Lambda là bảo mật bên trong mã cũng như viết và cập nhật mã. AWS Lambda là dịch vụ điện toán serverless cho phép bạn chạy mã mà không cần cung cấp hay quản lý máy chủ, thay đổi quy mô hay vá lỗi. AWS Lambda đảm nhiệm việc bảo mật cơ sở hạ tầng cơ bản, chẳng hạn như hệ điều hành, mạng và tường lửa. Tuy nhiên, công ty vẫn phải chịu trách nhiệm về tính bảo mật của chính mã đó, chẳng hạn như mã hóa dữ liệu nhạy cảm, xác thực đầu vào và xử lý lỗi. Công ty cũng chịu trách nhiệm viết và cập nhật mã xác định hàm Lambda cũng như chọn môi trường thời gian chạy, chẳng hạn như Node.js, Python hoặc Java. AWS Lambda không yêu cầu lựa chọn tài nguyên CPU vì nó tự động phân bổ chúng dựa trên cấu hình bộ nhớ34', '[{"label": "A", "text_vi": "Bảo mật bên trong mã", "is_correct": true, "analysis_vi": "Đúng. Bảo mật bên trong mã đáp ứng đầy đủ yêu cầu của đề bài. Nhiệm vụ của công ty đang sử dụng AWS Lambda là bảo mật bên trong mã cũng như viết và cập nhật mã."}, {"label": "B", "text_vi": "Lựa chọn tài nguyên CPU", "is_correct": false, "analysis_vi": "Sai. Lựa chọn tài nguyên CPU không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Vá lỗi hệ điều hành", "is_correct": false, "analysis_vi": "Sai. Vá lỗi hệ điều hành không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Viết và cập nhật mã", "is_correct": true, "analysis_vi": "Đúng. Viết và cập nhật mã là đáp án chính xác. Nhiệm vụ của công ty đang sử dụng AWS Lambda là bảo mật bên trong mã cũng như viết và cập nhật mã."}, {"label": "E", "text_vi": "Bảo mật cơ sở hạ tầng cơ bản", "is_correct": false, "analysis_vi": "Sai. Bảo mật cơ sở hạ tầng cơ bản không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["AWS Lambda"]'::jsonb, NOW())
