INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-36', 'practice_283', 'Công ty có gói AWS Business Support có thể sử dụng dịch vụ nào sau đây?', 'Domain 4: Billing, Pricing and Support', 'Các gói hỗ trợ kỹ thuật AWS Support Plans', 'API AWS Health được cung cấp cho công ty có gói AWS Business Support. API AWS Health cung cấp quyền truy cập theo chương trình vào thông tin AWS Health được trình bày trong Bảng thông tin sức khỏe cá nhân AWS. API AWS Health có thể giúp người dùng nhận được thông tin kịp thời và được cá nhân hóa về các sự kiện có thể ảnh hưởng đến tính khả dụng và hiệu suất của tài nguyên AWS của họ, chẳng hạn như bảo trì theo lịch, sự cố mạng hoặc gián đoạn dịch vụ. API AWS Health cũng có thể tích hợp với các dịch vụ AWS khác, chẳng hạn như Amazon CloudWatch Events và AWS Lambda, để kích hoạt các hành động và thông báo tự động. Tổng quan về API AWS Health Các gói hỗ trợ của AWS', '[{"label": "A", "text_vi": "Nhân viên hỗ trợ AWS", "is_correct": false, "analysis_vi": "Sai. Nhân viên hỗ trợ AWS: AWS Concierge là đội ngũ chuyên gia hỗ trợ thanh toán và tài khoản dành riêng cho khách hàng Enterprise Support. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Nhóm phản hồi DDoS của AWS (DRT)", "is_correct": false, "analysis_vi": "Sai. Nhóm phản hồi DDoS của AWS (DRT) không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Người quản lý tài khoản kỹ thuật AWS (TAM)", "is_correct": false, "analysis_vi": "Sai. Người quản lý tài khoản kỹ thuật AWS (TAM): Technical Account Manager (TAM) là chuyên gia kỹ thuật cấp cao được chỉ định riêng cho khách hàng gói Enterprise Support để hướng dẫn và tối ưu hóa kiến trúc. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "API sức khỏe AWS", "is_correct": true, "analysis_vi": "Đúng. API sức khỏe AWS là đáp án chính xác. API AWS Health được cung cấp cho công ty có gói AWS Business Support."}]'::jsonb, '["Ghi nhớ các ngưỡng SLA phản hồi: Business (<1h cho production down, 24/7 phone/chat/email), Enterprise (<15m cho mission-critical, có TAM)."]'::jsonb, '[{"term": "support plan", "points_to": "Developer / Business / Enterprise"}]'::jsonb, '["AWS Secrets Manager"]'::jsonb, NOW())
