INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-37', 'practice_283', 'Một công ty đang sử dụng Amazon RDS. Một công ty đang triển khai một ứng dụng kinh doanh quan trọng trong AWS Region. Làm thế nào công ty có thể tăng khả năng phục hồi cho ứng dụng này?', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'Triển khai ứng dụng bằng cách sử dụng nhiều Availability Zone (AZ) là cách tốt nhất để tăng khả năng phục hồi cho ứng dụng. Theo Hướng dẫn sử dụng Amazon RDS, "Amazon RDS cung cấp khả năng sẵn sàng cao và hỗ trợ chuyển đổi dự phòng cho các phiên bản DB sử dụng triển khai Multi-AZ. Khi triển khai Multi-AZ, Amazon RDS tự động cung cấp và duy trì một bản sao dự phòng đồng bộ trong một Availability Zone (AZ) khác. Phiên bản DB chính được sao chép đồng bộ trên các Availability Zone (AZ) sang một bản sao dự phòng để cung cấp dự phòng dữ liệu, loại bỏ tình trạng đóng băng I/O và giảm thiểu độ trễ đột biến trong quá trình sao lưu hệ thống."4 việc sử dụng nhiều VPC hoặc sử dụng nhiều mạng con không mang lại mức độ phục hồi giống như sử dụng nhiều Availability Zone (AZ).', '[{"label": "A", "text_vi": "Triển khai bản sao của ứng dụng trong tài khoản AWS khác.", "is_correct": false, "analysis_vi": "Sai. Triển khai bản sao của ứng dụng trong tài khoản AWS khác. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Triển khai ứng dụng bằng cách sử dụng nhiều VPC.", "is_correct": false, "analysis_vi": "Sai. Triển khai ứng dụng bằng cách sử dụng nhiều VPC.: Amazon VPC cho phép khởi tạo mạng ảo riêng biệt được cô lập logic trên đám mây AWS, kiểm soát toàn diện dải IP, subnet, bảng định tuyến và cổng mạng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Triển khai ứng dụng bằng cách sử dụng nhiều mạng con.", "is_correct": false, "analysis_vi": "Sai. Triển khai ứng dụng bằng cách sử dụng nhiều mạng con. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Triển khai ứng dụng bằng cách sử dụng nhiều Availability Zone (AZ).", "is_correct": true, "analysis_vi": "Đúng. Triển khai ứng dụng bằng cách sử dụng nhiều Availability Zone (AZ). là đáp án chính xác. Triển khai ứng dụng bằng cách sử dụng nhiều Availability Zone (AZ) là cách tốt nhất để tăng khả năng phục hồi cho ứng dụng."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon RDS", "Amazon VPC"]'::jsonb, NOW())
