INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-38', 'practice_283', 'Một công ty muốn tạo một bộ bảng thông tin tùy chỉnh để thu thập số liệu nhằm giám sát các ứng dụng của mình. Dịch vụ AWS nào sẽ đáp ứng những yêu cầu này?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'Amazon CloudWatch là dịch vụ cung cấp khả năng giám sát và quan sát các tài nguyên và ứng dụng AWS. Người dùng có thể tạo trang tổng quan tùy chỉnh để thu thập và trực quan hóa số liệu, nhật ký, cảnh báo và sự kiện từ các nguồn khác nhau5. AWS X-Ray là dịch vụ cung cấp khả năng theo dõi và phân tích phân tán cho các ứng dụng. AWS Systems Manager là dịch vụ cung cấp khả năng quản lý vận hành cho các tài nguyên và ứng dụng AWS. AWS CloudTrail là dịch vụ cung cấp khả năng quản trị, tuân thủ và kiểm tra hoạt động tài khoản AWS.', '[{"label": "A", "text_vi": "Amazon CloudWatch", "is_correct": true, "analysis_vi": "Đúng. Amazon CloudWatch là đáp án chính xác. Amazon CloudWatch là dịch vụ cung cấp khả năng giám sát và quan sát các tài nguyên và ứng dụng AWS."}, {"label": "B", "text_vi": "X-Ray của AWS", "is_correct": false, "analysis_vi": "Sai. X-Ray của AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Trình quản lý hệ thống AWS", "is_correct": false, "analysis_vi": "Sai. Trình quản lý hệ thống AWS: AWS Systems Manager cung cấp giao diện quản lý tập trung tài nguyên, tự động hóa tác vụ vận hành, quản lý bản vá (Patch Manager) và chạy lệnh (Run Command). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "AWS CloudTrail", "is_correct": false, "analysis_vi": "Sai. AWS CloudTrail: AWS CloudTrail ghi nhật ký và giám sát toàn bộ hoạt động gọi API của tài khoản AWS, phục vụ quản trị, kiểm toán bảo mật và tuân thủ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon RDS", "Amazon CloudWatch", "AWS CloudTrail", "AWS Secrets Manager"]'::jsonb, NOW())
