INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-39', 'practice_283', 'Một công ty đã triển khai phiên bản Amazon EC2. Tùy chọn nào là trách nhiệm của AWS theo mô hình trách nhiệm chung của AWS?', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Theo mô hình trách nhiệm chung của AWS, AWS chịu trách nhiệm bảo vệ cơ sở hạ tầng chạy tất cả các dịch vụ được cung cấp trên Đám mây AWS, chẳng hạn như trung tâm dữ liệu, phần cứng, phần mềm, mạng và cơ sở vật chất1. Điều này bao gồm cấu hình của các thiết bị cơ sở hạ tầng, chẳng hạn như bộ định tuyến, bộ chuyển mạch, tường lửa và Load Balancer (ELB)2. Khách hàng chịu trách nhiệm quản lý dữ liệu, ứng dụng, hệ điều hành, Security Group và các khía cạnh khác trong môi trường AWS của họ1. Do đó, các tùy chọn A, B và D là trách nhiệm của khách hàng chứ không phải trách nhiệm của AWS.', '[{"label": "A", "text_vi": "Quản lý và mã hóa dữ liệu ứng dụng", "is_correct": false, "analysis_vi": "Sai. Quản lý và mã hóa dữ liệu ứng dụng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Cài đặt bản cập nhật và bản vá bảo mật của hệ điều hành khách", "is_correct": false, "analysis_vi": "Sai. Cài đặt bản cập nhật và bản vá bảo mật của hệ điều hành khách không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Cấu hình các thiết bị hạ tầng", "is_correct": true, "analysis_vi": "Đúng. Cấu hình các thiết bị hạ tầng là đáp án chính xác. Theo mô hình trách nhiệm chung của AWS, AWS chịu trách nhiệm bảo vệ cơ sở hạ tầng chạy tất cả các dịch vụ được cung cấp trên Đám mây AWS, chẳng hạn như trung tâm dữ liệu, phần cứng, phần mềm, mạng và cơ sở vật chất1."}, {"label": "D", "text_vi": "Cấu hình Security Group trên từng phiên bản", "is_correct": false, "analysis_vi": "Sai. Cấu hình Security Group trên từng phiên bản: Security Group là tường lửa ảo ở cấp instance, hoạt động có trạng thái (Stateful) và chỉ cấu hình các quy tắc cho phép (Allow rules). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
ON CONFLICT (question_id) DO UPDATE SET
