INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-40', 'practice_283', 'Một công ty cần thực hiện xử lý dữ liệu mỗi tuần một lần và thường mất khoảng 5 giờ để hoàn thành. Công ty nên sử dụng dịch vụ AWS nào cho khối lượng công việc này?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'Amazon EC2 là dịch vụ AWS phù hợp nhất cho khối lượng công việc này. Amazon EC2 cung cấp khả năng tính toán bảo mật và có thể thay đổi kích thước trên đám mây. Bạn có thể khởi chạy các máy chủ ảo, được gọi là phiên bản và định cấu hình chúng theo nhu cầu của mình. Bạn có thể chọn từ các loại phiên bản, kích cỡ và dòng phiên bản khác nhau, đồng thời chỉ trả tiền cho những tài nguyên bạn sử dụng. Amazon EC2 cũng cung cấp các tính năng như tự động thay đổi quy mô, cân bằng tải, Security Group và nhóm vị trí để tối ưu hóa hiệu suất, tính khả dụng và bảo mật1 của bạn. Amazon EC2 lý tưởng cho các khối lượng công việc đòi hỏi sức mạnh tính toán ổn định và đáng tin cậy, chẳng hạn như xử lý dữ liệu, lưu trữ web, chơi game và điện toán hiệu năng cao2. Các dịch vụ khác không phù hợp với khối lượng công việc này. AWS Lambda là dịch vụ điện toán serverless cho phép bạn chạy mã mà không cần cung cấp hay quản lý máy chủ. Bạn chỉ trả tiền cho thời gian tính toán mà bạn sử dụng. Lambda là lựa chọn tốt nhất cho khối lượng công việc ngắn hạn, không trạng thái và theo hướng sự kiện có thể hoàn thành trong vòng chưa đầy 15 phút3. AWS CodeDeploy là dịch vụ triển khai tự động hóa việc triển khai ứng dụng cho các phiên bản Amazon EC2, phiên bản tại chỗ, chức năng Lambda không có máy chủ hoặc dịch vụ Amazon ECS. CodeDeploy không phải là một dịch vụ điện toán mà là một công cụ giúp bạn cập nhật ứng dụng của mình với thời gian ngừng hoạt động ở mức tối thiểu4. AWS Wavelength là dịch vụ cung cấp các ứng dụng có độ trễ cực thấp cho thiết bị 5G. Wavelength nhúng các dịch vụ điện toán và lưu trữ AWS ở rìa mạng 5G của nhà cung cấp viễn thông. Wavelength được thiết kế cho điện toán biên di động, chẳng hạn như chơi game tương tác, truyền phát video và thực tế tăng cường.', '[{"label": "A", "text_vi": "AWS Lambda", "is_correct": true, "analysis_vi": "Đúng. AWS Lambda là đáp án chính xác. AWS Lambda là dịch vụ điện toán serverless cho phép bạn chạy mã mà không cần cung cấp hay quản lý máy chủ."}, {"label": "B", "text_vi": "Amazon EC2", "is_correct": false, "analysis_vi": "Sai. Amazon EC2: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "AWS CodeDeploy", "is_correct": false, "analysis_vi": "Sai. AWS CodeDeploy là dịch vụ triển khai tự động hóa việc triển khai ứng dụng cho các phiên bản Amazon EC2, phiên bản tại chỗ, chức năng Lambda không có máy chủ hoặc dịch vụ Amazon ECS."}, {"label": "D", "text_vi": "Bước sóng AWS", "is_correct": false, "analysis_vi": "Sai. Bước sóng AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "AWS Lambda"]'::jsonb, NOW())
