INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-41', 'practice_283', 'Một công ty đã tạo Báo cáo chi phí và mức sử dụng AWS và muốn trực quan hóa báo cáo. Công ty nên sử dụng dịch vụ AWS nào để nhập và hiển thị thông tin này?', 'Domain 3: Cloud Technology and Services', 'Quản lý chi phí & Thanh toán AWS', 'Amazon QuickSight là dịch vụ AWS cung cấp khả năng trực quan hóa dữ liệu và thông tin kinh doanh. Amazon QuickSight cho phép bạn nhập, phân tích và hiển thị dữ liệu từ nhiều nguồn khác nhau, chẳng hạn như Báo cáo chi phí và mức sử dụng AWS, Amazon S3, Amazon Athena, Amazon Redshift và Amazon RDS. Bạn có thể sử dụng Amazon QuickSight để tạo bảng thông tin và biểu đồ tương tác hiển thị thông tin chi tiết và xu hướng từ dữ liệu của bạn. Bạn cũng có thể chia sẻ trang tổng quan và biểu đồ của mình với những người dùng khác hoặc nhúng chúng vào ứng dụng của bạn.', '[{"label": "A", "text_vi": "Amazon QuickSight", "is_correct": true, "analysis_vi": "Đúng. Amazon QuickSight là đáp án chính xác. Amazon QuickSight là dịch vụ AWS cung cấp khả năng trực quan hóa dữ liệu và thông tin kinh doanh."}, {"label": "B", "text_vi": "Điểm chính xác của Amazon", "is_correct": false, "analysis_vi": "Sai. Điểm chính xác của Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Sao Hải Vương Amazon", "is_correct": false, "analysis_vi": "Sai. Sao Hải Vương Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Amazon Kinesis", "is_correct": false, "analysis_vi": "Sai. Amazon Kinesis không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '[]'::jsonb, NOW())
