INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-42', 'practice_283', 'Tùy chọn nào là trụ cột của Khung kiến trúc tối ưu AWS?', 'Domain 1: Cloud Concepts', 'Khung kiến trúc tối ưu AWS (Well-Architected Framework)', 'Khung kiến trúc tối ưu AWS giúp bạn hiểu được ưu và nhược điểm của các quyết định bạn đưa ra khi xây dựng hệ thống trên AWS. Bằng cách sử dụng Khung, bạn sẽ tìm hiểu các phương pháp kiến ​​trúc tốt nhất để thiết kế và vận hành các hệ thống đáng tin cậy, an toàn, hiệu quả và tiết kiệm chi phí trên đám mây. Khung bao gồm năm trụ cột: hoạt động xuất sắc, bảo mật, độ tin cậy, hiệu quả hoạt động và tối ưu hóa chi phí2.', '[{"label": "A", "text_vi": "Quản lý bản vá", "is_correct": false, "analysis_vi": "Sai. Quản lý bản vá không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Tối ưu hóa chi phí", "is_correct": true, "analysis_vi": "Đúng. Tối ưu hóa chi phí đáp ứng đầy đủ yêu cầu của đề bài. Khung kiến trúc tối ưu AWS giúp bạn hiểu được ưu và nhược điểm của các quyết định bạn đưa ra khi xây dựng hệ thống trên AWS."}, {"label": "C", "text_vi": "Chiến lược công nghệ kinh doanh", "is_correct": false, "analysis_vi": "Sai. Chiến lược công nghệ kinh doanh không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Kiểm soát vật lý và môi trường", "is_correct": false, "analysis_vi": "Sai. Kiểm soát vật lý và môi trường không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
