INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-43', 'practice_283', 'Một công ty đang xây dựng một ứng dụng cần phân phối hình ảnh và video trên toàn cầu với độ trễ tối thiểu. Công ty có thể sử dụng cách tiếp cận nào để thực hiện điều này một cách hiệu quả về mặt chi phí?', 'Domain 2: Security and Compliance', 'Quản lý chi phí & Thanh toán AWS', 'Amazon CloudFront là dịch vụ mạng phân phối nội dung (CDN) nhanh, cung cấp dữ liệu, video, ứng dụng và API một cách an toàn cho khách hàng trên toàn cầu với độ trễ thấp, tốc độ truyền cao, tất cả đều trong môi trường thân thiện với nhà phát triển. Nó hoạt động liền mạch với các dịch vụ bao gồm AWS Shield để giảm thiểu DDoS, Amazon S3, Elastic Load Balancing hoặc Amazon EC2 làm nguồn gốc cho ứng dụng của bạn và Lambda@Edge để chạy mã tùy chỉnh gần hơn với người dùng của khách hàng và tùy chỉnh trải nghiệm người dùng. Bằng cách sử dụng CloudFront, bạn có thể lưu nội dung của mình vào bộ nhớ đệm ở các vị trí biên gần nhất với người dùng cuối, giảm độ trễ mạng và cải thiện hiệu suất ứng dụng của bạn. CloudFront cũng cung cấp mô hình định giá trả theo mức sử dụng, do đó bạn chỉ phải trả tiền cho việc truyền dữ liệu và các yêu cầu mà bạn sử dụng.', '[{"label": "A", "text_vi": "Cung cấp nội dung thông qua Amazon CloudFront.", "is_correct": true, "analysis_vi": "Đúng. Cung cấp nội dung thông qua Amazon CloudFront. là đáp án chính xác. Amazon CloudFront là dịch vụ mạng phân phối nội dung (CDN) nhanh, cung cấp dữ liệu, video, ứng dụng và API một cách an toàn cho khách hàng trên toàn cầu với độ trễ thấp, tốc độ truyền cao, tất cả đều trong môi trường thân thiện với nhà phát triển."}, {"label": "B", "text_vi": "Lưu trữ nội dung trên Amazon S3 và cho phép sao chép giữa các vùng của S3.", "is_correct": false, "analysis_vi": "Sai. Lưu trữ nội dung trên Amazon S3 và cho phép sao chép giữa các vùng của S3.: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Triển khai VPN trên nhiều AWS Region.", "is_correct": false, "analysis_vi": "Sai. Triển khai VPN trên nhiều AWS Region.: AWS Site-to-Site VPN tạo kết nối mạng riêng ảo bảo mật qua đường truyền Internet công cộng bằng giao thức IPsec giữa mạng on-premises và AWS VPC. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Cung cấp nội dung thông qua AWS PrivateLink.", "is_correct": false, "analysis_vi": "Sai. Cung cấp nội dung thông qua AWS PrivateLink. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["Amazon S3", "Amazon CloudFront"]'::jsonb, NOW())
