INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-44', 'practice_283', 'Dịch vụ AWS nào cung cấp cho người dùng khả năng khám phá và bảo vệ dữ liệu nhạy cảm được lưu trữ trong bộ chứa Amazon S3?', 'Domain 2: Security and Compliance', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Amazon Macie là dịch vụ bảo mật và quyền riêng tư dữ liệu do AWS cung cấp, sử dụng máy học và khớp mẫu để khám phá dữ liệu nhạy cảm được lưu trữ trong Amazon S3. Bạn có thể xác định loại danh mục dữ liệu nhạy cảm tùy chỉnh của riêng mình, loại danh mục này có thể dành riêng cho doanh nghiệp hoặc trường hợp sử dụng của bạn. Macie cũng cung cấp cho bạn các bảng thông tin và cảnh báo giúp bạn hiểu rõ cách dữ liệu của bạn đang được truy cập hoặc di chuyển. Macie giúp bạn bảo vệ dữ liệu của mình bằng cách cho phép bạn áp dụng các kỹ thuật bảo vệ dữ liệu như mã hóa, xóa, kiểm soát truy cập và kiểm tra.', '[{"label": "A", "text_vi": "Amazon Macie", "is_correct": true, "analysis_vi": "Đúng. Amazon Macie là đáp án chính xác. Amazon Macie là dịch vụ bảo mật và quyền riêng tư dữ liệu do AWS cung cấp, sử dụng máy học và khớp mẫu để khám phá dữ liệu nhạy cảm được lưu trữ trong Amazon S3."}, {"label": "B", "text_vi": "Thám tử Amazon", "is_correct": false, "analysis_vi": "Sai. Thám tử Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Nhiệm vụ bảo vệ của Amazon", "is_correct": false, "analysis_vi": "Sai. Nhiệm vụ bảo vệ của Amazon: Amazon GuardDuty là dịch vụ phát hiện mối đe dọa thông minh sử dụng máy học để liên tục phân tích VPC Flow Logs, CloudTrail Logs và DNS Logs. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Trình phân tích truy cập AWS I AM", "is_correct": false, "analysis_vi": "Sai. Trình phân tích truy cập AWS I AM không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon S3", "Amazon GuardDuty", "Amazon Macie"]'::jsonb, NOW())
