INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-45', 'practice_283', 'Một công ty muốn theo dõi hiệu suất khối lượng công việc của mình. Công ty muốn đảm bảo rằng các dịch vụ đám mây được cung cấp ở mức độ đáp ứng nhu cầu kinh doanh của mình. Phối cảnh Khung áp dụng đám mây AWS (AWS CAF) nào sẽ đáp ứng các yêu cầu này?', 'Domain 1: Cloud Concepts', 'Cloud Concepts', 'Phối cảnh Hoạt động giúp bạn giám sát và quản lý khối lượng công việc trên đám mây để đảm bảo rằng chúng được phân phối ở mức đáp ứng nhu cầu kinh doanh của bạn. Các bên liên quan phổ biến bao gồm giám đốc vận hành (COO), giám đốc đám mây, người quản lý vận hành đám mây và kỹ sư vận hành đám mây1. Phối cảnh Hoạt động bao gồm các khả năng như giám sát tình trạng khối lượng công việc, quản lý sự cố, quản lý thay đổi, quản lý phát hành, quản lý cấu hình và khắc phục thảm họa2. Quan điểm Kinh doanh giúp đảm bảo rằng các khoản đầu tư vào đám mây của bạn sẽ đẩy nhanh tham vọng chuyển đổi kỹ thuật số và kết quả kinh doanh của bạn. Các bên liên quan phổ biến bao gồm giám đốc điều hành (CEO), giám đốc tài chính (CFO), giám đốc thông tin (CIO) và giám đốc công nghệ (CTO). Quan điểm Kinh doanh bao gồm các khả năng như phát triển đề án kinh doanh, hiện thực hóa giá trị, quản lý danh mục đầu tư và quản lý các bên liên quan3. Phối cảnh Quản trị giúp bạn điều phối các sáng kiến ​​đám mây của mình đồng thời tối đa hóa lợi ích của tổ chức và giảm thiểu rủi ro liên quan đến chuyển đổi. Các bên liên quan phổ biến bao gồm giám đốc chuyển đổi, CIO, CTO, CFO, giám đốc dữ liệu (CDO) và giám đốc rủi ro (CRO). Khía cạnh Quản trị bao gồm các khả năng như khung quản trị, quản lý ngân sách và chi phí, quản lý tuân thủ và quản trị dữ liệu4. Phối cảnh Nền tảng giúp bạn xây dựng nền tảng đám mây lai, có thể mở rộng, cấp doanh nghiệp, hiện đại hóa khối lượng công việc hiện có và triển khai các giải pháp gốc đám mây mới. Các bên liên quan phổ biến bao gồm CTO, lãnh đạo công nghệ, kiến ​​trúc sư và kỹ sư. Phối cảnh Nền tảng bao gồm các khả năng như thiết kế và triển khai nền tảng, di chuyển và hiện đại hóa khối lượng công việc, phát triển trên nền tảng đám mây và DevOps5.', '[{"label": "A", "text_vi": "Kinh doanh", "is_correct": false, "analysis_vi": "Sai. Kinh doanh không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Quản trị", "is_correct": false, "analysis_vi": "Sai. Quản trị không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Nền tảng", "is_correct": false, "analysis_vi": "Sai. Nền tảng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Hoạt động", "is_correct": true, "analysis_vi": "Đúng. Hoạt động là đáp án chính xác. Phối cảnh Hoạt động giúp bạn giám sát và quản lý khối lượng công việc trên đám mây để đảm bảo rằng chúng được phân phối ở mức đáp ứng nhu cầu kinh doanh của bạn."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
