  updated_at = NOW();

INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-46', 'practice_283', 'Nhóm CNTT của một công ty đang quản lý các cụm máy chủ cơ sở dữ liệu MySQL. Nhóm CNTT phải vá cơ sở dữ liệu và chụp ảnh sao lưu dữ liệu trong các cụm. Công ty muốn chuyển khối lượng công việc này sang AWS để các nhiệm vụ này được hoàn thành tự động. Công ty phải làm gì để đáp ứng được những yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'Công ty nên sử dụng Amazon RDS với cơ sở dữ liệu MySQL để đáp ứng yêu cầu chuyển khối lượng công việc của mình sang AWS để các tác vụ vá cơ sở dữ liệu và chụp ảnh sao lưu dữ liệu trong các cụm sẽ được hoàn thành tự động. Amazon RDS là dịch vụ được quản lý giúp đơn giản hóa việc thiết lập, vận hành và thay đổi quy mô cơ sở dữ liệu quan hệ trên Đám mây AWS. Amazon RDS tự động hóa các tác vụ quản trị cơ sở dữ liệu phổ biến như vá lỗi, sao lưu và phục hồi. Amazon RDS cũng hỗ trợ MySQL và các công cụ cơ sở dữ liệu phổ biến khác5 Các bãi chứa AWS-Certified-Cloud-Practitioner hợp lệ được EduDump.com chia sẻ để giúp vượt qua kỳ thi dành cho người thực hành trên nền tảng đám mây được chứng nhận AWS! EduDump.com hiện cung cấp các kết xuất bài thi AWS- Certified-Cloud-Practitioner mới nhất, các câu hỏi thi EduDump.com AWS-Certified-Cloud-Practitioner đã được cập nhật và các câu trả lời đã được sửa. Hãy tải các kết xuất bài thi EduDump.com AWS-Certified-Cloud-Practitioner mới nhất với Test Engine tại đây: https://www.edudump.com/exams/Amazon/AWS-Certified-Cloud-Practitioner/premium/ ( 600 lượt hỏi đáp, GIẢM GIÁ 35% Mã giảm giá đặc biệt: freecram )', '[{"label": "A", "text_vi": "Triển khai cụm máy chủ cơ sở dữ liệu MySQL trên các phiên bản Amazon EC2.", "is_correct": false, "analysis_vi": "Sai. Triển khai cụm máy chủ cơ sở dữ liệu MySQL trên các phiên bản Amazon EC2.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Sử dụng Amazon RDS với cơ sở dữ liệu MySQL.", "is_correct": true, "analysis_vi": "Đúng. Sử dụng Amazon RDS với cơ sở dữ liệu MySQL. là đáp án chính xác. Công ty nên sử dụng Amazon RDS với cơ sở dữ liệu MySQL để đáp ứng yêu cầu chuyển khối lượng công việc của mình sang AWS để các tác vụ vá cơ sở dữ liệu và chụp ảnh sao lưu dữ liệu trong các cụm sẽ được hoàn thành tự động."}, {"label": "C", "text_vi": "Sử dụng mẫu AWS Cloud Form tại ion để triển khai máy chủ cơ sở dữ liệu MySQL trên phiên bản Amazon EC2.", "is_correct": false, "analysis_vi": "Sai. Sử dụng mẫu AWS Cloud Form tại ion để triển khai máy chủ cơ sở dữ liệu MySQL trên phiên bản Amazon EC2.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Di chuyển tất cả dữ liệu cơ sở dữ liệu MySQL sang Amazon S3.", "is_correct": false, "analysis_vi": "Sai. Di chuyển tất cả dữ liệu cơ sở dữ liệu MySQL sang Amazon S3.: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "Amazon S3", "Amazon RDS"]'::jsonb, NOW())
