INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-47', 'practice_283', 'Hoạt động nào là trách nhiệm của khách hàng trên Đám mây AWS theo mô hình trách nhiệm chung của AWS?', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Mô hình trách nhiệm chung của AWS mô tả cách AWS và khách hàng chia sẻ trách nhiệm về tính bảo mật và tuân thủ của môi trường AWS. AWS chịu trách nhiệm về bảo mật của đám mây, bao gồm bảo mật vật lý của các cơ sở AWS, cơ sở hạ tầng, phần cứng, phần mềm và mạng chạy các dịch vụ AWS. Khách hàng chịu trách nhiệm về bảo mật trên đám mây, bao gồm cấu hình Security Group, mã hóa dữ liệu khách hàng trên AWS, quản lý cơ sở hạ tầng AWS Lambda và quản lý thông lượng mạng của từng AWS Region. Một trong những trách nhiệm của khách hàng là đảm bảo rằng khối lượng Amazon EBS được sao lưu.', '[{"label": "A", "text_vi": "Đảm bảo kết nối mạng từ AWS ra internet", "is_correct": false, "analysis_vi": "Sai. Đảm bảo kết nối mạng từ AWS ra internet không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Vá và sửa các lỗi trong cơ sở hạ tầng Đám mây AWS", "is_correct": false, "analysis_vi": "Sai. Vá và sửa các lỗi trong cơ sở hạ tầng Đám mây AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Đảm bảo an ninh vật lý của trung tâm dữ liệu đám mây", "is_correct": false, "analysis_vi": "Sai. Đảm bảo an ninh vật lý của trung tâm dữ liệu đám mây không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Đảm bảo khối lượng Amazon EBS được sao lưu", "is_correct": true, "analysis_vi": "Đúng. Đảm bảo khối lượng Amazon EBS được sao lưu là đáp án chính xác. Khách hàng chịu trách nhiệm về bảo mật trên đám mây, bao gồm cấu hình Security Group, mã hóa dữ liệu khách hàng trên AWS, quản lý cơ sở hạ tầng AWS Lambda và quản lý thông lượng mạng của từng AWS Region."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["AWS Direct Connect"]'::jsonb, NOW())
