INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-48', 'practice_283', 'Một công ty đã triển khai ứng dụng trên phiên bản Amazon EC2. Công ty cần đánh giá các lỗ hổng ứng dụng và phải xác định việc triển khai cơ sở hạ tầng không đáp ứng các phương pháp hay nhất. Công ty có thể sử dụng dịch vụ AWS nào để đáp ứng các yêu cầu này?', 'Domain 2: Security and Compliance', 'Dịch vụ điện toán đám mây Amazon EC2', 'Amazon Inspector là dịch vụ cung cấp khả năng quản lý và đánh giá bảo mật tự động cho các tài nguyên AWS, chẳng hạn như phiên bản Amazon EC2. Amazon Inspector có thể quét các ứng dụng để tìm các lỗ hổng phổ biến, chẳng hạn như chèn SQL, tạo tập lệnh chéo trang và thực thi mã từ xa. Amazon Inspector cũng có thể kiểm tra cấu hình của tài nguyên AWS dựa trên các biện pháp bảo mật tốt nhất, chẳng hạn như Điểm chuẩn CIS và Biện pháp thực hành tốt nhất về bảo mật AWS. Amazon Inspector có thể giúp khách hàng xác định và khắc phục các sự cố bảo mật, tuân thủ các tiêu chuẩn bảo mật và cải thiện tình trạng bảo mật trong môi trường AWS của họ12.', '[{"label": "A", "text_vi": "AWS Trusted Advisor", "is_correct": false, "analysis_vi": "Sai. AWS Trusted Advisor: AWS Trusted Advisor quét toàn bộ tài khoản AWS và đưa ra khuyến nghị tối ưu theo 5 trụ cột: Chi phí, Hiệu năng, Bảo mật, Khả năng chịu lỗi và Giới hạn dịch vụ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon Inspector", "is_correct": true, "analysis_vi": "Đúng. Amazon Inspector là đáp án chính xác. Amazon Inspector là dịch vụ cung cấp khả năng quản lý và đánh giá bảo mật tự động cho các tài nguyên AWS, chẳng hạn như phiên bản Amazon EC2."}, {"label": "C", "text_vi": "Cấu hình AWS", "is_correct": false, "analysis_vi": "Sai. Cấu hình AWS: AWS Config liên tục ghi lại và đánh giá các thay đổi cấu hình tài nguyên so với các quy tắc tuân thủ mong muốn. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Nhiệm vụ bảo vệ của Amazon", "is_correct": false, "analysis_vi": "Sai. Nhiệm vụ bảo vệ của Amazon: Amazon GuardDuty là dịch vụ phát hiện mối đe dọa thông minh sử dụng máy học để liên tục phân tích VPC Flow Logs, CloudTrail Logs và DNS Logs. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "AWS Trusted Advisor", "Amazon GuardDuty", "Amazon Inspector"]'::jsonb, NOW())
