INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-49', 'practice_283', 'Một công ty đang chạy ứng dụng của mình trên Đám mây AWS. Công ty muốn xem xét định kỳ tài khoản AWS của mình để tìm cơ hội tối ưu hóa chi phí. Công ty có thể sử dụng dịch vụ hoặc công cụ AWS nào để đáp ứng các yêu cầu này?', 'Domain 4: Billing, Pricing and Support', 'Quản lý chi phí & Thanh toán AWS', 'AWS Cost Explorer là dịch vụ hoặc công cụ AWS mà công ty có thể sử dụng để xem xét định kỳ tài khoản AWS của mình để tìm cơ hội tối ưu hóa chi phí. AWS Cost Explorer là một công cụ cho phép công ty trực quan hóa, hiểu rõ và quản lý chi phí cũng như mức sử dụng AWS của họ theo thời gian. Công ty có thể sử dụng AWS Cost Explorer để truy cập vào các biểu đồ và bảng tương tác hiển thị thông tin chi tiết về chi phí và mức sử dụng theo dịch vụ, khu vực, tài khoản, thẻ, v.v. Công ty cũng có thể sử dụng AWS Cost Explorer để dự báo chi phí trong tương lai, xác định xu hướng và điểm bất thường, đồng thời khám phá các khoản tiết kiệm tiềm năng bằng cách sử dụng Phiên bản dự trữ hoặc Gói tiết kiệm.', '[{"label": "A", "text_vi": "Trình AWS Cost Explorer AWS", "is_correct": true, "analysis_vi": "Đúng. Trình AWS Cost Explorer AWS là đáp án chính xác. AWS Cost Explorer là dịch vụ hoặc công cụ AWS mà công ty có thể sử dụng để xem xét định kỳ tài khoản AWS của mình để tìm cơ hội tối ưu hóa chi phí."}, {"label": "B", "text_vi": "AWS Trusted Advisor", "is_correct": false, "analysis_vi": "Sai. AWS Trusted Advisor: AWS Trusted Advisor quét toàn bộ tài khoản AWS và đưa ra khuyến nghị tối ưu theo 5 trụ cột: Chi phí, Hiệu năng, Bảo mật, Khả năng chịu lỗi và Giới hạn dịch vụ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Công cụ tính giá AWS", "is_correct": false, "analysis_vi": "Sai. Công cụ tính giá AWS: AWS Pricing Calculator là công cụ ước tính chi phí trước khi triển khai kiến trúc trên AWS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Ngân sách AWS", "is_correct": false, "analysis_vi": "Sai. Ngân sách AWS: AWS Budgets cho phép thiết lập ngưỡng ngân sách tùy chỉnh và gửi thông báo hoặc kích hoạt hành động tự động khi chi phí dự kiến vượt ngưỡng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["AWS Trusted Advisor", "AWS Cost Explorer", "AWS Budgets"]'::jsonb, NOW())
