INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-50', 'practice_283', 'Một công ty đang chạy một ứng dụng trên AWS. Công ty muốn xác định và ngăn chặn việc vô tình xóa các đối tượng Amazon S3. Dịch vụ hoặc tính năng AWS nào sẽ đáp ứng các yêu cầu này?', 'Domain 2: Security and Compliance', 'Dịch vụ lưu trữ Amazon S3 & Vòng đời dữ liệu', 'Amazon GuardDuty là dịch vụ phát hiện mối đe dọa liên tục giám sát hoạt động độc hại và hành vi trái phép để bảo vệ tài khoản AWS, khối lượng công việc và dữ liệu được lưu trữ trong Amazon S3 của bạn. Với đám mây, việc thu thập và tổng hợp các hoạt động tài khoản và mạng được đơn giản hóa nhưng có thể tốn thời gian để các Security Group liên tục phân tích dữ liệu nhật ký sự kiện để tìm các mối đe dọa tiềm ẩn. Với GuardDuty, bạn có thể tự động hóa việc phát hiện sự bất thường và nhận được những phát hiện hữu ích để giúp bạn bảo vệ tài nguyên AWS của mình4.', '[{"label": "A", "text_vi": "Nhiệm vụ bảo vệ của Amazon", "is_correct": true, "analysis_vi": "Đúng. Nhiệm vụ bảo vệ của Amazon là đáp án chính xác. Amazon GuardDuty là dịch vụ phát hiện mối đe dọa liên tục giám sát hoạt động độc hại và hành vi trái phép để bảo vệ tài khoản AWS, khối lượng công việc và dữ liệu được lưu trữ trong Amazon S3 của bạn."}, {"label": "B", "text_vi": "Mạng ACL", "is_correct": false, "analysis_vi": "Sai. Mạng ACL: Network ACL là tường lửa ở cấp subnet, hoạt động không trạng thái (Stateless) và hỗ trợ cả quy tắc cho phép (Allow) lẫn từ chối (Deny). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "AWS WAF", "is_correct": false, "analysis_vi": "Sai. AWS WAF: AWS WAF là tường lửa ứng dụng web hoạt động ở tầng 7 (HTTP/S), bảo vệ chống lại các lỗ hổng web phổ biến như SQL Injection và XSS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Tường lửa mạng AWS", "is_correct": false, "analysis_vi": "Sai. Tường lửa mạng AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon S3", "AWS WAF", "Amazon GuardDuty"]'::jsonb, NOW())
