INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-51', 'practice_283', 'Những dịch vụ và tính năng nào của AWS được cung cấp miễn phí cho tất cả khách hàng? (Chọn HAI.)', 'Domain 2: Security and Compliance', 'Security and Compliance', 'Các dịch vụ và tính năng AWS được cung cấp miễn phí cho tất cả khách hàng là VPC và AWS Identity and Access Management (IAM). VPC là dịch vụ cho phép bạn khởi chạy các tài nguyên AWS trong mạng ảo được cách ly hợp lý do bạn xác định. Bạn có thể tạo và sử dụng VPC mà không phải trả thêm phí và chỉ trả tiền cho các tài nguyên bạn khởi chạy trong VPC, chẳng hạn như phiên bản EC2 hoặc ổ đĩa EBS. IAM là dịch vụ cho phép bạn quản lý quyền truy cập và quyền đối với tài nguyên AWS. Bạn có thể tạo và sử dụng người dùng, nhóm, vai trò và chính sách IAM mà không phải trả thêm phí và bạn chỉ trả tiền cho các tài nguyên AWS mà các thực thể IAM truy cập. Amazon Aurora, Amazon SageMaker và Amazon Polly không phải là dịch vụ miễn phí và tính phí dựa trên mức sử dụng cũng như tính năng mà bạn chọn5', '[{"label": "A", "text_vi": "Amazon cực quang", "is_correct": false, "analysis_vi": "Sai. Amazon Aurora, Amazon SageMaker và Amazon Polly không phải là dịch vụ miễn phí và tính phí dựa trên mức sử dụng cũng như tính năng mà bạn chọn5."}, {"label": "B", "text_vi": "VPC", "is_correct": true, "analysis_vi": "Đúng. VPC là giải pháp đáp ứng yêu cầu. Các dịch vụ và tính năng AWS được cung cấp miễn phí cho tất cả khách hàng là VPC và AWS Identity and Access Management (IAM). Amazon VPC cho phép khởi tạo mạng ảo riêng biệt được cô lập logic trên đám mây AWS, kiểm soát toàn diện dải IP, subnet, bảng định tuyến và cổng mạng."}, {"label": "C", "text_vi": "Amazon SageMaker", "is_correct": false, "analysis_vi": "Sai. Amazon Aurora, Amazon SageMaker và Amazon Polly không phải là dịch vụ miễn phí và tính phí dựa trên mức sử dụng cũng như tính năng mà bạn chọn5."}, {"label": "D", "text_vi": "Quản lý quyền truy cập và nhận dạng AWS (IAM)", "is_correct": true, "analysis_vi": "Đúng. Quản lý quyền truy cập và nhận dạng AWS (IAM) là đáp án chính xác. Các dịch vụ và tính năng AWS được cung cấp miễn phí cho tất cả khách hàng là VPC và AWS Identity and Access Management (IAM)."}, {"label": "E", "text_vi": "Amazon Polly", "is_correct": false, "analysis_vi": "Sai. Amazon Aurora, Amazon SageMaker và Amazon Polly không phải là dịch vụ miễn phí và tính phí dựa trên mức sử dụng cũng như tính năng mà bạn chọn5."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon Aurora", "AWS IAM", "Amazon VPC"]'::jsonb, NOW())
