INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-52', 'practice_283', 'Dịch vụ hoặc tính năng AWS nào được liên kết với mạng con trong VPC và được dùng để kiểm soát lưu lượng vào và ra?', 'Domain 2: Security and Compliance', 'Hạ tầng mạng & Phân phối nội dung (VPC & Networking)', 'ACL mạng (Network ACL) là lớp bảo mật tùy chọn cho VPC của bạn, hoạt động như tường lửa để kiểm soát lưu lượng truy cập vào và ra một hoặc nhiều mạng con. Bạn có thể sử dụng ACL mạng để cho phép hoặc từ chối lưu lượng truy cập dựa trên giao thức, cổng hoặc địa chỉ IP nguồn và đích. ACL mạng không có trạng thái, nghĩa là chúng không theo dõi lưu lượng truy cập đi qua chúng. Vì vậy, bạn phải tạo quy tắc cho cả lưu lượng truy cập vào và ra.', '[{"label": "A", "text_vi": "Amazon Inspector", "is_correct": false, "analysis_vi": "Sai. Amazon Inspector: Amazon Inspector là dịch vụ quản lý lỗ hổng bảo mật tự động, quét các lỗ hổng phần mềm và phát hiện phơi nhiễm mạng ngoài ý muốn trên EC2, ECR và Lambda. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "ACL mạng", "is_correct": true, "analysis_vi": "Đúng. ACL mạng là đáp án chính xác. ACL mạng (Network ACL) là lớp bảo mật tùy chọn cho VPC của bạn, hoạt động như tường lửa để kiểm soát lưu lượng truy cập vào và ra một hoặc nhiều mạng con."}, {"label": "C", "text_vi": "Khiên AWS", "is_correct": false, "analysis_vi": "Sai. Khiên AWS: AWS Shield là dịch vụ phòng chống tấn công từ chối dịch vụ phân tán (DDoS), bản Standard miễn phí tích hợp sẵn và bản Advanced hỗ trợ phản ứng 24/7 từ đội SRT. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Nhật ký luồng VPC", "is_correct": false, "analysis_vi": "Sai. Nhật ký luồng VPC: Amazon VPC cho phép khởi tạo mạng ảo riêng biệt được cô lập logic trên đám mây AWS, kiểm soát toàn diện dải IP, subnet, bảng định tuyến và cổng mạng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Shield", "Amazon Inspector", "Amazon VPC"]'::jsonb, NOW())
