INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-53', 'practice_283', 'Những lựa chọn nào được đề xuất cho hành trình chuyển đổi đám mây của AWS Cloud Adoption Framework (AWS CAF)? (Chọn HAI.)', 'Domain 1: Cloud Concepts', 'Cloud Concepts', 'Khung áp dụng đám mây AWS (AWS CAF) là một công cụ giúp các tổ chức lập kế hoạch và thực hiện hành trình chuyển đổi đám mây của mình. AWS CAF xác định bốn giai đoạn của hành trình chuyển đổi đám mây: Hình dung, Căn chỉnh, Khởi chạy và Quy mô. Mỗi giai đoạn có một mục đích và kết quả cụ thể1: Hình dung: Giai đoạn này giúp bạn xác định tầm nhìn, mục tiêu và kết quả mong đợi cho quá trình chuyển đổi đám mây của mình. Nó cũng giúp bạn xác định và ưu tiên các cơ hội chuyển đổi trên bốn lĩnh vực: kinh doanh, con người, quản trị và nền tảng2. Căn chỉnh: Giai đoạn này giúp bạn xác định các khoảng cách về năng lực trên sáu khía cạnh: kinh doanh, con người, quản trị, nền tảng, bảo mật và vận hành. Nó cũng giúp bạn tạo ra các chiến lược để cải thiện tính sẵn sàng của đám mây, đảm bảo sự liên kết của các bên liên quan và tạo điều kiện thuận lợi cho các hoạt động quản lý thay đổi có liên quan của tổ chức3. Khởi động: Giai đoạn này giúp bạn đưa ra các sáng kiến ​​thí điểm trong sản xuất và chứng minh giá trị kinh doanh gia tăng. Nó cũng giúp bạn học hỏi từ các phi công và điều chỉnh cách tiếp cận của mình trước khi mở rộng quy mô sang sản xuất hoàn chỉnh4. Quy mô: Giai đoạn này giúp bạn mở rộng các hoạt động thử nghiệm sản xuất và giá trị doanh nghiệp lên quy mô mong muốn, đồng thời đảm bảo rằng các lợi ích kinh doanh liên quan đến khoản đầu tư vào đám mây của bạn sẽ được hiện thực hóa và duy trì. Các tùy chọn A và B là những đề xuất chính xác về hành trình chuyển đổi đám mây AWS CAF vì chúng là một phần trong bốn giai đoạn được AWS CAF xác định. Các tùy chọn C, D và E không phải là đề xuất về hành trình chuyển đổi trên đám mây AWS CAF vì chúng không nằm trong bốn giai đoạn do AWS CAF xác định', '[{"label": "A", "text_vi": "Giai đoạn hình dung", "is_correct": true, "analysis_vi": "Đúng. Giai đoạn hình dung là đáp án chính xác. AWS CAF xác định bốn giai đoạn của hành trình chuyển đổi đám mây: Hình dung, Căn chỉnh, Khởi chạy và Quy mô."}, {"label": "B", "text_vi": "Giai đoạn AIign", "is_correct": true, "analysis_vi": "Đúng. Giai đoạn AIign là đáp án chính xác. AWS CAF xác định bốn giai đoạn của hành trình chuyển đổi đám mây: Hình dung, Căn chỉnh, Khởi chạy và Quy mô."}, {"label": "C", "text_vi": "Giai đoạn đánh giá", "is_correct": false, "analysis_vi": "Sai. Giai đoạn đánh giá không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Giai đoạn huy động", "is_correct": false, "analysis_vi": "Sai. Giai đoạn huy động không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "E", "text_vi": "Giai đoạn di cư và hiện đại hóa", "is_correct": false, "analysis_vi": "Sai. Giai đoạn di cư và hiện đại hóa không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
