INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-54', 'practice_283', 'Việc sử dụng Amazon Elastic Container Service (Amazon ECS) để chia nhỏ kiến trúc nguyên khối thành các vi dịch vụ là một ví dụ về:', 'Domain 1: Cloud Concepts', 'Cloud Concepts', 'Việc sử dụng Amazon Elastic Container Service (Amazon ECS) để chia nhỏ kiến trúc nguyên khối thành các vi dịch vụ là một ví dụ về kiến trúc liên kết lỏng lẻo. Kiến trúc liên kết lỏng lẻo là kiến ​​trúc trong đó các thành phần độc lập và có thể giao tiếp với nhau thông qua các giao diện được xác định rõ ràng. Điều này cho phép khả năng mở rộng, tính linh hoạt và khả năng phục hồi cao hơn. Kiến trúc liên kết chặt chẽ là kiến ​​trúc trong đó các thành phần phụ thuộc lẫn nhau và dựa vào nhau để thực hiện chức năng. Điều này có thể làm tăng độ phức tạp, dễ vỡ và khó khăn trong việc thay đổi hoặc mở rộng quy mô hệ thống. Tổng quan về Amazon ECS Khung kiến trúc tối ưu của AWS', '[{"label": "A", "text_vi": "một kiến trúc liên kết lỏng lẻo.", "is_correct": true, "analysis_vi": "Đúng. một kiến trúc liên kết lỏng lẻo. là đáp án chính xác. Việc sử dụng Amazon Elastic Container Service (Amazon ECS) để chia nhỏ kiến trúc nguyên khối thành các vi dịch vụ là một ví dụ về kiến trúc liên kết lỏng lẻo."}, {"label": "B", "text_vi": "một kiến ​​trúc liên kết chặt chẽ.", "is_correct": false, "analysis_vi": "Sai. một kiến ​​trúc liên kết chặt chẽ. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "một kiến ​​trúc không quốc tịch.", "is_correct": false, "analysis_vi": "Sai. một kiến ​​trúc không quốc tịch. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "một kiến ​​trúc trạng thái.", "is_correct": false, "analysis_vi": "Sai. một kiến ​​trúc trạng thái. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
