INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-55', 'practice_283', 'Một công ty đang xây dựng một ứng dụng trên Đám mây AWS. Công ty muốn sử dụng thông tin xác thực tạm thời cho ứng dụng để truy cập các tài nguyên AWS khác. Dịch vụ AWS nào sẽ đáp ứng những yêu cầu này?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'Dịch vụ mã thông báo bảo mật AWS (AWS STS) là dịch vụ cung cấp thông tin xác thực bảo mật tạm thời cho người dùng hoặc ứng dụng cần truy cập tài nguyên AWS. Thông tin xác thực tạm thời có thời hạn sử dụng giới hạn và có thể được định cấu hình để tồn tại từ vài phút đến vài giờ. Thông tin xác thực không được lưu trữ cùng với người dùng hoặc ứng dụng mà được tạo động và cung cấp theo yêu cầu. Thông tin xác thực hoạt động gần như giống hệt với thông tin xác thực khóa truy cập dài hạn nhưng có ưu điểm là không yêu cầu phân phối, xoay vòng hoặc thu hồi1. Dịch vụ quản lý khóa AWS (AWS KMS) là dịch vụ cung cấp dịch vụ mã hóa và giải mã dữ liệu và khóa. Nó không cung cấp thông tin xác thực bảo mật tạm thời2. AWS CloudHSM là dịch vụ cung cấp các mô-đun bảo mật phần cứng (HSM) cho các hoạt động mã hóa và quản lý khóa. Nó không cung cấp thông tin xác thực bảo mật tạm thời3. Amazon Cognito là dịch vụ cung cấp xác thực và ủy quyền người dùng cho các ứng dụng web và di động. Nó cũng có thể cung cấp thông tin xác thực bảo mật tạm thời cho người dùng đã được xác thực, nhưng không cung cấp cho các ứng dụng4.', '[{"label": "A", "text_vi": "Dịch vụ quản lý khóa AWS (Aws KMS)", "is_correct": false, "analysis_vi": "Sai. Thông tin xác thực hoạt động gần như giống hệt với thông tin xác thực khóa truy cập dài hạn nhưng có ưu điểm là không yêu cầu phân phối, xoay vòng hoặc thu hồi1."}, {"label": "B", "text_vi": "Đám mây AWSM", "is_correct": false, "analysis_vi": "Sai. Đám mây AWSM: AWS CloudHSM cung cấp thiết bị bảo mật phần cứng chuyên dụng (FIPS 140-2 Level 3) do khách hàng độc quyền kiểm soát để quản lý khóa mã hóa. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Nhận thức của Amazon", "is_correct": false, "analysis_vi": "Sai. Nhận thức của Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Dịch vụ mã thông báo bảo mật AWS (Aws STS)", "is_correct": true, "analysis_vi": "Đúng. Dịch vụ mã thông báo bảo mật AWS (Aws STS) là đáp án chính xác. Dịch vụ mã thông báo bảo mật AWS (AWS STS) là dịch vụ cung cấp thông tin xác thực bảo mật tạm thời cho người dùng hoặc ứng dụng cần truy cập tài nguyên AWS."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS KMS"]'::jsonb, NOW())
