INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-56', 'practice_283', 'AWS có trách nhiệm gì khi sử dụng dịch vụ AWS?', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'AWS chịu trách nhiệm duy trì các biện pháp kiểm soát vật lý và môi trường của Đám mây AWS, chẳng hạn như nguồn điện, làm mát, chữa cháy và bảo mật vật lý1. Khách hàng chịu trách nhiệm quản lý quyền của người dùng IAM, tạo quy tắc Security Group để truy cập ra bên ngoài, áp dụng các bản vá hệ điều hành Amazon EC2 và các khía cạnh bảo mật khác trên đám mây1.', '[{"label": "A", "text_vi": "Quản lý quyền của người dùng IAM", "is_correct": false, "analysis_vi": "Sai. Quản lý quyền của người dùng IAM: AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Tạo quy tắc Security Group để truy cập ra bên ngoài", "is_correct": false, "analysis_vi": "Sai. Tạo quy tắc Security Group để truy cập ra bên ngoài: Security Group là tường lửa ảo ở cấp instance, hoạt động có trạng thái (Stateful) và chỉ cấu hình các quy tắc cho phép (Allow rules). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Duy trì các biện pháp kiểm soát vật lý và môi trường", "is_correct": true, "analysis_vi": "Đúng. Duy trì các biện pháp kiểm soát vật lý và môi trường là đáp án chính xác. AWS chịu trách nhiệm duy trì các biện pháp kiểm soát vật lý và môi trường của Đám mây AWS, chẳng hạn như nguồn điện, làm mát, chữa cháy và bảo mật vật lý1."}, {"label": "D", "text_vi": "Ứng dụng các bản vá lỗi hệ điều hành Amazon EC2", "is_correct": false, "analysis_vi": "Sai. Ứng dụng các bản vá lỗi hệ điều hành Amazon EC2: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["Amazon EC2", "AWS IAM"]'::jsonb, NOW())
