INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-57', 'practice_283', 'Một công ty muốn truy cập báo cáo về tác động môi trường ước tính của việc sử dụng AWS của công ty. Công ty nên sử dụng dịch vụ hoặc tính năng nào của AWS để đáp ứng yêu cầu này?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'Công ty nên sử dụng bảng điều khiển Thanh toán AWS để truy cập báo cáo về tác động môi trường ước tính của việc sử dụng AWS của công ty. Bảng điều khiển Thanh toán AWS cung cấp cho khách hàng nhiều công cụ và báo cáo khác nhau để quản lý cũng như giám sát chi phí và mức sử dụng AWS của họ. Một trong những báo cáo có sẵn trong bảng điều khiển Thanh toán AWS là Bảng thông tin bền vững AWS, hiển thị lượng khí thải carbon ước tính và hỗn hợp năng lượng trong mức sử dụng AWS của khách hàng. Công ty có thể sử dụng bảng thông tin này để đo lường và cải thiện tính bền vững của khối lượng công việc trên đám mây của họ. AWS Organizations, chính sách IAM và Dịch vụ thông báo đơn giản của Amazon (Amazon SNS) không phải là các dịch vụ hoặc tính năng có thể cung cấp báo cáo về tác động môi trường ước tính của việc sử dụng AWS của công ty. AWS Organs là dịch vụ cho phép khách hàng quản lý và quản lý tập trung tài khoản AWS của họ. Chính sách IAM là tài liệu xác định các quyền đối với danh tính IAM (người dùng, nhóm hoặc vai trò) hoặc tài nguyên AWS. Amazon SNS là dịch vụ nhắn tin pub/sub được quản lý toàn phần, cho phép khách hàng gửi tin nhắn đến người đăng ký hoặc các dịch vụ AWS khác.', '[{"label": "A", "text_vi": "AWS Organizations", "is_correct": false, "analysis_vi": "Sai. AWS Organizations, chính sách IAM và Dịch vụ thông báo đơn giản của Amazon (Amazon SNS) không phải là các dịch vụ hoặc tính năng có thể cung cấp báo cáo về tác động môi trường ước tính của việc sử dụng AWS của công ty."}, {"label": "B", "text_vi": "Chính sách IAM", "is_correct": false, "analysis_vi": "Sai. AWS Organizations, chính sách IAM và Dịch vụ thông báo đơn giản của Amazon (Amazon SNS) không phải là các dịch vụ hoặc tính năng có thể cung cấp báo cáo về tác động môi trường ước tính của việc sử dụng AWS của công ty."}, {"label": "C", "text_vi": "Bảng điều khiển thanh toán AWS", "is_correct": true, "analysis_vi": "Đúng. Bảng điều khiển thanh toán AWS là đáp án chính xác. Công ty nên sử dụng bảng điều khiển Thanh toán AWS để truy cập báo cáo về tác động môi trường ước tính của việc sử dụng AWS của công ty."}, {"label": "D", "text_vi": "Dịch vụ thông báo đơn giản của Amazon (Amazon SNS)", "is_correct": false, "analysis_vi": "Sai. Dịch vụ thông báo đơn giản của Amazon (Amazon SNS) không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Organizations", "AWS IAM", "Amazon SNS"]'::jsonb, NOW())
