INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-58', 'practice_283', 'Những nhiệm vụ nào thuộc trách nhiệm của khách hàng theo mô hình trách nhiệm chung của AWS? (Chọn HAI.)', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Theo mô hình trách nhiệm chung của AWS, khách hàng chịu trách nhiệm về bảo mật trên đám mây, bao gồm các nhiệm vụ định cấu hình tường lửa Security Group do AWS cung cấp và phân loại tài sản của công ty trong Đám mây AWS. Security Group là tường lửa ảo kiểm soát lưu lượng vào và ra cho một hoặc nhiều phiên bản EC2. Khách hàng phải định cấu hình các quy tắc Security Group để cho phép hoặc từ chối lưu lượng truy cập dựa trên giao thức, cổng hoặc địa chỉ IP nguồn và đích2 Việc phân loại tài sản của công ty trong Đám mây AWS có nghĩa là xác định loại, danh mục và mức độ nhạy cảm của dữ liệu và tài nguyên mà khách hàng lưu trữ và xử lý trên AWS. Khách hàng cũng phải xác định các yêu cầu và quy định tuân thủ hiện hành áp dụng cho tài sản của họ, đồng thời thực hiện các biện pháp và biện pháp kiểm soát bảo mật thích hợp để bảo vệ chúng.', '[{"label": "A", "text_vi": "Định cấu hình tường lửa Security Group do AWS cung cấp.", "is_correct": true, "analysis_vi": "Đúng. Định cấu hình tường lửa Security Group do AWS cung cấp. là đáp án chính xác. Theo mô hình trách nhiệm chung của AWS, khách hàng chịu trách nhiệm về bảo mật trên đám mây, bao gồm các nhiệm vụ định cấu hình tường lửa Security Group do AWS cung cấp và phân loại tài sản của công ty trong Đám mây AWS."}, {"label": "B", "text_vi": "Phân loại tài sản của công ty trên Đám mây AWS.", "is_correct": true, "analysis_vi": "Đúng. Phân loại tài sản của công ty trên Đám mây AWS. là đáp án chính xác. Theo mô hình trách nhiệm chung của AWS, khách hàng chịu trách nhiệm về bảo mật trên đám mây, bao gồm các nhiệm vụ định cấu hình tường lửa Security Group do AWS cung cấp và phân loại tài sản của công ty trong Đám mây AWS."}, {"label": "C", "text_vi": "Xác định Availability Zone (AZ) nào sẽ sử dụng cho bộ chứa Amazon S3.", "is_correct": false, "analysis_vi": "Sai. Xác định Availability Zone (AZ) nào sẽ sử dụng cho bộ chứa Amazon S3.: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Vá hoặc nâng cấp Amazon DynamoDB.", "is_correct": false, "analysis_vi": "Sai. Vá hoặc nâng cấp Amazon DynamoDB.: Amazon DynamoDB là cơ sở dữ liệu NoSQL (Key-Value và Document) serverless, cung cấp hiệu năng dưới 10 mili-giây ổn định ở mọi quy mô. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "E", "text_vi": "Chọn phiên bản Amazon EC2 để chạy AWS Lambda.", "is_correct": false, "analysis_vi": "Sai. Chọn phiên bản Amazon EC2 để chạy AWS Lambda.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "F", "text_vi": "Cấu hình AWS", "is_correct": false, "analysis_vi": "Sai. Cấu hình AWS: AWS Config liên tục ghi lại và đánh giá các thay đổi cấu hình tài nguyên so với các quy tắc tuân thủ mong muốn. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["Amazon EC2", "Amazon S3", "AWS Lambda", "Amazon DynamoDB"]'::jsonb, NOW())
