INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-59', 'practice_283', 'Một công ty có một trang web mua sắm trực tuyến và muốn lưu trữ dữ liệu thẻ tín dụng của khách hàng. Công ty phải đáp ứng các tiêu chuẩn của ngành Thẻ thanh toán (PCI). Công ty có thể sử dụng dịch vụ nào để truy cập tài liệu tuân thủ AWS?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'Câu trả lời đúng là B vì AWS Artifact là dịch vụ cung cấp quyền truy cập vào tài liệu tuân thủ AWS, chẳng hạn như báo cáo kiểm tra, chứng nhận bảo mật và thỏa thuận. AWS Artifact cho phép khách hàng tải xuống, xem xét và chấp nhận các tài liệu liên quan đến việc họ sử dụng dịch vụ AWS. Các tùy chọn khác không chính xác vì chúng không phải là dịch vụ cung cấp quyền truy cập vào tài liệu tuân thủ AWS. Amazon Cloud Directory là dịch vụ cho phép khách hàng tạo các thư mục gốc đám mây linh hoạt để tổ chức phân cấp dữ liệu. AWS Trusted Advisor là dịch vụ cung cấp hướng dẫn theo thời gian thực để giúp khách hàng thực hiện theo các biện pháp thực hành tốt nhất của AWS về bảo mật, hiệu suất, tối ưu hóa chi phí và khả năng chịu lỗi. Amazon Inspector là dịch vụ giúp khách hàng tìm ra các lỗ hổng bảo mật và sai lệch so với các biện pháp thực hành tốt nhất trong các phiên bản Amazon EC2 của họ.', '[{"label": "A", "text_vi": "Thư mục đám mây Amazon", "is_correct": false, "analysis_vi": "Sai. Thư mục đám mây Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Tạo phẩm AWS", "is_correct": true, "analysis_vi": "Đúng. Tạo phẩm AWS là đáp án chính xác. Câu trả lời đúng là B vì AWS Artifact là dịch vụ cung cấp quyền truy cập vào tài liệu tuân thủ AWS, chẳng hạn như báo cáo kiểm tra, chứng nhận bảo mật và thỏa thuận."}, {"label": "C", "text_vi": "AWS Trusted Advisor", "is_correct": false, "analysis_vi": "Sai. AWS Trusted Advisor: AWS Trusted Advisor quét toàn bộ tài khoản AWS và đưa ra khuyến nghị tối ưu theo 5 trụ cột: Chi phí, Hiệu năng, Bảo mật, Khả năng chịu lỗi và Giới hạn dịch vụ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Amazon Inspector", "is_correct": false, "analysis_vi": "Sai. Amazon Inspector là dịch vụ giúp khách hàng tìm ra các lỗ hổng bảo mật và sai lệch so với các biện pháp thực hành tốt nhất trong các phiên bản Amazon EC2 của họ.."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon RDS", "AWS Trusted Advisor", "Amazon Inspector", "AWS Artifact"]'::jsonb, NOW())
