INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-60', 'practice_283', 'Một công ty muốn các phiên bản Amazon EC2 của mình dùng chung khu vực địa lý nhưng sử dụng các nguồn điện cơ bản dự phòng. Giải pháp nào sẽ đáp ứng được những yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'Sử dụng phiên bản EC2 trên nhiều Availability Zone (AZ) trong cùng AWS Region là giải pháp đáp ứng yêu cầu chia sẻ cùng một khu vực địa lý nhưng sử dụng các nguồn điện cơ bản dự phòng. Availability Zone (AZ) là các vị trí biệt lập trong AWS Region có nguồn điện, khả năng làm mát và bảo mật vật lý độc lập. Chúng được kết nối thông qua mạng có độ trễ thấp, thông lượng cao và có tính dự phòng cao. Bằng cách khởi chạy các phiên bản EC2 trong các Availability Zone (AZ) khác nhau, người dùng có thể tăng khả năng chịu lỗi và tính khả dụng của ứng dụng của họ. Amazon CloudFront là dịch vụ mạng phân phối nội dung (CDN) giúp tăng tốc độ phân phối nội dung web và phương tiện tới người dùng cuối bằng cách lưu vào bộ nhớ đệm ở các vị trí biên gần họ hơn. Đây không phải là dịch vụ cơ sở dữ liệu và không thể dùng để lưu trữ dữ liệu vận hành cho các phiên bản EC2. Vị trí biên là các trang web thuộc mạng Amazon CloudFront và nằm ở nhiều thành phố trên thế giới. Chúng không giống như Availability Zone (AZ) và không cung cấp dự phòng cho các phiên bản EC2. AWS OpsWorks là dịch vụ quản lý cấu hình cho phép người dùng tự động hóa việc triển khai và quản lý ứng dụng bằng Chef hoặc Puppet. Nó có thể được sử dụng để tạo các ngăn xếp trải rộng trên nhiều AWS Region, nhưng điều này sẽ không đáp ứng yêu cầu chia sẻ cùng một khu vực địa lý.', '[{"label": "A", "text_vi": "Sử dụng các phiên bản EC2 trên nhiều Availability Zone (AZ) trong cùng một AWS Region.", "is_correct": true, "analysis_vi": "Đúng. Sử dụng các phiên bản EC2 trên nhiều Availability Zone (AZ) trong cùng một AWS Region. là đáp án chính xác. Sử dụng phiên bản EC2 trên nhiều Availability Zone (AZ) trong cùng AWS Region là giải pháp đáp ứng yêu cầu chia sẻ cùng một khu vực địa lý nhưng sử dụng các nguồn điện cơ bản dự phòng."}, {"label": "B", "text_vi": "Sử dụng Amazon CloudFront làm cơ sở dữ liệu cho các phiên bản EC2.", "is_correct": false, "analysis_vi": "Sai. Sử dụng Amazon CloudFront làm cơ sở dữ liệu cho các phiên bản EC2.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Sử dụng các phiên bản EC2 ở cùng vị trí biên và cùng Availability Zone (AZ).", "is_correct": false, "analysis_vi": "Sai. Sử dụng các phiên bản EC2 ở cùng vị trí biên và cùng Availability Zone (AZ).: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Sử dụng phiên bản EC2 trong ngăn xếp AWS OpsWorks ở các AWS Region khác nhau.", "is_correct": false, "analysis_vi": "Sai. Sử dụng phiên bản EC2 trong ngăn xếp AWS OpsWorks ở các AWS Region khác nhau.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "Amazon CloudFront"]'::jsonb, NOW())
