INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-61', 'practice_283', 'Một công ty muốn lưu trữ cơ sở dữ liệu quan hệ của mình trên AWS. Cơ sở dữ liệu có các lược đồ được xác định trước mà công ty cần sao chép trên AWS. Công ty có thể sử dụng những dịch vụ AWS nào cho cơ sở dữ liệu? (Chọn HAI.)', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'Câu trả lời đúng là A và B vì Amazon Aurora và Amazon RDS là các dịch vụ AWS mà công ty có thể sử dụng cho cơ sở dữ liệu quan hệ. Amazon Aurora là cơ sở dữ liệu quan hệ tương thích với MySQL và PostgreSQL. Amazon Aurora là một dịch vụ hiệu suất cao, có thể mở rộng và được quản lý toàn phần, cung cấp thông lượng gấp năm lần thông lượng của MySQL tiêu chuẩn và gấp ba lần thông lượng của PostgreSQL tiêu chuẩn. Amazon RDS là dịch vụ cho phép người dùng thiết lập, vận hành và mở rộng quy mô cơ sở dữ liệu quan hệ trên đám mây. Amazon RDS hỗ trợ sáu công cụ cơ sở dữ liệu phổ biến: MySQL, PostgreSQL, Oracle, SQL Server, MariaDB và Amazon Aurora. Các tùy chọn khác không chính xác vì chúng không phải là dịch vụ AWS mà công ty có thể sử dụng cho cơ sở dữ liệu quan hệ. Amazon DocumentDB (có khả năng tương thích với MongoDB) là cơ sở dữ liệu tài liệu tương thích với MongoDB. Amazon Neptune là cơ sở dữ liệu đồ thị hỗ trợ đồ thị thuộc tính và mô hình RDF. Amazon DynamoDB là cơ sở dữ liệu tài liệu và khóa-giá trị.', '[{"label": "A", "text_vi": "Amazon cực quang", "is_correct": true, "analysis_vi": "Đúng. Amazon cực quang là đáp án chính xác. Câu trả lời đúng là A và B vì Amazon Aurora và Amazon RDS là các dịch vụ AWS mà công ty có thể sử dụng cho cơ sở dữ liệu quan hệ."}, {"label": "B", "text_vi": "Amazon RDS", "is_correct": true, "analysis_vi": "Đúng. Amazon RDS là giải pháp đáp ứng yêu cầu. Câu trả lời đúng là A và B vì Amazon Aurora và Amazon RDS là các dịch vụ AWS mà công ty có thể sử dụng cho cơ sở dữ liệu quan hệ. Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao."}, {"label": "C", "text_vi": "Amazon DocumentDB (có khả năng tương thích MongoDB)", "is_correct": false, "analysis_vi": "Sai. Amazon DocumentDB (có khả năng tương thích MongoDB) không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Sao Hải Vương Amazon", "is_correct": false, "analysis_vi": "Sai. Sao Hải Vương Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "E", "text_vi": "Amazon DynamoDB", "is_correct": false, "analysis_vi": "Sai. Amazon DynamoDB: Amazon DynamoDB là cơ sở dữ liệu NoSQL (Key-Value và Document) serverless, cung cấp hiệu năng dưới 10 mili-giây ổn định ở mọi quy mô. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon RDS", "Amazon Aurora", "Amazon DynamoDB"]'::jsonb, NOW())
