INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-62', 'practice_283', 'Đặc điểm của Phiên bản dự trữ có thể chuyển đổi (RI) là gì?', 'Domain 4: Billing, Pricing and Support', 'Billing, Pricing and Support', 'Phiên bản dự trữ có thể chuyển đổi (RI) là một loại Phiên bản dự trữ cho phép bạn thay đổi các thuộc tính của RI miễn là việc trao đổi tạo ra Phiên bản dự trữ có giá trị bằng hoặc lớn hơn. Bạn có thể trao đổi RI Có thể chuyển đổi lấy RI Có thể chuyển đổi khác từ dòng phiên bản, quy mô, nền tảng, hình thức thuê hoặc phạm vi khác (Khu vực hoặc Availability Zone (AZ))3.', '[{"label": "A", "text_vi": "Người dùng có thể trao đổi RI Có thể chuyển đổi lấy RI Có thể chuyển đổi khác từ dòng phiên bản khác.", "is_correct": true, "analysis_vi": "Đúng. Người dùng có thể trao đổi RI Có thể chuyển đổi lấy RI Có thể chuyển đổi khác từ dòng phiên bản khác. là đáp án chính xác. Phiên bản dự trữ có thể chuyển đổi (RI) là một loại Phiên bản dự trữ cho phép bạn thay đổi các thuộc tính của RI miễn là việc trao đổi tạo ra Phiên bản dự trữ có giá trị bằng hoặc lớn hơn."}, {"label": "B", "text_vi": "Người dùng có thể trao đổi RI Có thể chuyển đổi lấy RI Có thể chuyển đổi khác ở các AWS Region khác nhau.", "is_correct": false, "analysis_vi": "Sai. Người dùng có thể trao đổi RI Có thể chuyển đổi lấy RI Có thể chuyển đổi khác ở các AWS Region khác nhau. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Người dùng có thể bán và mua RI có thể chuyển đổi trên AWS Marketplace.", "is_correct": false, "analysis_vi": "Sai. Người dùng có thể bán và mua RI có thể chuyển đổi trên AWS Marketplace. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Người dùng có thể rút ngắn thời hạn của RI Có thể chuyển đổi bằng cách hợp nhất chúng với các RI Có thể chuyển đổi khác.", "is_correct": false, "analysis_vi": "Sai. Người dùng có thể rút ngắn thời hạn của RI Có thể chuyển đổi bằng cách hợp nhất chúng với các RI Có thể chuyển đổi khác. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
