INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-63', 'practice_283', 'Một công ty thương mại điện tử đã di chuyển cơ sở hạ tầng CNTT của mình từ trung tâm dữ liệu tại chỗ sang Đám mây AWS. Công ty chịu trách nhiệm trực tiếp về chi phí nào?', 'Domain 3: Cloud Technology and Services', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Chi phí cấp phép phần mềm ứng dụng là trách nhiệm trực tiếp của công ty khi di chuyển cơ sở hạ tầng CNTT của mình từ trung tâm dữ liệu tại chỗ sang Đám mây AWS. Giấy phép phần mềm ứng dụng là thỏa thuận cấp cho người dùng quyền sử dụng các sản phẩm phần mềm cụ thể, chẳng hạn như hệ điều hành, cơ sở dữ liệu hoặc ứng dụng. Tùy thuộc vào loại và điều khoản của giấy phép, người dùng có thể phải trả phí cho nhà cung cấp hoặc nhà cung cấp phần mềm để sử dụng phần mềm một cách hợp pháp cũng như truy cập các tính năng và bản cập nhật của phần mềm. Khi người dùng di chuyển cơ sở hạ tầng CNTT của mình sang Đám mây AWS, họ có thể chọn mua giấy phép mới từ AWS, mang theo giấy phép của riêng mình (BYOL) hoặc sử dụng kết hợp cả hai. Tuy nhiên, bất kể họ chọn phương án nào, họ vẫn có trách nhiệm tuân thủ các điều khoản cấp phép và thanh toán phí cấp phép cho nhà cung cấp hoặc nhà cung cấp phần mềm. AWS không tính phí người dùng đối với giấy phép phần mềm ứng dụng mà họ mang theo hoặc mua mà chỉ tính phí đối với tài nguyên AWS mà họ sử dụng để chạy ứng dụng của mình. Vì vậy, chi phí mua bản quyền phần mềm ứng dụng là chi phí duy nhất trong số các lựa chọn mà công ty chịu trách nhiệm trực tiếp. Các chi phí khác được bao gồm trong phí dịch vụ AWS hoặc do AWS chi trả.', '[{"label": "A", "text_vi": "Chi phí bản quyền phần mềm ứng dụng", "is_correct": true, "analysis_vi": "Đúng. Chi phí bản quyền phần mềm ứng dụng là đáp án chính xác. Chi phí cấp phép phần mềm ứng dụng là trách nhiệm trực tiếp của công ty khi di chuyển cơ sở hạ tầng CNTT của mình từ trung tâm dữ liệu tại chỗ sang Đám mây AWS."}, {"label": "B", "text_vi": "Chi phí cơ sở hạ tầng phần cứng trên AWS", "is_correct": false, "analysis_vi": "Sai. Chi phí cơ sở hạ tầng phần cứng trên AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Chi phí điện năng cho máy chủ AWS", "is_correct": false, "analysis_vi": "Sai. Chi phí điện năng cho máy chủ AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Chi phí bảo mật vật lý cho trung tâm dữ liệu AWS", "is_correct": false, "analysis_vi": "Sai. Chi phí bảo mật vật lý cho trung tâm dữ liệu AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '[]'::jsonb, NOW())
