INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-64', 'practice_283', 'Dịch vụ AWS nào có thể hạn chế lỗi thủ công bằng cách cung cấp tài nguyên AWS một cách nhất quán trong nhiều môi trường', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'AWS CloudFormation và AWS Cloud Development Kit (AWS CDK) là các dịch vụ AWS có thể hạn chế lỗi thủ công bằng cách cung cấp nhất quán tài nguyên AWS trong nhiều môi trường. AWS CloudFormation là dịch vụ cho phép bạn lập mô hình và cung cấp tài nguyên AWS bằng các mẫu. Bạn có thể sử dụng AWS CloudFormation để xác định các tài nguyên AWS và các phần phụ thuộc của chúng mà bạn cần cho ứng dụng của mình, đồng thời để tự động hóa việc tạo và cập nhật các tài nguyên đó trên nhiều môi trường, chẳng hạn như phát triển, thử nghiệm và sản xuất. AWS CloudFormation giúp bạn đảm bảo rằng tài nguyên AWS của bạn được cấu hình nhất quán và chính xác, đồng thời bạn có thể dễ dàng sao chép hoặc sửa đổi chúng khi cần. Bộ công cụ phát triển đám mây AWS (AWS CDK) là dịch vụ cho phép bạn sử dụng các ngôn ngữ lập trình quen thuộc như Python, TypeScript, Java và C# để xác định và cung cấp tài nguyên AWS. Bạn có thể sử dụng AWS CDK để viết mã tổng hợp thành các mẫu AWS CloudFormation và tận dụng các thư viện và công cụ hiện có của ngôn ngữ ưa thích của bạn. AWS CDK giúp bạn giảm bớt độ phức tạp và lỗi khi viết và duy trì các mẫu AWS CloudFormation, đồng thời giúp bạn áp dụng các biện pháp thực hành và tiêu chuẩn tốt nhất về phát triển phần mềm cho cơ sở hạ tầng AWS của bạn.', '[{"label": "A", "text_vi": "Cấu hình AWS", "is_correct": false, "analysis_vi": "Sai. Cấu hình AWS: AWS Config liên tục ghi lại và đánh giá các thay đổi cấu hình tài nguyên so với các quy tắc tuân thủ mong muốn. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Ngôi sao mã AWS", "is_correct": false, "analysis_vi": "Sai. Ngôi sao mã AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Đám mây AWS", "is_correct": false, "analysis_vi": "Sai. Đám mây AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Bộ công cụ phát triển đám mây AWS (AWS CDK)", "is_correct": true, "analysis_vi": "Đúng. Bộ công cụ phát triển đám mây AWS (AWS CDK) là đáp án chính xác. AWS CloudFormation và AWS Cloud Development Kit (AWS CDK) là các dịch vụ AWS có thể hạn chế lỗi thủ công bằng cách cung cấp nhất quán tài nguyên AWS trong nhiều môi trường."}, {"label": "E", "text_vi": "AWS CodeBuild", "is_correct": false, "analysis_vi": "Sai. AWS CodeBuild không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS CloudFormation"]'::jsonb, NOW())
