INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-65', 'practice_283', 'Dịch vụ AWS nào là dịch vụ quản lý trạng thái bảo mật đám mây (CSPM) tổng hợp các cảnh báo từ nhiều dịch vụ AWS và sản phẩm của đối tác theo định dạng chuẩn?', 'Domain 2: Security and Compliance', 'An ninh & Phòng chống đe dọa (Security & Compliance)', 'AWS Security Hub là dịch vụ quản lý trạng thái bảo mật đám mây (CSPM) thực hiện các biện pháp kiểm tra biện pháp bảo mật tốt nhất, tổng hợp cảnh báo và cho phép khắc phục tự động. Trung tâm bảo mật thu thập các phát hiện từ các dịch vụ bảo mật được kích hoạt trên các tài khoản AWS của bạn, chẳng hạn như phát hiện phát hiện xâm nhập từ Amazon GuardDuty, quét lỗ hổng từ Amazon Inspector và phát hiện nhận dạng dữ liệu nhạy cảm từ Amazon Macie. Security Hub cũng thu thập các phát hiện từ các sản phẩm bảo mật của đối tác bằng cách sử dụng Định dạng tìm kiếm bảo mật AWS được tiêu chuẩn hóa, loại bỏ nhu cầu phân tích dữ liệu và nỗ lực chuẩn hóa tốn thời gian. Khách hàng có thể chỉ định một tài khoản quản trị viên có thể truy cập tất cả các phát hiện trên tài khoản của họ.', '[{"label": "A", "text_vi": "Trung tâm bảo mật AWS", "is_correct": true, "analysis_vi": "Đúng. Trung tâm bảo mật AWS là đáp án chính xác. AWS Security Hub là dịch vụ quản lý trạng thái bảo mật đám mây (CSPM) thực hiện các biện pháp kiểm tra biện pháp bảo mật tốt nhất, tổng hợp cảnh báo và cho phép khắc phục tự động."}, {"label": "B", "text_vi": "AWS Trusted Advisor", "is_correct": false, "analysis_vi": "Sai. AWS Trusted Advisor: AWS Trusted Advisor quét toàn bộ tài khoản AWS và đưa ra khuyến nghị tối ưu theo 5 trụ cột: Chi phí, Hiệu năng, Bảo mật, Khả năng chịu lỗi và Giới hạn dịch vụ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Amazon EventBndge", "is_correct": false, "analysis_vi": "Sai. Amazon EventBndge không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Nhiệm vụ bảo vệ của Amazon", "is_correct": false, "analysis_vi": "Sai. Nhiệm vụ bảo vệ của Amazon: Amazon GuardDuty là dịch vụ phát hiện mối đe dọa thông minh sử dụng máy học để liên tục phân tích VPC Flow Logs, CloudTrail Logs và DNS Logs. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Cặp dịch vụ bảo mật hay gặp: GuardDuty (phát hiện mối đe dọa thông minh), Inspector (quét lỗ hổng phần mềm trên EC2/Lambda), WAF (tường lửa web lớp 7)."]'::jsonb, '[{"term": "phát hiện mối đe dọa", "points_to": "Amazon GuardDuty"}]'::jsonb, '["AWS Trusted Advisor", "Amazon GuardDuty"]'::jsonb, NOW())
