INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-66', 'practice_283', 'Một chuyên viên đám mây đang phân tích hiệu suất và cách sử dụng phiên bản Amazon EC2 để đưa ra đề xuất nhằm tiết kiệm chi phí tiềm năng. Phân tích này chứng minh khái niệm đám mây nào?', 'Domain 4: Billing, Pricing and Support', 'Quản lý chi phí & Thanh toán AWS', 'Phân quyền là khái niệm đám mây mà phân tích này chứng minh. Phân quyền là quá trình tối ưu hóa hiệu suất và chi phí tài nguyên AWS của bạn bằng cách chọn loại, kích thước và cấu hình phù hợp nhất dựa trên yêu cầu khối lượng công việc và kiểu sử dụng của bạn. Việc phân quyền có thể giúp bạn đạt được mức tiết kiệm chi phí tiềm năng bằng cách giảm việc cung cấp quá mức hoặc sử dụng không đúng mức các nguồn lực của bạn. Bạn có thể sử dụng nhiều công cụ và dịch vụ AWS khác nhau, chẳng hạn như AWS Cost Explorer, AWS Computer Optimizer và AWS Trusted Advisor, để phân tích các chỉ số hiệu suất và mức sử dụng tài nguyên của bạn cũng như nhận các đề xuất về cấp quyền.', '[{"label": "A", "text_vi": "Tự động chia tỷ lệ", "is_correct": false, "analysis_vi": "Sai. Tự động chia tỷ lệ không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Quyền hóa", "is_correct": true, "analysis_vi": "Đúng. Quyền hóa là đáp án chính xác. Phân quyền là khái niệm đám mây mà phân tích này chứng minh."}, {"label": "C", "text_vi": "Cân bằng tải", "is_correct": false, "analysis_vi": "Sai. Cân bằng tải không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Tính sẵn sàng cao", "is_correct": false, "analysis_vi": "Sai. Tính sẵn sàng cao: Tính sẵn sàng cao (High Availability) đảm bảo ứng dụng vận hành liên tục không gián đoạn bằng cách triển khai phân tán trên nhiều Availability Zone. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
