INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-67', 'practice_283', 'Một công ty muốn quản lý tài nguyên Đám mây AWS của mình thông qua giao diện web. Dịch vụ AWS nào sẽ đáp ứng yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Bảng điều khiển quản lý AWS là một ứng dụng web cho phép bạn quản lý và giám sát tài nguyên Đám mây AWS thông qua giao diện thân thiện với người dùng. Bạn có thể sử dụng Bảng điều khiển quản lý AWS để truy cập và thử nghiệm hơn 150 dịch vụ AWS, xem và sửa đổi thông tin tài khoản cũng như thanh toán của mình, nhận trợ giúp trong bảng điều khiển từ AWS Support và tùy chỉnh bảng thông tin của bạn bằng các tiện ích hiển thị số liệu và thông tin chính cho ứng dụng của bạn567. Bạn cũng có thể sử dụng Bảng điều khiển quản lý AWS để khởi chạy và đặt cấu hình tài nguyên AWS bằng cách sử dụng trình hướng dẫn và mẫu mà không cần viết bất kỳ mã nào5.', '[{"label": "A", "text_vi": "Bảng điều khiển quản lý AWS", "is_correct": true, "analysis_vi": "Đúng. Bảng điều khiển quản lý AWS là đáp án chính xác. Bảng điều khiển quản lý AWS là một ứng dụng web cho phép bạn quản lý và giám sát tài nguyên Đám mây AWS thông qua giao diện thân thiện với người dùng."}, {"label": "B", "text_vi": "AWS CLI", "is_correct": false, "analysis_vi": "Sai. AWS CLI không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "SDK AWS", "is_correct": false, "analysis_vi": "Sai. SDK AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Đám mây AWS", "is_correct": false, "analysis_vi": "Sai. Đám mây AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
