INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-68', 'practice_283', 'Công ty cần triển khai quản lý danh tính cho nhóm ứng dụng di động đang chạy trên Đám mây AWS. Dịch vụ AWS nào sẽ đáp ứng yêu cầu này?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'Amazon Cognito là dịch vụ cung cấp khả năng quản lý danh tính cho các ứng dụng web và di động, cho phép người dùng đăng ký, đăng nhập và truy cập tài nguyên AWS bằng các nhà cung cấp danh tính khác nhau. Trung tâm bảo mật AWS là dịch vụ cung cấp cái nhìn toàn diện về trạng thái bảo mật của tài khoản và tài nguyên AWS. AWS Shield là dịch vụ cung cấp khả năng bảo vệ chống lại các cuộc tấn công từ chối dịch vụ (DDoS) phân tán. AWS WAF là tường lửa ứng dụng web giúp bảo vệ các ứng dụng web khỏi các hoạt động khai thác web phổ biến.', '[{"label": "A", "text_vi": "Amazon Cognito", "is_correct": true, "analysis_vi": "Đúng. Amazon Cognito là đáp án chính xác. Amazon Cognito là dịch vụ cung cấp khả năng quản lý danh tính cho các ứng dụng web và di động, cho phép người dùng đăng ký, đăng nhập và truy cập tài nguyên AWS bằng các nhà cung cấp danh tính khác nhau."}, {"label": "B", "text_vi": "Trung tâm bảo mật AWS", "is_correct": false, "analysis_vi": "Sai. Trung tâm bảo mật AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Khiên AWS", "is_correct": false, "analysis_vi": "Sai. Khiên AWS: AWS Shield là dịch vụ phòng chống tấn công từ chối dịch vụ phân tán (DDoS), bản Standard miễn phí tích hợp sẵn và bản Advanced hỗ trợ phản ứng 24/7 từ đội SRT. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "AWS WAF", "is_correct": false, "analysis_vi": "Sai. AWS WAF: AWS WAF là tường lửa ứng dụng web hoạt động ở tầng 7 (HTTP/S), bảo vệ chống lại các lỗ hổng web phổ biến như SQL Injection và XSS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Shield", "AWS WAF"]'::jsonb, NOW())
