INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-69', 'practice_283', 'Điều nào sau đây là lợi ích của việc vận hành trên Đám mây AWS?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Một trong những lợi ích của việc vận hành trên Đám mây AWS là khả năng mở rộng điện toán, lưu trữ và bộ nhớ khi cần, cho phép người dùng tăng hoặc giảm quy mô ứng dụng và tài nguyên của họ tùy theo nhu cầu. Điều này cũng giúp người dùng tối ưu hóa chi phí và hiệu suất của họ. Khả năng di chuyển các thiết bị mạng tại chỗ sang Đám mây AWS, khả năng lưu trữ phần cứng tùy chỉnh trong Đám mây AWS và khả năng tùy chỉnh lớp ảo hóa giám sát cơ bản cho Amazon EC2 không phải là lợi ích khi vận hành trên Đám mây AWS, vì chúng không thể thực hiện được hoặc không được AWS khuyến nghị.', '[{"label": "A", "text_vi": "Khả năng di chuyển các thiết bị mạng tại chỗ sang Đám mây AWS", "is_correct": false, "analysis_vi": "Sai. Khả năng di chuyển các thiết bị mạng tại chỗ sang Đám mây AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Khả năng mở rộng tính toán, lưu trữ và bộ nhớ khi cần thiết", "is_correct": true, "analysis_vi": "Đúng. Khả năng mở rộng tính toán, lưu trữ và bộ nhớ khi cần thiết là đáp án chính xác. Một trong những lợi ích của việc vận hành trên Đám mây AWS là khả năng mở rộng điện toán, lưu trữ và bộ nhớ khi cần, cho phép người dùng tăng hoặc giảm quy mô ứng dụng và tài nguyên của họ tùy theo nhu cầu."}, {"label": "C", "text_vi": "Khả năng lưu trữ phần cứng tùy chỉnh trên Đám mây AWS", "is_correct": false, "analysis_vi": "Sai. Khả năng lưu trữ phần cứng tùy chỉnh trên Đám mây AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Khả năng tùy chỉnh lớp ảo hóa cơ bản cho Amazon EC2", "is_correct": false, "analysis_vi": "Sai. Khả năng tùy chỉnh lớp ảo hóa cơ bản cho Amazon EC2: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
