INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-70', 'practice_283', 'Quan điểm nào của Khung áp dụng đám mây AWS (AWS CAF) kết nối công nghệ và kinh doanh?', 'Domain 1: Cloud Concepts', 'Cloud Concepts', 'Quan điểm của Khung áp dụng đám mây AWS (AWS CAF) kết nối công nghệ và kinh doanh là quản trị. Quan điểm quản trị tập trung vào việc liên kết chiến lược và quy trình CNTT với chiến lược và mục tiêu kinh doanh, cũng như quản lý ngân sách, rủi ro và tuân thủ CNTT. Các khả năng của góc độ quản trị là quản lý danh mục đầu tư, quản lý hiệu quả kinh doanh và quản trị CNTT. Quan điểm quản trị giúp các tổ chức đảm bảo rằng việc áp dụng đám mây của họ mang lại giá trị và kết quả kinh doanh như mong đợi, đồng thời các giải pháp đám mây của họ an toàn, đáng tin cậy và tuân thủ. Hoạt động, con người và bảo mật là những khía cạnh khác của AWS CAF nhưng chúng không kết nối trực tiếp công nghệ và hoạt động kinh doanh. Khía cạnh vận hành tập trung vào việc quản lý và giám sát các tài nguyên và ứng dụng đám mây, cũng như tự động hóa và tối ưu hóa các quy trình vận hành. Quan điểm con người tập trung vào việc phát triển và trao quyền cho nguồn nhân lực, cũng như sự chuyển đổi văn hóa và cơ cấu tổ chức. Khía cạnh bảo mật tập trung vào việc bảo vệ tài sản và hệ thống thông tin trên đám mây, cũng như việc thực hiện các chính sách và biện pháp kiểm soát bảo mật.', '[{"label": "A", "text_vi": "Hoạt động", "is_correct": false, "analysis_vi": "Sai. Hoạt động, con người và bảo mật là những khía cạnh khác của AWS CAF nhưng chúng không kết nối trực tiếp công nghệ và hoạt động kinh doanh."}, {"label": "B", "text_vi": "Mọi người", "is_correct": false, "analysis_vi": "Sai. Hoạt động, con người và bảo mật là những khía cạnh khác của AWS CAF nhưng chúng không kết nối trực tiếp công nghệ và hoạt động kinh doanh."}, {"label": "C", "text_vi": "Bảo mật", "is_correct": false, "analysis_vi": "Sai. Bảo mật không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Quản trị", "is_correct": true, "analysis_vi": "Đúng. Quản trị là đáp án chính xác. Quan điểm của Khung áp dụng đám mây AWS (AWS CAF) kết nối công nghệ và kinh doanh là quản trị."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Direct Connect"]'::jsonb, NOW())
