INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-71', 'practice_283', 'Một công ty cần phải thực hiện một số khối lượng công việc của mình tại cơ sở để tuân thủ các nguyên tắc quy định. Công ty muốn sử dụng Đám mây AWS để chạy khối lượng công việc không bắt buộc phải có tại cơ sở. Công ty cũng muốn có thể sử dụng các lệnh gọi API giống nhau cho khối lượng công việc tại chỗ và khối lượng công việc trên đám mây. Công ty nên sử dụng dịch vụ hoặc tính năng nào của AWS để đáp ứng các yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'AWS Outposts là dịch vụ được quản lý toàn phần giúp mở rộng cơ sở hạ tầng AWS, dịch vụ AWS, API và công cụ tới hầu hết mọi trung tâm dữ liệu, không gian dùng chung hoặc cơ sở tại chỗ để có trải nghiệm kết hợp thực sự nhất quán1. AWS Outposts cho phép khách hàng chạy khối lượng công việc tại cơ sở bằng cách sử dụng cùng API, công cụ và dịch vụ AWS mà họ sử dụng trên đám mây2. Máy chủ chuyên dụng là máy chủ vật lý có dung lượng phiên bản EC2 hoàn toàn dành riêng cho mục đích sử dụng của khách hàng3. Availability Zone (AZ) là một hoặc nhiều trung tâm dữ liệu riêng biệt, mỗi trung tâm có nguồn điện, kết nối mạng và kết nối dự phòng, được đặt tại các cơ sở riêng biệt trong AWS Region4. AWS Wavelength là dịch vụ Cơ sở hạ tầng AWS được tối ưu hóa cho các ứng dụng điện toán biên di động.', '[{"label": "A", "text_vi": "Máy chủ chuyên dụng", "is_correct": false, "analysis_vi": "Sai. Máy chủ chuyên dụng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Tiền đồn AWS", "is_correct": true, "analysis_vi": "Đúng. Tiền đồn AWS là đáp án chính xác. AWS Outposts là dịch vụ được quản lý toàn phần giúp mở rộng cơ sở hạ tầng AWS, dịch vụ AWS, API và công cụ tới hầu hết mọi trung tâm dữ liệu, không gian dùng chung hoặc cơ sở tại chỗ để có trải nghiệm kết hợp thực sự nhất quán1."}, {"label": "C", "text_vi": "Availability Zone (AZ)", "is_correct": false, "analysis_vi": "Sai. Availability Zone (AZ) không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Bước sóng AWS", "is_correct": false, "analysis_vi": "Sai. Bước sóng AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
