INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-72', 'practice_283', 'Kỹ sư bảo mật muốn có giải pháp AWS dành cho một bên thuê để tạo, kiểm soát và quản lý khóa mật mã của riêng họ nhằm đáp ứng các yêu cầu tuân thủ quy định về bảo mật dữ liệu. Kỹ sư nên sử dụng dịch vụ AWS nào?', 'Domain 2: Security and Compliance', 'An ninh & Phòng chống đe dọa (Security & Compliance)', 'Câu trả lời đúng là C vì AWS CloudHSM là dịch vụ AWS cho phép kỹ sư bảo mật đáp ứng các yêu cầu. AWS CloudHSM là dịch vụ cung cấp cho khách hàng các mô-đun bảo mật phần cứng (HSM) chuyên dụng để tạo, kiểm soát và quản lý khóa mật mã của riêng họ trong Đám mây AWS. AWS CloudHSM cho phép khách hàng đáp ứng các yêu cầu tuân thủ quy định nghiêm ngặt về bảo mật dữ liệu, chẳng hạn như FIPS 140-2 Cấp 3, PCI-DSS và HIPAA. Các tùy chọn khác không chính xác vì chúng không phải là dịch vụ AWS cho phép kỹ sư bảo mật đáp ứng các yêu cầu. Dịch vụ quản lý khóa AWS (AWS KMS) là dịch vụ cung cấp cho khách hàng hệ thống quản lý khóa tích hợp, có thể mở rộng và được quản lý toàn phần để tạo và kiểm soát khóa mã hóa cho các dịch vụ và ứng dụng AWS. AWS KMS không cung cấp cho khách hàng HSM riêng lẻ hoặc HSM chuyên dụng. AWS Certification Manager (ACM) là dịch vụ cung cấp cho khách hàng một cách đơn giản và an toàn để cung cấp, quản lý và triển khai các chứng chỉ Lớp cổng bảo mật/Bảo mật lớp truyền tải (SSL/TLS) công khai và riêng tư để sử dụng với các dịch vụ AWS và tài nguyên được kết nối nội bộ. ACM không cung cấp cho khách hàng HSM hoặc khóa mật mã. AWS Systems Manager là dịch vụ cung cấp cho khách hàng giao diện người dùng thống nhất để xem dữ liệu vận hành từ nhiều dịch vụ AWS và tự động hóa các tác vụ vận hành trên các tài nguyên AWS của họ. AWS Systems Manager không cung cấp cho khách hàng HSM hoặc khóa mật mã.', '[{"label": "A", "text_vi": "Dịch vụ quản lý khóa AWS (AWS KMS)", "is_correct": false, "analysis_vi": "Sai. Dịch vụ quản lý khóa AWS (AWS KMS): AWS Key Management Service (KMS) giúp tạo, quản lý và kiểm soát các khóa mã hóa dùng để mã hóa dữ liệu trên các dịch vụ AWS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "AWS Certificate Manager (ACM) (ACM)", "is_correct": false, "analysis_vi": "Sai. AWS Certificate Manager (ACM) (ACM) không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "AWS CloudHSM", "is_correct": true, "analysis_vi": "Đúng. AWS CloudHSM là đáp án chính xác. Câu trả lời đúng là C vì AWS CloudHSM là dịch vụ AWS cho phép kỹ sư bảo mật đáp ứng các yêu cầu."}, {"label": "D", "text_vi": "Trình quản lý hệ thống AWS", "is_correct": false, "analysis_vi": "Sai. Trình quản lý hệ thống AWS: AWS Systems Manager cung cấp giao diện quản lý tập trung tài nguyên, tự động hóa tác vụ vận hành, quản lý bản vá (Patch Manager) và chạy lệnh (Run Command). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Cặp dịch vụ bảo mật hay gặp: GuardDuty (phát hiện mối đe dọa thông minh), Inspector (quét lỗ hổng phần mềm trên EC2/Lambda), WAF (tường lửa web lớp 7)."]'::jsonb, '[{"term": "phát hiện mối đe dọa", "points_to": "Amazon GuardDuty"}]'::jsonb, '["AWS KMS", "AWS Secrets Manager"]'::jsonb, NOW())
