INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-73', 'practice_283', 'Một công ty lưu trữ ứng dụng trên phiên bản Amazon EC2. Phiên bản EC2 cần truy cập vào một số tài nguyên AWS, bao gồm Amazon S3 và Amazon DynamoDB. Giải pháp hiệu quả nhất để ủy quyền là gì?', 'Domain 2: Security and Compliance', 'Dịch vụ lưu trữ Amazon S3 & Vòng đời dữ liệu', 'Tạo vai trò IAM với các quyền cần thiết và gắn vai trò đó vào phiên bản EC2 là giải pháp ủy quyền hiệu quả nhất về mặt hoạt động. Vai trò IAM là một thực thể xác định một tập hợp các quyền để thực hiện các yêu cầu dịch vụ AWS. Phiên bản EC2 có thể giả định vai trò IAM để truy cập các tài nguyên AWS khác, chẳng hạn như Amazon S3 và Amazon DynamoDB mà không cần phải lưu trữ bất kỳ thông tin xác thực nào trên phiên bản. Giải pháp này an toàn hơn và có khả năng mở rộng hơn so với việc sử dụng người dùng IAM và khóa truy cập của họ. Để biết thêm thông tin, hãy xem [Vai trò IAM cho Amazon EC2] và [Sử dụng vai trò IAM để cấp quyền cho các ứng dụng chạy trên phiên bản Amazon EC2].', '[{"label": "A", "text_vi": "Tạo vai trò IAM với các quyền cần thiết. Đính kèm vai trò vào phiên bản EC2.", "is_correct": true, "analysis_vi": "Đúng. Tạo vai trò IAM với các quyền cần thiết. Đính kèm vai trò vào phiên bản EC2. là đáp án chính xác. Tạo vai trò IAM với các quyền cần thiết và gắn vai trò đó vào phiên bản EC2 là giải pháp ủy quyền hiệu quả nhất về mặt hoạt động."}, {"label": "B", "text_vi": "Tạo người dùng IAM và sử dụng khóa truy cập cũng như khóa truy cập bí mật của người dùng đó trong ứng dụng.", "is_correct": false, "analysis_vi": "Sai. Phiên bản EC2 có thể giả định vai trò IAM để truy cập các tài nguyên AWS khác, chẳng hạn như Amazon S3 và Amazon DynamoDB mà không cần phải lưu trữ bất kỳ thông tin xác thực nào trên phiên bản."}, {"label": "C", "text_vi": "Tạo người dùng IAM và sử dụng khóa truy cập cũng như khóa truy cập bí mật của người dùng đó để tạo hồ sơ CLI trong phiên bản EC2.", "is_correct": false, "analysis_vi": "Sai. Tạo người dùng IAM và sử dụng khóa truy cập cũng như khóa truy cập bí mật của người dùng đó để tạo hồ sơ CLI trong phiên bản EC2.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Tạo vai trò IAM với các quyền cần thiết. Đính kèm vai trò cho người dùng IAM quản trị.", "is_correct": false, "analysis_vi": "Sai. Tạo vai trò IAM với các quyền cần thiết. Đính kèm vai trò cho người dùng IAM quản trị.: AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon EC2", "Amazon S3", "Amazon DynamoDB", "AWS IAM"]'::jsonb, NOW())
