INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-74', 'practice_283', 'Một công ty đang thiết lập AWS Identity and Access Management (IAM) trên tài khoản AWS. Đề xuất nào tuân thủ các phương pháp hay nhất về bảo mật IAM?', 'Domain 2: Security and Compliance', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'C đúng vì bật xác thực đa yếu tố (MFA) để tăng cường bảo mật trong quá trình đăng nhập là một trong những phương pháp hay nhất về bảo mật IAM được AWS khuyến nghị. MFA bổ sung thêm một lớp bảo vệ bên cạnh tên người dùng và mật khẩu, khiến kẻ tấn công khó truy cập vào tài khoản AWS hơn. A không chính xác vì sử dụng khóa truy cập của người dùng root tài khoản cho các tác vụ quản trị không phải là một phương pháp hay vì người dùng root có toàn quyền truy cập vào tất cả các tài nguyên trong tài khoản AWS và có thể gây ra thiệt hại không thể khắc phục nếu bị xâm phạm. AWS khuyên bạn nên tạo người dùng IAM riêng lẻ theo nguyên tắc đặc quyền tối thiểu và sử dụng vai trò cho các ứng dụng chạy trên phiên bản Amazon EC2. B không chính xác vì việc cấp các quyền rộng rãi để tất cả nhân viên công ty có thể truy cập vào tài nguyên họ cần không phải là một phương pháp hay vì nó làm tăng nguy cơ xảy ra các hành động trái phép hoặc vô tình đối với tài nguyên AWS. AWS khuyến nghị chỉ cấp các quyền cần thiết để thực hiện một tác vụ và sử dụng các nhóm để gán quyền cho người dùng IAM. D không chính xác vì việc tránh luân phiên thông tin xác thực để ngăn chặn sự cố trong các ứng dụng sản xuất không phải là một phương pháp hay vì nó làm tăng nguy cơ rò rỉ hoặc xâm phạm thông tin xác thực. AWS khuyến nghị luân phiên thông tin xác thực thường xuyên và sử dụng thông tin xác thực bảo mật tạm thời từ AWS STS khi có thể.', '[{"label": "A", "text_vi": "Sử dụng khóa truy cập người dùng root của tài khoản cho các tác vụ quản trị.", "is_correct": false, "analysis_vi": "Sai. Sử dụng khóa truy cập người dùng root của tài khoản cho các tác vụ quản trị. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Cấp quyền rộng rãi để tất cả nhân viên công ty có thể truy cập vào tài nguyên họ cần.", "is_correct": false, "analysis_vi": "Sai. Cấp quyền rộng rãi để tất cả nhân viên công ty có thể truy cập vào tài nguyên họ cần. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Bật xác thực đa yếu tố (MFA) để tăng cường bảo mật trong quá trình đăng nhập.", "is_correct": true, "analysis_vi": "Đúng. Bật xác thực đa yếu tố (MFA) để tăng cường bảo mật trong quá trình đăng nhập. là đáp án chính xác. C đúng vì bật xác thực đa yếu tố (MFA) để tăng cường bảo mật trong quá trình đăng nhập là một trong những phương pháp hay nhất về bảo mật IAM được AWS khuyến nghị."}, {"label": "D", "text_vi": "Tránh luân chuyển thông tin đăng nhập để ngăn chặn sự cố trong ứng dụng sản xuất.", "is_correct": false, "analysis_vi": "Sai. Tránh luân chuyển thông tin đăng nhập để ngăn chặn sự cố trong ứng dụng sản xuất. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Cặp dịch vụ bảo mật hay gặp: GuardDuty (phát hiện mối đe dọa thông minh), Inspector (quét lỗ hổng phần mềm trên EC2/Lambda), WAF (tường lửa web lớp 7)."]'::jsonb, '[{"term": "phát hiện mối đe dọa", "points_to": "Amazon GuardDuty"}]'::jsonb, '["AWS IAM"]'::jsonb, NOW())
