INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-75', 'practice_283', 'Một công ty đang sử dụng Amazon DynamoDB. Trách nhiệm của công ty là gì theo mô hình chia sẻ trách nhiệm của AWS?', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Theo mô hình trách nhiệm chung của AWS, AWS chịu trách nhiệm về tính bảo mật của đám mây, trong khi khách hàng chịu trách nhiệm về tính bảo mật trên đám mây. Điều này có nghĩa là AWS chịu trách nhiệm về các máy chủ vật lý, mạng và hệ điều hành chạy DynamoDB, trong khi khách hàng chịu trách nhiệm về tính bảo mật dữ liệu và quyền truy cập vào cơ sở dữ liệu của họ. Khách hàng cần quản lý các quyền truy cập cơ sở dữ liệu, chẳng hạn như tạo và quản lý các chính sách và vai trò AWS Identity and Access Management (IAM), cũng như sử dụng các tùy chọn mã hóa và quản lý khóa để bảo vệ dữ liệu của họ123.', '[{"label": "A", "text_vi": "Vá hệ điều hành", "is_correct": false, "analysis_vi": "Sai. Vá hệ điều hành không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Máy chủ cung cấp", "is_correct": false, "analysis_vi": "Sai. Máy chủ cung cấp không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Quản lý quyền truy cập cơ sở dữ liệu.", "is_correct": true, "analysis_vi": "Đúng. Quản lý quyền truy cập cơ sở dữ liệu. là đáp án chính xác. Điều này có nghĩa là AWS chịu trách nhiệm về các máy chủ vật lý, mạng và hệ điều hành chạy DynamoDB, trong khi khách hàng chịu trách nhiệm về tính bảo mật dữ liệu và quyền truy cập vào cơ sở dữ liệu của họ."}, {"label": "D", "text_vi": "Bảo mật hệ điều hành", "is_correct": false, "analysis_vi": "Sai. Bảo mật hệ điều hành không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["Amazon DynamoDB"]'::jsonb, NOW())
