INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-76', 'practice_283', 'Dịch vụ AWS nào tổng hợp, sắp xếp và ưu tiên các cảnh báo cũng như phát hiện bảo mật từ nhiều dịch vụ AWS?', 'Domain 2: Security and Compliance', 'An ninh & Phòng chống đe dọa (Security & Compliance)', 'Câu trả lời đúng là D vì AWS Security Hub là dịch vụ tổng hợp, sắp xếp và ưu tiên các cảnh báo cũng như phát hiện bảo mật từ nhiều dịch vụ AWS, chẳng hạn như Amazon GuardDuty, Amazon Inspector, Amazon Macie, AWS Tường lửa Manager và AWS IAM Access Phân tích. Các tùy chọn khác không chính xác vì chúng không phải là dịch vụ tổng hợp các cảnh báo và phát hiện bảo mật từ nhiều dịch vụ AWS. Amazon Detective là dịch vụ giúp người dùng phân tích và trực quan hóa dữ liệu bảo mật để điều tra và khắc phục các sự cố tiềm ẩn. Amazon Inspector là dịch vụ giúp người dùng tìm ra các lỗ hổng bảo mật và sai lệch so với các biện pháp thực hành tốt nhất trong các phiên bản Amazon EC2 của họ. Amazon Macie là dịch vụ giúp người dùng khám phá, phân loại và bảo vệ dữ liệu nhạy cảm được lưu trữ trong Amazon S3.', '[{"label": "A", "text_vi": "Thám tử Amazon", "is_correct": false, "analysis_vi": "Sai. Thám tử Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Amazon Inspector", "is_correct": false, "analysis_vi": "Sai. Amazon Inspector: Amazon Inspector là dịch vụ quản lý lỗ hổng bảo mật tự động, quét các lỗ hổng phần mềm và phát hiện phơi nhiễm mạng ngoài ý muốn trên EC2, ECR và Lambda. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Amazon Macie", "is_correct": false, "analysis_vi": "Sai. Amazon Macie: Amazon Macie sử dụng máy học và đối sánh mẫu để tự động phát hiện, phân loại và bảo vệ dữ liệu nhạy cảm (như PII, số thẻ tín dụng) trên Amazon S3. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Trung tâm bảo mật AWS", "is_correct": true, "analysis_vi": "Đúng. Trung tâm bảo mật AWS là đáp án chính xác. Câu trả lời đúng là D vì AWS Security Hub là dịch vụ tổng hợp, sắp xếp và ưu tiên các cảnh báo cũng như phát hiện bảo mật từ nhiều dịch vụ AWS, chẳng hạn như Amazon GuardDuty, Amazon Inspector, Amazon Macie, AWS Tường lửa Manager và AWS IAM Access Phân tích."}]'::jsonb, '["Cặp dịch vụ bảo mật hay gặp: GuardDuty (phát hiện mối đe dọa thông minh), Inspector (quét lỗ hổng phần mềm trên EC2/Lambda), WAF (tường lửa web lớp 7)."]'::jsonb, '[{"term": "phát hiện mối đe dọa", "points_to": "Amazon GuardDuty"}]'::jsonb, '["Amazon Inspector", "Amazon Macie"]'::jsonb, NOW())
