INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-77', 'practice_283', 'Một công ty đang di chuyển sang Đám mây AWS và có kế hoạch chạy khối lượng công việc thử nghiệm trong 3 đến 6 tháng trên AWS. Mô hình định giá nào sẽ đáp ứng được những yêu cầu này?', 'Domain 4: Billing, Pricing and Support', 'Billing, Pricing and Support', 'Phiên bản theo yêu cầu là mô hình định giá linh hoạt và tiết kiệm chi phí nhất cho khối lượng công việc ngắn hạn, thử nghiệm hoặc không thể đoán trước trên AWS. Phiên bản Theo yêu cầu cho phép bạn chỉ thanh toán cho những tài nguyên bạn sử dụng mà không cần bất kỳ cam kết dài hạn hoặc phí trả trước nào. Bạn có thể dễ dàng bắt đầu và dừng các phiên bản khi cần cũng như tăng hoặc giảm quy mô tùy theo nhu cầu của mình. Gói tiết kiệm, Phiên bản dự trữ và Máy chủ chuyên dụng đều là các mô hình định giá yêu cầu cam kết về mức sử dụng hoặc dung lượng nhất định trong thời hạn một hoặc ba năm. Các mô hình định giá này cung cấp mức giá thấp hơn so với Phiên bản theo yêu cầu, nhưng chúng không phù hợp với khối lượng công việc chỉ chạy trong 3 đến 6 tháng hoặc có cách sử dụng khác nhau. Savings Plans và Reserved Instances cũng mang lại sự linh hoạt trong việc thay đổi loại phiên bản, kích thước hoặc khu vực trong cùng một dòng hoặc nhóm, trong khi Máy chủ chuyên dụng là máy chủ vật lý chỉ có thể chạy các loại phiên bản cụ thể.', '[{"label": "A", "text_vi": "Sử dụng Kế hoạch tiết kiệm trong thời hạn 3 năm.", "is_correct": false, "analysis_vi": "Sai. Phiên bản theo yêu cầu là mô hình định giá linh hoạt và tiết kiệm chi phí nhất cho khối lượng công việc ngắn hạn, thử nghiệm hoặc không thể đoán trước trên AWS."}, {"label": "B", "text_vi": "Sử dụng máy chủ chuyên dụng.", "is_correct": false, "analysis_vi": "Sai. Phiên bản Theo yêu cầu cho phép bạn chỉ thanh toán cho những tài nguyên bạn sử dụng mà không cần bất kỳ cam kết dài hạn hoặc phí trả trước nào."}, {"label": "C", "text_vi": "Mua phiên bản dự trữ.", "is_correct": false, "analysis_vi": "Sai. Phiên bản theo yêu cầu là mô hình định giá linh hoạt và tiết kiệm chi phí nhất cho khối lượng công việc ngắn hạn, thử nghiệm hoặc không thể đoán trước trên AWS."}, {"label": "D", "text_vi": "Sử dụng phiên bản theo yêu cầu.", "is_correct": true, "analysis_vi": "Đúng. Sử dụng phiên bản theo yêu cầu. là đáp án chính xác. Phiên bản theo yêu cầu là mô hình định giá linh hoạt và tiết kiệm chi phí nhất cho khối lượng công việc ngắn hạn, thử nghiệm hoặc không thể đoán trước trên AWS."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
