INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-78', 'practice_283', 'Những dịch vụ hoặc tính năng nào của AWS có thể kiểm soát lưu lượng VPC? (Chọn HAI.)', 'Domain 2: Security and Compliance', 'Hạ tầng mạng & Phân phối nội dung (VPC & Networking)', 'Các dịch vụ hoặc tính năng AWS có thể kiểm soát lưu lượng VPC là các Security Group và ACL mạng. Security Group là tường lửa có trạng thái kiểm soát lưu lượng truy cập vào và ra ở cấp phiên bản. Bạn có thể chỉ định một hoặc nhiều Security Group cho từng phiên bản trong VPC và chỉ định các quy tắc cho phép hoặc từ chối lưu lượng truy cập dựa trên giao thức, cổng và nguồn hoặc đích. ACL mạng là tường lửa không trạng thái kiểm soát lưu lượng truy cập vào và ra ở cấp mạng con. Bạn có thể liên kết một ACL mạng với mỗi mạng con trong VPC và chỉ định các quy tắc cho phép hoặc từ chối lưu lượng truy cập dựa trên giao thức, cổng và nguồn hoặc đích. AWS Direct Connect, Amazon GuardDuty và Amazon Connect không phải là các dịch vụ hoặc tính năng có thể kiểm soát lưu lượng VPC. AWS Direct Connect là dịch vụ thiết lập kết nối mạng chuyên dụng giữa cơ sở của bạn và AWS. Amazon GuardDuty là dịch vụ giám sát tài khoản AWS và khối lượng công việc của bạn để phát hiện hoạt động độc hại hoặc trái phép. Amazon Connect là dịch vụ cung cấp giải pháp trung tâm liên lạc dựa trên đám mây.', '[{"label": "A", "text_vi": "Security Group", "is_correct": true, "analysis_vi": "Đúng. Security Group là đáp án chính xác. Các dịch vụ hoặc tính năng AWS có thể kiểm soát lưu lượng VPC là các Security Group và ACL mạng."}, {"label": "B", "text_vi": "Kết nối trực tiếp AWS", "is_correct": false, "analysis_vi": "Sai. AWS Direct Connect, Amazon GuardDuty và Amazon Connect không phải là các dịch vụ hoặc tính năng có thể kiểm soát lưu lượng VPC."}, {"label": "C", "text_vi": "Nhiệm vụ bảo vệ của Amazon", "is_correct": false, "analysis_vi": "Sai. AWS Direct Connect, Amazon GuardDuty và Amazon Connect không phải là các dịch vụ hoặc tính năng có thể kiểm soát lưu lượng VPC."}, {"label": "D", "text_vi": "ACL mạng", "is_correct": true, "analysis_vi": "Đúng. ACL mạng là đáp án chính xác. Các dịch vụ hoặc tính năng AWS có thể kiểm soát lưu lượng VPC là các Security Group và ACL mạng."}, {"label": "E", "text_vi": "Kết nối Amazon", "is_correct": false, "analysis_vi": "Sai. AWS Direct Connect, Amazon GuardDuty và Amazon Connect không phải là các dịch vụ hoặc tính năng có thể kiểm soát lưu lượng VPC."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon GuardDuty", "Amazon VPC", "AWS Direct Connect"]'::jsonb, NOW())
