INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-79', 'practice_283', 'Công ty cần theo dõi hoạt động trong tài khoản AWS của mình và cần biết khi nào lệnh gọi API được thực hiện đối với tài nguyên AWS của mình. Có thể sử dụng công cụ hoặc dịch vụ AWS nào để đáp ứng những yêu cầu này?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'AWS CloudTrail là dịch vụ có thể được sử dụng để đáp ứng các yêu cầu này. AWS CloudTrail là dịch vụ ghi lại lệnh gọi API AWS cho tài khoản của bạn và cung cấp tệp nhật ký cho bạn. Thông tin được ghi lại bao gồm danh tính của lệnh gọi API, thời gian của lệnh gọi API, địa chỉ IP nguồn của lệnh gọi API, tham số yêu cầu và các thành phần phản hồi được dịch vụ AWS1 trả về. Bạn có thể sử dụng CloudTrail để theo dõi hoạt động trong tài khoản AWS của mình, chẳng hạn như ai đã thực hiện lệnh gọi API, thời điểm thực hiện và tài nguyên nào bị ảnh hưởng. Bạn cũng có thể sử dụng CloudTrail để giám sát tính tuân thủ, bảo mật và quản trị môi trường AWS2 của mình. Các dịch vụ khác không được thiết kế để theo dõi hoạt động và lệnh gọi API trong tài khoản AWS của bạn. Amazon CloudWatch là dịch vụ giám sát và thu thập số liệu, nhật ký và sự kiện từ các tài nguyên và ứng dụng AWS của bạn. Bạn có thể sử dụng CloudWatch để đặt cảnh báo, trực quan hóa dữ liệu và tự động hóa các hành động dựa trên ngưỡng hoặc quy tắc được xác định trước3. Amazon Inspector là dịch vụ giúp bạn cải thiện tính bảo mật và tuân thủ của các ứng dụng chạy trên AWS. Thanh tra tự động đánh giá các ứng dụng để phát hiện khả năng bị lộ, lỗ hổng và sai lệch so với các phương pháp hay nhất4. AWS IAM là dịch vụ cho phép bạn quản lý quyền truy cập vào các dịch vụ và tài nguyên AWS một cách an toàn. IAM cho phép bạn tạo và quản lý người dùng và nhóm AWS, đồng thời sử dụng các quyền để cho phép và từ chối quyền truy cập của họ vào tài nguyên AWS.', '[{"label": "A", "text_vi": "Amazon CloudWatch", "is_correct": false, "analysis_vi": "Sai. Amazon CloudWatch: Amazon CloudWatch là dịch vụ giám sát và quan sát tài nguyên, thu thập chỉ số (metrics), log và gửi cảnh báo (alarms) theo thời gian thực. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon Inspector", "is_correct": false, "analysis_vi": "Sai. Amazon Inspector: Amazon Inspector là dịch vụ quản lý lỗ hổng bảo mật tự động, quét các lỗ hổng phần mềm và phát hiện phơi nhiễm mạng ngoài ý muốn trên EC2, ECR và Lambda. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "AWS CloudTrail", "is_correct": true, "analysis_vi": "Đúng. AWS CloudTrail là đáp án chính xác. AWS CloudTrail là dịch vụ có thể được sử dụng để đáp ứng các yêu cầu này."}, {"label": "D", "text_vi": "AWS IAM", "is_correct": false, "analysis_vi": "Sai. AWS IAM: AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon CloudWatch", "AWS CloudTrail", "Amazon Inspector", "AWS IAM"]'::jsonb, NOW())
ON CONFLICT (question_id) DO UPDATE SET
  question_vi = EXCLUDED.question_vi,
  domain = EXCLUDED.domain,
