  updated_at = NOW();

INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-80', 'practice_283', 'Một công ty muốn đảm bảo rằng tất cả các phiên bản Amazon EC2 của mình đều có các bản vá hệ điều hành tuân thủ. Dịch vụ AWS nào sẽ đáp ứng những yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'AWS Systems Manager cung cấp cho bạn khả năng hiển thị và kiểm soát cơ sở hạ tầng của bạn trên AWS. Trình quản lý hệ thống cung cấp giao diện người dùng thống nhất để bạn có thể xem dữ liệu vận hành từ nhiều dịch vụ AWS và cho phép bạn tự động hóa các tác vụ vận hành trên các tài nguyên AWS của mình. Bạn có thể sử dụng Trình quản lý Hệ thống để áp dụng các bản vá hệ điều hành, tạo hình ảnh hệ thống, đặt cấu hình hệ điều hành Windows và Linux cũng như thực thi các lệnh PowerShell5. Trình quản lý hệ thống có thể giúp bạn đảm bảo rằng tất cả các phiên bản Amazon EC2 của bạn đều có các bản vá hệ điều hành tuân thủ bằng cách sử dụng tính năng Trình quản lý bản vá.', '[{"label": "A", "text_vi": "Trình tối ưu hóa điện toán AWS", "is_correct": false, "analysis_vi": "Sai. Trình tối ưu hóa điện toán AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "AWS Elastic Beanstalk", "is_correct": false, "analysis_vi": "Sai. AWS Elastic Beanstalk: AWS Elastic Beanstalk là dịch vụ PaaS cho phép lập trình viên tải mã nguồn lên và AWS tự động xử lý việc cấp phát máy chủ, cân bằng tải, tự động co giãn và giám sát. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Đồng bộ hóa ứng dụng AWS", "is_correct": false, "analysis_vi": "Sai. Đồng bộ hóa ứng dụng AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Trình quản lý hệ thống AWS", "is_correct": true, "analysis_vi": "Đúng. Trình quản lý hệ thống AWS là đáp án chính xác. AWS Systems Manager cung cấp cho bạn khả năng hiển thị và kiểm soát cơ sở hạ tầng của bạn trên AWS."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "AWS Elastic Beanstalk", "AWS Secrets Manager"]'::jsonb, NOW())
