INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-81', 'practice_283', 'Một công ty đang thiết kế một ứng dụng web sẽ chạy trên các phiên bản Amazon EC2. Những dịch vụ và tính năng nào của AWS sẽ cải thiện tính khả dụng và giảm tác động của lỗi đối với ứng dụng này? (Chọn HAI.)', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'Câu trả lời đúng là A và C vì Amazon EC2 Auto Scaling và các tài nguyên được phân phối trên nhiều Availability Zone (AZ) là các dịch vụ và tính năng AWS sẽ cải thiện độ sẵn sàng và giảm tác động của lỗi đối với ứng dụng web. Amazon EC2 Auto Scaling là dịch vụ cho phép người dùng tự động điều chỉnh số lượng phiên bản Amazon EC2 để đáp ứng những thay đổi về nhu cầu hoặc hiệu suất. Amazon EC2 Auto Scaling giúp người dùng duy trì độ khả dụng và hiệu suất tối ưu cho ứng dụng của họ bằng cách thêm hoặc xóa phiên bản nếu cần. Tài nguyên được phân phối trên nhiều Availability Zone (AZ) là các tính năng của AWS cho phép người dùng tăng khả năng chịu lỗi và khả năng phục hồi cho ứng dụng của họ. Availability Zone (AZ) là các vị trí biệt lập trong AWS Region có nguồn điện, khả năng làm mát và kết nối mạng độc lập. Người dùng có thể khởi chạy tài nguyên của mình, chẳng hạn như phiên bản Amazon EC2, trong nhiều Availability Zone (AZ) để bảo vệ ứng dụng của họ khỏi lỗi ở một vị trí. Các tùy chọn khác không chính xác vì chúng không phải là các dịch vụ và tính năng của AWS sẽ cải thiện tính khả dụng và giảm tác động của lỗi đối với ứng dụng web. ACL mạng con VPC là các tính năng của AWS cho phép người dùng kiểm soát lưu lượng vào và ra đến và đi từ mạng con của họ trong VPC. ACL mạng con VPC không kiểm tra tình trạng của dịch vụ mà lọc lưu lượng mạng dựa trên các quy tắc. Cấu hình của Dịch vụ di chuyển máy chủ AWS (AWS SMS) là dịch vụ AWS cho phép người dùng di chuyển máy chủ tại chỗ của họ sang AWS. Cấu hình của AWS SMS không giúp di chuyển các phiên bản Amazon EC2 sang AWS Region khác mà giúp di chuyển các máy chủ từ môi trường nguồn sang AWS. Tài nguyên được phân bổ trên nhiều điểm hiện diện của AWS là các tính năng của AWS cho phép người dùng phân phối nội dung đến người dùng cuối với độ trễ thấp và hiệu suất cao. Điểm hiện diện của AWS là các vị trí biên nằm trong Cơ sở hạ tầng toàn cầu của AWS. Người dùng có thể sử dụng các dịch vụ như Amazon CloudFront và AWS Global Accelerator để phân phối nội dung của họ trên nhiều điểm hiện diện AWS.', '[{"label": "A", "text_vi": "Amazon EC2 Auto Scaling cho phiên bản EC2", "is_correct": true, "analysis_vi": "Đúng. Amazon EC2 Auto Scaling cho phiên bản EC2 là đáp án chính xác. Câu trả lời đúng là A và C vì Amazon EC2 Auto Scaling và các tài nguyên được phân phối trên nhiều Availability Zone (AZ) là các dịch vụ và tính năng AWS sẽ cải thiện độ sẵn sàng và giảm tác động của lỗi đối với ứng dụng web."}, {"label": "B", "text_vi": "ACL mạng con VPC để kiểm tra tình trạng của dịch vụ", "is_correct": false, "analysis_vi": "Sai. ACL mạng con VPC để kiểm tra tình trạng của dịch vụ: Amazon VPC cho phép khởi tạo mạng ảo riêng biệt được cô lập logic trên đám mây AWS, kiểm soát toàn diện dải IP, subnet, bảng định tuyến và cổng mạng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Tài nguyên được phân phối trên nhiều Availability Zone (AZ)", "is_correct": true, "analysis_vi": "Đúng. Tài nguyên được phân phối trên nhiều Availability Zone (AZ) là đáp án chính xác. Câu trả lời đúng là A và C vì Amazon EC2 Auto Scaling và các tài nguyên được phân phối trên nhiều Availability Zone (AZ) là các dịch vụ và tính năng AWS sẽ cải thiện độ sẵn sàng và giảm tác động của lỗi đối với ứng dụng web."}, {"label": "D", "text_vi": "Cấu hình Dịch vụ di chuyển máy chủ AWS (AWS SMS) để di chuyển các phiên bản EC2 sang AWS Region khác", "is_correct": false, "analysis_vi": "Sai. Cấu hình Dịch vụ di chuyển máy chủ AWS (AWS SMS) để di chuyển các phiên bản EC2 sang AWS Region khác: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "E", "text_vi": "Tài nguyên được phân phối trên nhiều điểm hiện diện của AWS", "is_correct": false, "analysis_vi": "Sai. Tài nguyên được phân phối trên nhiều điểm hiện diện của AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "Amazon VPC"]'::jsonb, NOW())
ON CONFLICT (question_id) DO UPDATE SET
  question_vi = EXCLUDED.question_vi,
