  updated_at = NOW();

INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-82', 'practice_283', 'Một công ty muốn có cơ sở dữ liệu NoSQL có giá trị khóa được quản lý hoàn toàn và không có máy chủ. Dịch vụ AWS nào sẽ đáp ứng những yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'Amazon DynamoDB là cơ sở dữ liệu tài liệu và khóa-giá trị mang lại hiệu suất mili giây một chữ số ở mọi quy mô. Đây là cơ sở dữ liệu không có máy chủ, được quản lý hoàn toàn, không yêu cầu cung cấp, vá lỗi hoặc sao lưu. Nó cung cấp tính năng bảo mật, sao lưu và khôi phục tích hợp cũng như bộ nhớ đệm trong bộ nhớ3. Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ giúp dễ dàng thiết lập, vận hành và mở rộng quy mô cơ sở dữ liệu quan hệ trên đám mây. Nó cung cấp khả năng tiết kiệm chi phí và có thể thay đổi kích thước đồng thời tự động hóa các tác vụ quản trị tốn thời gian như cung cấp phần cứng, thiết lập cơ sở dữ liệu, vá lỗi và sao lưu. Tuy nhiên, đây không phải là cơ sở dữ liệu NoSQL khóa-giá trị và không phải là không có máy chủ vì nó yêu cầu bạn chọn loại phiên bản và kích thước4. Amazon Aurora là cơ sở dữ liệu quan hệ tương thích với MySQL và PostgreSQL được xây dựng cho đám mây, kết hợp hiệu suất và tính khả dụng của cơ sở dữ liệu doanh nghiệp truyền thống với tính đơn giản và hiệu quả về mặt chi phí của cơ sở dữ liệu nguồn mở. Tuy nhiên, nó cũng không phải là cơ sở dữ liệu NoSQL khóa-giá trị và không phải là không có máy chủ vì nó yêu cầu bạn chọn loại và kích thước phiên bản. Amazon MemoryDB for Redis là dịch vụ cơ sở dữ liệu trong bộ nhớ, bền bỉ, tương thích với Redis, mang lại hiệu năng cực nhanh và độ tin cậy đa Availability Zone (AZ) cho các ứng dụng có yêu cầu khắt khe nhất. Tuy nhiên, nó cũng không phải là cơ sở dữ liệu NoSQL có giá trị khóa và không phải là không có máy chủ vì nó yêu cầu bạn chọn loại và kích thước nút.', '[{"label": "A", "text_vi": "Amazon DynamoDB", "is_correct": true, "analysis_vi": "Đúng. Amazon DynamoDB là đáp án chính xác. Amazon DynamoDB là cơ sở dữ liệu tài liệu và khóa-giá trị mang lại hiệu suất mili giây một chữ số ở mọi quy mô."}, {"label": "B", "text_vi": "Amazon RDS", "is_correct": false, "analysis_vi": "Sai. Amazon RDS: Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Amazon cực quang", "is_correct": false, "analysis_vi": "Sai. Amazon cực quang: Amazon Aurora là cơ sở dữ liệu quan hệ tương thích MySQL/PostgreSQL hiệu năng cao gấp 3-5 lần, tự động sao chép 6 bản dữ liệu qua 3 AZ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Cơ sở dữ liệu bộ nhớ Amazon dành cho Redis", "is_correct": false, "analysis_vi": "Sai. Cơ sở dữ liệu bộ nhớ Amazon dành cho Redis không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon RDS", "Amazon Aurora", "Amazon DynamoDB"]'::jsonb, NOW())
