  updated_at = NOW();

INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-83', 'practice_283', 'Dịch vụ hoặc tính năng AWS nào cho phép người dùng tạo tài khoản AWS mới, nhóm nhiều tài khoản để sắp xếp quy trình công việc và áp dụng chính sách cho các nhóm tài khoản?', 'Domain 3: Cloud Technology and Services', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'AWS Organs là dịch vụ hoặc tính năng AWS cho phép người dùng tạo tài khoản AWS mới, nhóm nhiều tài khoản để sắp xếp quy trình công việc và áp dụng chính sách cho các nhóm tài khoản. AWS Organizations cho phép người dùng quản lý và điều hành tập trung môi trường AWS của họ trên nhiều tài khoản. Người dùng có thể tạo các đơn vị tổ chức (OU) để nhóm các tài khoản dựa trên nhu cầu kinh doanh của họ, chẳng hạn như theo chức năng, dự án hoặc khu vực. Người dùng cũng có thể áp dụng chính sách kiểm soát dịch vụ (SCP) cho OU hoặc tài khoản cá nhân để xác định quyền và hạn chế đối với các dịch vụ và tài nguyên AWS mà họ có thể truy cập. AWS Organizations cũng cung cấp các tính năng như thanh toán tổng hợp, tự động tạo tài khoản và quyền truy cập đáng tin cậy12.', '[{"label": "A", "text_vi": "Quản lý quyền truy cập và nhận dạng AWS (1 giờ sáng)", "is_correct": false, "analysis_vi": "Sai. Quản lý quyền truy cập và nhận dạng AWS (1 giờ sáng) không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "AWS Trusted Advisor", "is_correct": false, "analysis_vi": "Sai. AWS Trusted Advisor: AWS Trusted Advisor quét toàn bộ tài khoản AWS và đưa ra khuyến nghị tối ưu theo 5 trụ cột: Chi phí, Hiệu năng, Bảo mật, Khả năng chịu lỗi và Giới hạn dịch vụ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Đám mây AWS", "is_correct": false, "analysis_vi": "Sai. Đám mây AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "AWS Organizations", "is_correct": true, "analysis_vi": "Đúng. AWS Organizations là đáp án chính xác. AWS Organizations cho phép người dùng quản lý và điều hành tập trung môi trường AWS của họ trên nhiều tài khoản."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Trusted Advisor", "AWS Organizations", "AWS CloudFormation"]'::jsonb, NOW())
