INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-84', 'practice_283', 'Một công ty cần một mạng phân phối nội dung cung cấp khả năng phân phối dữ liệu, video, ứng dụng và API an toàn cho người dùng trên toàn cầu với độ trễ thấp và tốc độ truyền cao. Dịch vụ AWS nào đáp ứng các yêu cầu này?', 'Domain 2: Security and Compliance', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Câu trả lời đúng là A vì Amazon CloudFront là dịch vụ AWS cung cấp khả năng phân phối dữ liệu, video, ứng dụng và API an toàn cho người dùng trên toàn cầu với độ trễ thấp và tốc độ truyền cao. Amazon CloudFront là mạng phân phối nội dung nhanh (CDN) tích hợp với các dịch vụ AWS khác, chẳng hạn như Amazon S3, Amazon EC2, AWS Lambda và AWS Shield. Amazon CloudFront cung cấp nội dung thông qua mạng lưới toàn cầu gồm các vị trí biên nằm gần người dùng cuối. Các tùy chọn khác không chính xác vì chúng không phải là dịch vụ AWS cung cấp khả năng phân phối dữ liệu, video, ứng dụng và API an toàn cho người dùng trên toàn cầu với độ trễ thấp và tốc độ truyền cao. Cân bằng tải đàn hồi là một dịch vụ AWS phân phối lưu lượng truy cập đến trên nhiều mục tiêu, chẳng hạn như phiên bản, bộ chứa và địa chỉ IP của Amazon EC2. Amazon S3 là dịch vụ AWS cung cấp khả năng lưu trữ đối tượng cho dữ liệu ở mọi kích thước và loại. Amazon Elastic Transcode là dịch vụ AWS giúp chuyển đổi các tệp phương tiện từ định dạng nguồn ban đầu thành các định dạng khác nhau sẽ phát trên nhiều thiết bị khác nhau.', '[{"label": "A", "text_vi": "Amazon CloudFront", "is_correct": true, "analysis_vi": "Đúng. Amazon CloudFront là đáp án chính xác. Câu trả lời đúng là A vì Amazon CloudFront là dịch vụ AWS cung cấp khả năng phân phối dữ liệu, video, ứng dụng và API an toàn cho người dùng trên toàn cầu với độ trễ thấp và tốc độ truyền cao."}, {"label": "B", "text_vi": "Cân bằng tải đàn hồi", "is_correct": false, "analysis_vi": "Sai. Cân bằng tải đàn hồi không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Amazon S3", "is_correct": false, "analysis_vi": "Sai. Amazon S3: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Bộ chuyển mã đàn hồi Amazon", "is_correct": false, "analysis_vi": "Sai. Bộ chuyển mã đàn hồi Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon S3", "Amazon CloudFront"]'::jsonb, NOW())
