INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-85', 'practice_283', 'Câu nào sau đây là đề xuất giá trị của AWS mô tả khả năng của người dùng trong việc mở rộng quy mô cơ sở hạ tầng dựa trên nhu cầu?', 'Domain 1: Cloud Concepts', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Độ co giãn của tài nguyên là một đề xuất giá trị của AWS mô tả khả năng của người dùng trong việc mở rộng quy mô cơ sở hạ tầng dựa trên nhu cầu. Độ co giãn của tài nguyên có nghĩa là người dùng có thể cung cấp hoặc hủy cung cấp tài nguyên một cách nhanh chóng và dễ dàng mà không cần bất kỳ cam kết trả trước hoặc hợp đồng dài hạn nào. Độ co giãn của tài nguyên có thể giúp người dùng tối ưu hóa chi phí và hiệu suất của ứng dụng cũng như đáp ứng nhu cầu kinh doanh đang thay đổi và mong đợi của khách hàng. Có thể đạt được độ co giãn của tài nguyên bằng cách sử dụng các dịch vụ như Amazon EC2, Amazon S3, Amazon RDS, Amazon DynamoDB, Amazon ECS và AWS Lambda. [Khung giá trị đám mây AWS] Người thực hành đám mây được chứng nhận AWS - aws.amazon.com', '[{"label": "A", "text_vi": "Tốc độ đổi mới", "is_correct": false, "analysis_vi": "Sai. Tốc độ đổi mới không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Độ co giãn của tài nguyên", "is_correct": true, "analysis_vi": "Đúng. Độ co giãn của tài nguyên là đáp án chính xác. Độ co giãn của tài nguyên là một đề xuất giá trị của AWS mô tả khả năng của người dùng trong việc mở rộng quy mô cơ sở hạ tầng dựa trên nhu cầu."}, {"label": "C", "text_vi": "Kiến trúc tách rời", "is_correct": false, "analysis_vi": "Sai. Kiến trúc tách rời không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Triển khai toàn cầu", "is_correct": false, "analysis_vi": "Sai. Triển khai toàn cầu không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
