INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-86', 'practice_283', 'Dịch vụ AWS nào cung cấp khả năng quản lý cơ sở hạ tầng dưới dạng mã?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Dịch vụ AWS cung cấp khả năng quản lý cơ sở hạ tầng dưới dạng mã là AWS CloudFormation. Cơ sở hạ tầng dưới dạng mã là một quá trình xác định và cung cấp tài nguyên AWS bằng cách sử dụng mã hoặc mẫu, thay vì các hành động hoặc tập lệnh thủ công. AWS CloudFormation cho phép bạn tạo và cập nhật các ngăn xếp tài nguyên AWS dựa trên các mẫu được xác định trước để mô tả trạng thái và cấu hình mong muốn của tài nguyên. AWS CloudFormation tự động hóa và đơn giản hóa việc triển khai cũng như quản lý tài nguyên AWS, đồng thời đảm bảo tính nhất quán và khả năng lặp lại trên các môi trường và khu vực khác nhau. AWS CloudFormation cũng hỗ trợ các tính năng khôi phục, nhóm thay đổi, phát hiện sai lệch và ngăn xếp lồng nhau giúp bạn giám sát và kiểm soát các thay đổi đối với cơ sở hạ tầng của mình1.', '[{"label": "A", "text_vi": "Đường dẫn mã AWS", "is_correct": false, "analysis_vi": "Sai. Đường dẫn mã AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "AWS CodeDeploy", "is_correct": false, "analysis_vi": "Sai. AWS CodeDeploy không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Kết nối trực tiếp AWS", "is_correct": false, "analysis_vi": "Sai. Kết nối trực tiếp AWS: AWS Direct Connect thiết lập kết nối mạng chuyên dụng riêng biệt từ hạ tầng on-premises tới AWS, bỏ qua mạng Internet công cộng để có băng thông ổn định. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Đám mây AWS", "is_correct": true, "analysis_vi": "Đúng. Đám mây AWS là đáp án chính xác. Dịch vụ AWS cung cấp khả năng quản lý cơ sở hạ tầng dưới dạng mã là AWS CloudFormation."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Direct Connect", "AWS CloudFormation"]'::jsonb, NOW())
