INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-87', 'practice_283', 'Một công ty đang di chuyển máy chủ cơ sở dữ liệu quan hệ sang Đám mây AWS. Công ty muốn giảm thiểu chi phí hành chính cho các nhiệm vụ bảo trì cơ sở dữ liệu. Dịch vụ AWS nào sẽ đáp ứng những yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Quản lý chi phí & Thanh toán AWS', 'Amazon RDS là dịch vụ AWS sẽ đáp ứng các yêu cầu di chuyển máy chủ cơ sở dữ liệu quan hệ sang Đám mây AWS và giảm thiểu chi phí quản trị cho các tác vụ bảo trì cơ sở dữ liệu. Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý toàn phần, xử lý các tác vụ cơ sở dữ liệu thông thường, chẳng hạn như cung cấp, vá lỗi, sao lưu, phục hồi, phát hiện lỗi và sửa chữa. Amazon RDS hỗ trợ một số công cụ cơ sở dữ liệu, chẳng hạn như MySQL, PostgreSQL, Oracle, SQL Server và Amazon Aurora5.', '[{"label": "A", "text_vi": "Amazon DynamoDB", "is_correct": false, "analysis_vi": "Sai. Amazon DynamoDB: Amazon DynamoDB là cơ sở dữ liệu NoSQL (Key-Value và Document) serverless, cung cấp hiệu năng dưới 10 mili-giây ổn định ở mọi quy mô. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon EC2", "is_correct": false, "analysis_vi": "Sai. Amazon EC2: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Dịch chuyển đỏ của Amazon", "is_correct": false, "analysis_vi": "Sai. Dịch chuyển đỏ của Amazon: Amazon Redshift là kho dữ liệu đám mây (Data Warehouse) phục vụ phân tích dữ liệu lớn và OLAP ở quy mô petabyte. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Amazon RDS", "is_correct": true, "analysis_vi": "Đúng. Amazon RDS là giải pháp đáp ứng yêu cầu. Amazon RDS là dịch vụ AWS sẽ đáp ứng các yêu cầu di chuyển máy chủ cơ sở dữ liệu quan hệ sang Đám mây AWS và giảm thiểu chi phí quản trị cho các tác vụ bảo trì cơ sở dữ liệu. Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["Amazon EC2", "Amazon RDS", "Amazon DynamoDB"]'::jsonb, NOW())
