INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-88', 'practice_283', 'Một công ty cần lưu trữ dữ liệu trên nhiều Availability Zone (AZ) trong AWS Region. Dữ liệu sẽ không được truy cập thường xuyên nhưng phải có thể truy xuất được ngay lập tức. Lớp lưu trữ Amazon EFS (Amazon EFS) nào đáp ứng các yêu cầu này một cách hiệu quả nhất về mặt chi phí?', 'Domain 3: Cloud Technology and Services', 'Quản lý chi phí & Thanh toán AWS', 'Truy cập tiêu chuẩn-không thường xuyên EFS (EFS Standard-IA) là lớp lưu trữ đáp ứng các yêu cầu lưu trữ dữ liệu trên nhiều Availability Zone (AZ) trong AWS Region, loại dữ liệu này sẽ không được truy cập thường xuyên nhưng phải có khả năng truy xuất ngay lập tức, tiết kiệm chi phí nhất. EFS Standard-IA được thiết kế cho các tệp ít được truy cập thường xuyên hơn nhưng vẫn yêu cầu hiệu suất cao, độ trễ thấp và tính khả dụng cao như EFS Standard. EFS Standard-IA có chi phí lưu trữ thấp hơn EFS Standard nhưng tính thêm một khoản phí nhỏ cho mỗi lần truy cập. EFS One Zone và EFS One Zone-IA lưu trữ dữ liệu trong một Availability Zone (AZ) duy nhất, điều này làm giảm tính khả dụng và độ bền so với EFS Standard và EFS Standard-IA.', '[{"label": "A", "text_vi": "Tiêu chuẩn EFS", "is_correct": false, "analysis_vi": "Sai. Truy cập tiêu chuẩn-không thường xuyên EFS (EFS Standard-IA) là lớp lưu trữ đáp ứng các yêu cầu lưu trữ dữ liệu trên nhiều Availability Zone (AZ) trong AWS Region, loại dữ liệu này sẽ không được truy cập thường xuyên nhưng phải có khả năng truy xuất ngay lập tức, tiết kiệm chi phí nhất."}, {"label": "B", "text_vi": "Truy cập không thường xuyên theo tiêu chuẩn EFS (EFS Standard-IA)", "is_correct": true, "analysis_vi": "Đúng. Truy cập không thường xuyên theo tiêu chuẩn EFS (EFS Standard-IA) là đáp án chính xác. Truy cập tiêu chuẩn-không thường xuyên EFS (EFS Standard-IA) là lớp lưu trữ đáp ứng các yêu cầu lưu trữ dữ liệu trên nhiều Availability Zone (AZ) trong AWS Region, loại dữ liệu này sẽ không được truy cập thường xuyên nhưng phải có khả năng truy xuất ngay lập tức, tiết kiệm chi phí nhất."}, {"label": "C", "text_vi": "EFS Một Khu", "is_correct": false, "analysis_vi": "Sai. Truy cập tiêu chuẩn-không thường xuyên EFS (EFS Standard-IA) là lớp lưu trữ đáp ứng các yêu cầu lưu trữ dữ liệu trên nhiều Availability Zone (AZ) trong AWS Region, loại dữ liệu này sẽ không được truy cập thường xuyên nhưng phải có khả năng truy xuất ngay lập tức, tiết kiệm chi phí nhất."}, {"label": "D", "text_vi": "Truy cập không thường xuyên một vùng EFS (EFS One Zone-IA)", "is_correct": false, "analysis_vi": "Sai. Truy cập tiêu chuẩn-không thường xuyên EFS (EFS Standard-IA) là lớp lưu trữ đáp ứng các yêu cầu lưu trữ dữ liệu trên nhiều Availability Zone (AZ) trong AWS Region, loại dữ liệu này sẽ không được truy cập thường xuyên nhưng phải có khả năng truy xuất ngay lập tức, tiết kiệm chi phí nhất."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '[]'::jsonb, NOW())
