INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-89', 'practice_283', 'Một công ty muốn cung cấp các ứng dụng và máy tính để bàn ảo Windows được quản lý cho nhân viên từ xa của mình qua kết nối mạng an toàn. Công ty có thể sử dụng những dịch vụ AWS nào để đáp ứng những yêu cầu này? (Chọn HAI.)', 'Domain 3: Cloud Technology and Services', 'Hạ tầng mạng & Phân phối nội dung (VPC & Networking)', 'Amazon AppStream 2.0 và Amazon WorkSpaces là các dịch vụ AWS có thể được sử dụng để cung cấp các ứng dụng và máy tính để bàn ảo Windows được quản lý cho nhân viên từ xa qua kết nối mạng an toàn. Amazon AppStream 2.0 là dịch vụ phát trực tuyến ứng dụng được quản lý hoàn toàn, cho phép người dùng truy cập các ứng dụng máy tính để bàn Windows từ bất kỳ thiết bị nào mà không cần cài đặt hay quản lý bất kỳ phần mềm nào. Amazon AppStream 2.0 cung cấp các ứng dụng qua kết nối được mã hóa và cách ly chúng khỏi cơ sở hạ tầng cơ bản, đảm bảo tính bảo mật và tuân thủ1. Amazon WorkSpaces là dịch vụ ảo hóa máy tính để bàn được quản lý hoàn toàn, cho phép người dùng truy cập máy tính để bàn Windows hoặc Linux từ bất kỳ thiết bị nào với trải nghiệm người dùng nhất quán. Amazon WorkSpaces cung cấp máy tính để bàn ảo dựa trên đám mây ổn định, có thể tùy chỉnh và thay đổi quy mô theo nhu cầu của người dùng. Amazon WorkSpaces cũng cung cấp các tính năng mã hóa, sao lưu và giám sát để đảm bảo tính bảo mật và độ tin cậy2.', '[{"label": "A", "text_vi": "Kết nối Amazon", "is_correct": false, "analysis_vi": "Sai. Kết nối Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Amazon AppStream 2.0", "is_correct": true, "analysis_vi": "Đúng. Amazon AppStream 2.0 là đáp án chính xác. Amazon AppStream 2.0 và Amazon WorkSpaces là các dịch vụ AWS có thể được sử dụng để cung cấp các ứng dụng và máy tính để bàn ảo Windows được quản lý cho nhân viên từ xa qua kết nối mạng an toàn."}, {"label": "C", "text_vi": "Không gian làm việc của Amazon", "is_correct": true, "analysis_vi": "Đúng. Không gian làm việc của Amazon là đáp án chính xác. Amazon AppStream 2.0 và Amazon WorkSpaces là các dịch vụ AWS có thể được sử dụng để cung cấp các ứng dụng và máy tính để bàn ảo Windows được quản lý cho nhân viên từ xa qua kết nối mạng an toàn."}, {"label": "D", "text_vi": "VPN Site-to-Site của AWS", "is_correct": false, "analysis_vi": "Sai. VPN Site-to-Site của AWS: AWS Site-to-Site VPN tạo kết nối mạng riêng ảo bảo mật qua đường truyền Internet công cộng bằng giao thức IPsec giữa mạng on-premises và AWS VPC. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "E", "text_vi": "Dịch vụ container đàn hồi của Amazon (Amazon ECS)", "is_correct": false, "analysis_vi": "Sai. Dịch vụ container đàn hồi của Amazon (Amazon ECS): Amazon ECS là dịch vụ điều phối container Docker có khả năng mở rộng cao và hiệu năng cao trên AWS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Direct Connect"]'::jsonb, NOW())
