INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-90', 'practice_283', 'Một công ty muốn nhận được thông báo khi đạt đến ngưỡng chi phí AWS cụ thể. Công ty có thể sử dụng những dịch vụ hoặc công cụ AWS nào để đáp ứng yêu cầu này? (Chọn HAI.)', 'Domain 4: Billing, Pricing and Support', 'Quản lý chi phí & Thanh toán AWS', 'AWS Budgets và Amazon CloudWatch là hai dịch vụ hoặc công cụ AWS mà công ty có thể sử dụng để nhận thông báo khi đạt đến ngưỡng chi phí AWS cụ thể. Ngân sách AWS cho phép người dùng đặt ngân sách tùy chỉnh để theo dõi chi phí và mức sử dụng của họ, đồng thời phản hồi nhanh chóng các cảnh báo nhận được từ email hoặc thông báo của Dịch vụ thông báo đơn giản của Amazon (Amazon SNS) nếu chúng vượt quá ngưỡng. Người dùng có thể tạo ngân sách chi phí với số tiền mục tiêu cố định hoặc thay đổi và định cấu hình thông báo của họ cho mức chi tiêu thực tế hoặc dự báo. Người dùng cũng có thể thiết lập các hành động tùy chỉnh để chạy tự động hoặc thông qua quy trình phê duyệt khi vượt quá mục tiêu ngân sách. Ví dụ: người dùng có thể tự động áp dụng chính sách IAM tùy chỉnh để từ chối khả năng cung cấp tài nguyên bổ sung trong tài khoản của họ. Amazon CloudWatch là dịch vụ giám sát các ứng dụng, phản hồi những thay đổi về hiệu suất, tối ưu hóa việc sử dụng tài nguyên và cung cấp thông tin chi tiết về tình trạng hoạt động. Người dùng có thể sử dụng CloudWatch để thu thập và theo dõi số liệu, là những biến số mà họ có thể đo lường cho tài nguyên và ứng dụng của mình. Người dùng có thể tạo cảnh báo để theo dõi số liệu và gửi thông báo hoặc tự động thực hiện thay đổi đối với tài nguyên mà họ đang theo dõi khi vượt ngưỡng. Người dùng có thể sử dụng CloudWatch để giám sát chi phí và mức sử dụng AWS của mình bằng cách tạo cảnh báo thanh toán gửi thông báo khi mức phí ước tính của họ vượt quá ngưỡng chỉ định. Người dùng cũng có thể sử dụng CloudWatch để giám sát việc sử dụng và phạm vi của Phiên bản dự trữ (RI) hoặc Savings Plans, đồng thời nhận thông báo khi chúng giảm xuống dưới một mức nhất định.', '[{"label": "A", "text_vi": "Dịch vụ xếp hàng đơn giản của Amazon (Amazon SQS)", "is_correct": true, "analysis_vi": "Đúng. Dịch vụ xếp hàng đơn giản của Amazon (Amazon SQS) là đáp án chính xác. Ngân sách AWS cho phép người dùng đặt ngân sách tùy chỉnh để theo dõi chi phí và mức sử dụng của họ, đồng thời phản hồi nhanh chóng các cảnh báo nhận được từ email hoặc thông báo của Dịch vụ thông báo đơn giản của Amazon (Amazon SNS) nếu chúng vượt quá ngưỡng."}, {"label": "B", "text_vi": "Ngân sách AWS", "is_correct": false, "analysis_vi": "Sai. Ngân sách AWS: AWS Budgets cho phép thiết lập ngưỡng ngân sách tùy chỉnh và gửi thông báo hoặc kích hoạt hành động tự động khi chi phí dự kiến vượt ngưỡng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "AWS Cost Explorer", "is_correct": true, "analysis_vi": "Đúng. AWS Cost Explorer là giải pháp đáp ứng yêu cầu. AWS Budgets và Amazon CloudWatch là hai dịch vụ hoặc công cụ AWS mà công ty có thể sử dụng để nhận thông báo khi đạt đến ngưỡng chi phí AWS cụ thể. AWS Cost Explorer cung cấp giao diện trực quan để phân tích, hiểu rõ chi phí lịch sử và dự báo chi tiêu AWS trong tương lai lên đến 12 tháng."}, {"label": "D", "text_vi": "Amazon CloudWatch của Amazon", "is_correct": false, "analysis_vi": "Sai. Amazon CloudWatch của Amazon: Amazon CloudWatch là dịch vụ giám sát và quan sát tài nguyên, thu thập chỉ số (metrics), log và gửi cảnh báo (alarms) theo thời gian thực. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "E", "text_vi": "Báo cáo chi phí và mức sử dụng AWS", "is_correct": false, "analysis_vi": "Sai. Báo cáo chi phí và mức sử dụng AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["Amazon CloudWatch", "AWS Cost Explorer", "AWS Budgets", "Amazon SQS"]'::jsonb, NOW())
