INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-91', 'practice_283', 'Một công ty có một nền tảng truyền thông xã hội trong đó người dùng tải lên và chia sẻ ảnh với những người dùng khác. Công ty muốn xác định và loại bỏ những bức ảnh không phù hợp. Công ty không có nhà khoa học về máy học (ML) và phải xây dựng khả năng phát hiện này mà không có chuyên môn về ML. Công ty nên sử dụng dịch vụ AWS nào để xây dựng khả năng này?', 'Domain 3: Cloud Technology and Services', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Amazon Rekognition là dịch vụ AWS mà công ty nên sử dụng để xây dựng khả năng xác định và xóa những bức ảnh không phù hợp. Amazon Rekognition là dịch vụ sử dụng công nghệ deep learning để phân tích hình ảnh và video cho nhiều mục đích khác nhau, chẳng hạn như nhận diện khuôn mặt, nhận dạng đối tượng, trích xuất văn bản và kiểm duyệt nội dung. Amazon Rekognition có thể giúp người dùng phát hiện nội dung không an toàn hoặc không phù hợp trong hình ảnh và video, chẳng hạn như ảnh khỏa thân, bạo lực hoặc ma túy, đồng thời cung cấp điểm tin cậy cho từng nhãn. Amazon Rekognition không yêu cầu bất kỳ kiến ​​thức chuyên môn về máy học nào và người dùng có thể dễ dàng tích hợp nó với các dịch vụ AWS khác. Các bãi chứa AWS-Certified-Cloud-Practitioner hợp lệ được EduDump.com chia sẻ để giúp vượt qua kỳ thi dành cho người thực hành trên nền tảng đám mây được chứng nhận AWS! EduDump.com hiện cung cấp các kết xuất bài thi AWS- Certified-Cloud-Practitioner mới nhất, các câu hỏi thi EduDump.com AWS-Certified-Cloud-Practitioner đã được cập nhật và các câu trả lời đã được sửa. Hãy tải các kết xuất bài thi EduDump.com AWS-Certified-Cloud-Practitioner mới nhất với Test Engine tại đây: https://www.edudump.com/exams/Amazon/AWS-Certified-Cloud-Practitioner/premium/ ( 600 lượt hỏi đáp, GIẢM GIÁ 35% Mã giảm giá đặc biệt: freecram )', '[{"label": "A", "text_vi": "Amazon SageMaker", "is_correct": false, "analysis_vi": "Sai. Amazon SageMaker không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Văn bản Amazon", "is_correct": false, "analysis_vi": "Sai. Văn bản Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Nhận thức lại Amazon", "is_correct": true, "analysis_vi": "Đúng. Nhận thức lại Amazon là đáp án chính xác. Amazon Rekognition là dịch vụ AWS mà công ty nên sử dụng để xây dựng khả năng xác định và xóa những bức ảnh không phù hợp."}, {"label": "D", "text_vi": "Amazon Hiểu", "is_correct": false, "analysis_vi": "Sai. Amazon Hiểu không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
