INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-92', 'practice_283', 'Mục đích của việc có cổng internet trong VPC là gì?', 'Domain 2: Security and Compliance', 'Hạ tầng mạng & Phân phối nội dung (VPC & Networking)', 'Cổng internet là một dịch vụ cho phép lưu lượng truy cập internet đi vào VPC. Mặt khác, VPC hoàn toàn bị phân đoạn và khi đó cách duy nhất để truy cập nó là thông qua kết nối VPN thay vì kết nối internet. Cổng internet là kết nối logic giữa AWS VPC và internet. Nó hỗ trợ lưu lượng IPv4 và IPv6. Nó không gây ra rủi ro về tính khả dụng hoặc hạn chế về băng thông đối với lưu lượng truy cập mạng của bạn1. Cổng Internet cho phép các tài nguyên trong mạng con công cộng của bạn (chẳng hạn như phiên bản EC2) kết nối với Internet nếu tài nguyên có địa chỉ IPv4 công cộng hoặc địa chỉ IPv6. Tương tự, các tài nguyên trên Internet có thể bắt đầu kết nối đến các tài nguyên trong mạng con của bạn bằng địa chỉ IPv4 công cộng hoặc địa chỉ IPv62. Cổng internet cũng cung cấp mục tiêu trong bảng lộ trình VPC của bạn cho lưu lượng truy cập có thể định tuyến qua internet. Để liên lạc bằng IPv4, cổng internet cũng thực hiện dịch địa chỉ mạng (NAT). Để liên lạc bằng IPv6, NAT không cần thiết vì địa chỉ IPv6 là công khai2. Để cho phép truy cập vào hoặc từ internet cho các phiên bản trong mạng con trong VPC sử dụng cổng internet, bạn phải tạo một cổng internet và gắn nó vào VPC, thêm tuyến vào bảng tuyến của mạng con để hướng lưu lượng truy cập đến internet đến cổng internet, đảm bảo rằng các phiên bản trong mạng con của bạn có địa chỉ IPv4 công cộng hoặc địa chỉ IPv6, đồng thời đảm bảo rằng Network ACL và quy tắc Security Group cho phép lưu lượng truy cập internet mong muốn truyền đến và đi từ phiên bản của bạn2.', '[{"label": "A", "text_vi": "Để tạo kết nối VPN tới VPC", "is_correct": false, "analysis_vi": "Sai. Để tạo kết nối VPN tới VPC: Amazon VPC cho phép khởi tạo mạng ảo riêng biệt được cô lập logic trên đám mây AWS, kiểm soát toàn diện dải IP, subnet, bảng định tuyến và cổng mạng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Để cho phép liên lạc giữa VPC và internet", "is_correct": true, "analysis_vi": "Đúng. Để cho phép liên lạc giữa VPC và internet là đáp án chính xác. Cổng internet là một dịch vụ cho phép lưu lượng truy cập internet đi vào VPC."}, {"label": "C", "text_vi": "Để áp đặt các hạn chế về băng thông đối với lưu lượng truy cập internet", "is_correct": false, "analysis_vi": "Sai. Để áp đặt các hạn chế về băng thông đối với lưu lượng truy cập internet không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Để cân bằng tải lưu lượng truy cập từ internet trên các phiên bản Amazon EC2", "is_correct": false, "analysis_vi": "Sai. Để cân bằng tải lưu lượng truy cập từ internet trên các phiên bản Amazon EC2: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "Amazon VPC", "AWS Direct Connect", "AWS Storage Gateway"]'::jsonb, NOW())
ON CONFLICT (question_id) DO UPDATE SET
  question_vi = EXCLUDED.question_vi,
  domain = EXCLUDED.domain,
