  related_services = EXCLUDED.related_services,
  updated_at = NOW();

INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-93', 'practice_283', 'Một công ty có một ứng dụng có yêu cầu phần cứng mạnh mẽ. Ứng dụng này phải dành cho những sinh viên đang sử dụng máy tính xách tay nhẹ, giá rẻ. Dịch vụ AWS nào sẽ giúp công ty triển khai ứng dụng mà không cần đầu tư vào cơ sở hạ tầng phụ trợ hoặc phần cứng máy khách cao cấp?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Câu trả lời đúng là A vì Amazon AppStream 2.0 là dịch vụ sẽ giúp công ty triển khai ứng dụng mà không cần đầu tư vào cơ sở hạ tầng phụ trợ hoặc phần cứng máy khách cao cấp. Amazon AppStream 2.0 là dịch vụ truyền phát ứng dụng an toàn, được quản lý toàn phần, cho phép khách hàng truyền phát các ứng dụng máy tính để bàn từ AWS tới bất kỳ thiết bị nào chạy trình duyệt web. Amazon AppStream 2.0 xử lý việc cung cấp, thay đổi quy mô, vá lỗi và bảo trì cơ sở hạ tầng phụ trợ, đồng thời mang lại hiệu suất cao và trải nghiệm người dùng nhạy bén. Các tùy chọn khác không chính xác vì chúng không phải là dịch vụ giúp công ty triển khai ứng dụng mà không cần đầu tư vào cơ sở hạ tầng phụ trợ hoặc phần cứng máy khách cao cấp. AWS AppSync là dịch vụ cho phép khách hàng tạo các API linh hoạt để đồng bộ hóa dữ liệu trên nhiều nguồn dữ liệu. Amazon WorkLink là dịch vụ cho phép khách hàng cung cấp quyền truy cập an toàn, chỉ bằng một cú nhấp chuột vào các trang web và ứng dụng web nội bộ từ thiết bị di động. AWS Elastic Beanstalk là dịch vụ cho phép khách hàng triển khai và quản lý các ứng dụng web bằng các nền tảng phổ biến như Java, .NET, PHP và Node.js.', '[{"label": "A", "text_vi": "Amazon AppStream 2.0", "is_correct": true, "analysis_vi": "Đúng. Amazon AppStream 2.0 là đáp án chính xác. Câu trả lời đúng là A vì Amazon AppStream 2.0 là dịch vụ sẽ giúp công ty triển khai ứng dụng mà không cần đầu tư vào cơ sở hạ tầng phụ trợ hoặc phần cứng máy khách cao cấp."}, {"label": "B", "text_vi": "Đồng bộ hóa ứng dụng AWS", "is_correct": false, "analysis_vi": "Sai. Câu trả lời đúng là A vì Amazon AppStream 2.0 là dịch vụ sẽ giúp công ty triển khai ứng dụng mà không cần đầu tư vào cơ sở hạ tầng phụ trợ hoặc phần cứng máy khách cao cấp."}, {"label": "C", "text_vi": "Liên kết làm việc của Amazon", "is_correct": false, "analysis_vi": "Sai. Liên kết làm việc của Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "AWS Elastic Beanstalk", "is_correct": false, "analysis_vi": "Sai. AWS Elastic Beanstalk: AWS Elastic Beanstalk là dịch vụ PaaS cho phép lập trình viên tải mã nguồn lên và AWS tự động xử lý việc cấp phát máy chủ, cân bằng tải, tự động co giãn và giám sát. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Elastic Beanstalk"]'::jsonb, NOW())
