INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-94', 'practice_283', 'Một công ty thương mại điện tử muốn cung cấp các đề xuất sản phẩm phù hợp cho khách hàng của mình. Các đề xuất sẽ bao gồm các sản phẩm được mua thường xuyên cùng với các sản phẩm khác mà khách hàng đã mua. Các đề xuất cũng sẽ bao gồm các sản phẩm có màu sắc cụ thể và các sản phẩm từ thương hiệu yêu thích của khách hàng. Công ty nên sử dụng dịch vụ hoặc tính năng AWS nào để đáp ứng các yêu cầu này với nỗ lực phát triển ÍT NHẤT?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Amazon Personalize là dịch vụ cung cấp các đề xuất được cá nhân hóa theo thời gian thực dựa trên hành vi, sở thích và bối cảnh của người dùng. Nó cũng có thể kết hợp siêu dữ liệu như màu sắc sản phẩm và thương hiệu để tạo ra các đề xuất phù hợp hơn. Amazon Comprehend là dịch vụ xử lý ngôn ngữ tự nhiên (NLP) có thể phân tích văn bản để tìm các thực thể, cảm xúc, chủ đề, v.v. Dự báo của Amazon là dịch vụ cung cấp dự báo chuỗi thời gian chính xác dựa trên học máy. Amazon SageMaker Studio là môi trường phát triển tích hợp (IDE) dựa trên web dành cho machine learning.', '[{"label": "A", "text_vi": "Amazon Hiểu", "is_correct": false, "analysis_vi": "Sai. Amazon Hiểu không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Dự báo của Amazon", "is_correct": false, "analysis_vi": "Sai. Dự báo của Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Amazon Personalize", "is_correct": true, "analysis_vi": "Đúng. Amazon Personalize là đáp án chính xác. Amazon Personalize là dịch vụ cung cấp các đề xuất được cá nhân hóa theo thời gian thực dựa trên hành vi, sở thích và bối cảnh của người dùng."}, {"label": "D", "text_vi": "Studio Amazon SageMaker", "is_correct": false, "analysis_vi": "Sai. Studio Amazon SageMaker không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
