INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-95', 'practice_283', 'Kiểm tra viên cần tìm hiểu xem một dịch vụ AWS cụ thể có tuân thủ các khuôn khổ tuân thủ cụ thể hay không. Dịch vụ AWS nào sẽ cung cấp thông tin này?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'AWS Artifact là dịch vụ sẽ cung cấp thông tin về việc liệu một dịch vụ AWS cụ thể có tuân thủ các khuôn khổ tuân thủ cụ thể hay không. AWS Artifact là một cổng thông tin tự phục vụ cho phép bạn truy cập, xem xét và tải xuống các báo cáo cũng như thỏa thuận về bảo mật và tuân thủ của AWS. Bạn có thể sử dụng AWS Artifact để xác minh trạng thái tuân thủ của các dịch vụ AWS trên nhiều khu vực và chương trình tuân thủ khác nhau, chẳng hạn như ISO, PCI, SOC, FedRAMP, HIPAA, v.v.12', '[{"label": "A", "text_vi": "Hiện vật AWS", "is_correct": true, "analysis_vi": "Đúng. Hiện vật AWS là đáp án chính xác. AWS Artifact là dịch vụ sẽ cung cấp thông tin về việc liệu một dịch vụ AWS cụ thể có tuân thủ các khuôn khổ tuân thủ cụ thể hay không."}, {"label": "B", "text_vi": "AWS Trusted Advisor", "is_correct": false, "analysis_vi": "Sai. AWS Trusted Advisor: AWS Trusted Advisor quét toàn bộ tài khoản AWS và đưa ra khuyến nghị tối ưu theo 5 trụ cột: Chi phí, Hiệu năng, Bảo mật, Khả năng chịu lỗi và Giới hạn dịch vụ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Nhiệm vụ bảo vệ của Amazon", "is_correct": false, "analysis_vi": "Sai. Nhiệm vụ bảo vệ của Amazon: Amazon GuardDuty là dịch vụ phát hiện mối đe dọa thông minh sử dụng máy học để liên tục phân tích VPC Flow Logs, CloudTrail Logs và DNS Logs. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "AWS Certificate Manager (ACM) (ACM)", "is_correct": false, "analysis_vi": "Sai. AWS Certificate Manager (ACM) (ACM) không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Trusted Advisor", "Amazon GuardDuty", "AWS Secrets Manager", "AWS Artifact"]'::jsonb, NOW())
